def compute_metric_from_chi(chi):
    """
    [P5a-MANIFOLD 2026-05-19] 从chi场构建度规张量（支持复数类型）
    
    当 ENABLE_MANIFOLD_STEERING=True 且流形已拟合时：
      使用黎曼测地线度规替代 I+0.01*randn 白噪声。
      g = g_0 + ε * pullback(χ, v_geodesic)
    
    否则回退到原版白噪声度规。
    """
    device = chi.device
    dtype = chi.dtype
    is_complex = chi.is_complex()

    # [P5a] 尝试用黎曼流形操控构建度规
    try:
        enable_steering = bool(getattr(Config, 'ENABLE_MANIFOLD_STEERING', False))
    except Exception:
        enable_steering = False
    
    if enable_steering:
        try:
            steerer = get_manifold_steerer()
            # 注册当前 chi 到历史缓冲区
            steerer.register_chi(chi)
            # 每 10 步重新拟合 Mh
            if steerer.geodesic_step_count % 10 == 0 and len(steerer.chi_history) >= 10:
                steerer.fit_activation_manifold()
            # 用黎曼方法构建度规
            g = steerer.compute_riemann_metric(chi)
            if g is not None:
                return g
        except Exception as e:
            pass  # 静默回退到原版
    # (end P5a)

    # ========== 原版白噪声度规构建（回退路径） ==========
    # 简化的度规构建：基于chi的范数
    chi_norm = torch.norm(chi)
    
    # 构建35x35度规张量
    if is_complex:
        g = torch.eye(35, dtype=dtype, device=device)
        # randn does not support complex; build from real+imag
        noise_real = torch.randn(35, 35, dtype=chi.real.dtype, device=device)
        noise_imag = torch.randn(35, 35, dtype=chi.real.dtype, device=device)
        noise = torch.complex(noise_real, noise_imag)
    else:
        g = torch.eye(35, dtype=dtype, device=device)
        noise = torch.randn(35, 35, dtype=dtype, device=device)
    
    # 添加chi场的影响
    g += 0.01 * chi_norm * noise
    
    # 确保度规对称性（复数Hermitian）
    if is_complex:
        g = (g + g.transpose(-1, -2).conj()) / 2
    else:
        g = (g + g.T) / 2

    enable_bft = False
    try:
        enable_bft = bool(getattr(Config, 'ENABLE_BFT_GHOST_DECOUPLING', False))
    except Exception:
        enable_bft = False

    if enable_bft:
        try:
            eigenvals, eigenvecs = torch.linalg.eigh(g)
            g = apply_bft_ghost_decoupling(g, eigenvals, eigenvecs, M_geo=float(getattr(Config, 'M_GEO_DEFAULT', 10.0)))
            g = (g + g.T) / 2
        except Exception as e:
            print(f"[WARNING] BFT ghost decoupling failed: {e}")
    else:
        # 确保正定性
        eigenvals = torch.linalg.eigvalsh(g)
        min_eigenval = eigenvals.min()
        if min_eigenval <= 1e-12:
            g += torch.eye(35, dtype=dtype, device=device) * (1e-6 - min_eigenval)
    
    return g

def convert_to_sl6c_matrix(chi):
    chi_t = chi
    if not torch.is_tensor(chi_t):
        chi_t = torch.tensor(chi_t, device=Config.DEVICE if 'Config' in globals() else None)
    chi_flat = chi_t.reshape(-1)
    n = chi_flat.numel()
    if n < 36:
        pad = torch.zeros(36 - n, device=chi_flat.device, dtype=chi_flat.dtype)
        chi_flat = torch.cat([chi_flat, pad], dim=0)
    base = chi_flat[:36].reshape(6, 6)
    m = (base + base.transpose(-1, -2).conj()) / 2
    tr = torch.trace(m)
    m = m - (tr / 6.0) * torch.eye(6, device=m.device, dtype=m.dtype)
    return m

def compute_phase_signature_constraint(evals):
    """
    [P0-FIX 2026-05-18] 六维流形相签名约束 — 替代尼可马库斯对偶。

    第一性原理推导：
    SL(6,C) 作用在 6 维复空间 = 12 维实空间。
    三大人相按 (空间维, 时间维) 签名分解：
      (3S+1T) 物质相 → 空间占位=3, 时间占位=1, w≈0
      (1S+3T) 黑洞相 → 空间占位=1, 时间占位=3, w≈1
      (2S+2T) 暗能量相 → 空间占位=2, 时间占位=2, w≈-1
    总守恒：ΣS = 6, ΣT = 6（SL(6,C) 全局约束）

    对 6×6 厄米矩阵特征值 {λ_i}，将其按模长分为三组，
    施加 (S,T) 签名约束：
      L_sig = γ_s · (|Σ_S - 6|² + |Σ_T - 6|²)
    其中 Σ_S, Σ_T 由各相特征值的空间/时间权重加权求和。

    参考：「六维流形时空宇宙演化全景图及模型算法总结20260330」
          第 88-107 行：三大时空相详细描述
    """
    n = evals.shape[0]  # n=6 for SL(6,C)
    if n < 6:
        return torch.tensor(0.0, device=evals.device, dtype=evals.dtype)

    evals_abs = torch.abs(evals)
    sorted_idx = torch.argsort(evals_abs, descending=True)
    
    # 按模长分为三组（对应三相）
    # 第1组(模最大): (1S+3T) 黑洞相 — 时间主导
    # 第2组(模中等): (3S+1T) 物质相 — 空间主导  
    # 第3组(模最小): (2S+2T) 暗能量相 — 均衡
    g1_idx = sorted_idx[:2]  # 黑洞相: 2个特征值
    g2_idx = sorted_idx[2:4]  # 物质相: 2个特征值
    g3_idx = sorted_idx[4:6]  # 暗能量相: 2个特征值
    
    # 各组的空间/时间权重 (从相签名推导)
    # (3S+1T): S_weight=3/4, T_weight=1/4
    # (1S+3T): S_weight=1/4, T_weight=3/4
    # (2S+2T): S_weight=1/2, T_weight=1/2
    phase_S_weights = torch.tensor([1/4, 3/4, 1/2], device=evals.device, dtype=evals.dtype)
    phase_T_weights = torch.tensor([3/4, 1/4, 1/2], device=evals.device, dtype=evals.dtype)
    
    # 加权求和 → 空间/时间总占位
    g1_sum = torch.sum(evals_abs[g1_idx])
    g2_sum = torch.sum(evals_abs[g2_idx])
    g3_sum = torch.sum(evals_abs[g3_idx])
    total_mass = g1_sum + g2_sum + g3_sum + 1e-12
    
    g1_frac = g1_sum / total_mass
    g2_frac = g2_sum / total_mass
    g3_frac = g3_sum / total_mass
    
    Sigma_S = g1_frac * phase_S_weights[0] * 6 + g2_frac * phase_S_weights[1] * 6 + g3_frac * phase_S_weights[2] * 6
    Sigma_T = g1_frac * phase_T_weights[0] * 6 + g2_frac * phase_T_weights[1] * 6 + g3_frac * phase_T_weights[2] * 6
    
    gamma_s = float(getattr(Config, 'PHASE_SIGNATURE_GAMMA', 1.0))
    L_sig = gamma_s * ((Sigma_S - 6.0) ** 2 + (Sigma_T - 6.0) ** 2)
    
    return L_sig


def compute_vev_thermodynamic_loss(chi, kappa_2=1.0, kappa_3=0.5, beta=0.1):
    """
    [P0-FIX 2026-05-18] VEV thermodynamic constraint loss.
    
    原版使用尼可马库斯对偶 Σk³=(Σk)² 作为约束——但此恒等式仅对
    自然数 {1,2,...,n} 成立，对任意矩阵特征值无数学保证。
    
    升级为基于 SL(6,C) 六维流形的相签名约束：
      - 三大时空相各有确定 (S,T) 签名
      - 全局守恒 ΣS=6, ΣT=6 由 SL(6,C) 结构保证
      - 暗能量状态方程 w≈-1 从 (2S+2T) 均衡签名自然导出
    
    保留项：V_conf (约束势) + V_rep (能级排斥)
    替换项：l_duality → L_signature (相签名约束)
    """
    try:
        if torch.isnan(chi).any() or torch.isinf(chi).any():
            chi_clean = torch.nan_to_num(chi, nan=0.0, posinf=1.0, neginf=-1.0)
            chi = chi_clean
        
        m = convert_to_sl6c_matrix(chi)
        m_h = (m + m.transpose(-1, -2).conj()) / 2
        
        n = m_h.shape[0]
        diag_perturb = torch.eye(n, device=m_h.device, dtype=m_h.real.dtype) * 1e-8
        if m_h.is_complex():
            diag_perturb = diag_perturb.to(dtype=m_h.dtype)
        m_h_reg = m_h + diag_perturb
        
        evals = torch.linalg.eigvalsh(m_h_reg).real
        trace_2 = torch.sum(evals ** 2)
        trace_3 = torch.sum(evals ** 3)
        v_conf = (kappa_2 * trace_2) - (kappa_3 * trace_3)
        v_rep = torch.zeros((), device=evals.device, dtype=evals.dtype)
        for i in range(evals.shape[0]):
            for j in range(i + 1, evals.shape[0]):
                diff = torch.abs(evals[i] - evals[j])
                v_rep = v_rep - (beta * torch.log(diff * diff + 1e-8))

        # ==== [P0-FIX] 六维流形相签名约束（替代尼可马库斯对偶）====
        l_signature = compute_phase_signature_constraint(evals)
        # ===========================================================

        result = v_conf + v_rep + l_signature
        
        if torch.isnan(result) or torch.isinf(result):
            return torch.tensor(0.0, device=chi.device, dtype=chi.real.dtype if chi.is_complex() else chi.dtype)
        return result
        
    except Exception as e:
        print(f"[WARNING] VEV thermodynamic loss (phase-signature) failed: {e}")
        return torch.tensor(0.0, device=chi.device, dtype=chi.real.dtype if chi.is_complex() else chi.dtype)


def get_rym_flow_drift(chi, tau=None):
    """Compute RYM flow drift via autograd (preserves gradient chain)."""
    chi_leaf = chi.detach().clone().requires_grad_(True)
    if tau is None or not torch.is_tensor(tau):
        tau_leaf = torch.tensor(0.0, device=chi_leaf.device, dtype=torch.float64, requires_grad=True)
    else:
        tau_leaf = tau.detach().clone().requires_grad_(True)
    try:
        # Call residual with skip_safety=True to preserve gradient chain
        rym_res = get_rym_flow_residual(chi_leaf, tau_leaf, skip_safety=True)
        grad = torch.autograd.grad(rym_res, chi_leaf, retain_graph=False, create_graph=False, allow_unused=True)[0]
        if grad is None:
            grad = torch.zeros_like(chi_leaf)
        return grad
    except Exception as e:
        print(f"[WARNING] get_rym_flow_drift failed: {e}")
        return torch.zeros_like(chi_leaf)

# [P0-FIX 2026-05-18] 六维流形相签名偏差度 — 替代尼可马库斯对偶偏差
_LAST_PHASE_IMBALANCE = 0.0

def compute_phase_imbalance(chi):
    """
    [P0-FIX] 计算六维流形相签名偏差度。
    
    基于三大时空相的 (S,T) 签名约束：
      (3S+1T) 物质相, (1S+3T) 黑洞相, (2S+2T) 暗能量相
    全局守恒：ΣS=6, ΣT=6
    
    偏差度 = |Σ_S - 6|/(6+ε) + |Σ_T - 6|/(6+ε)
    0 = 完美三相平衡，2 = 完全失衡。
    
    供路径2(黑洞跨维泄漏)和路径3(动态CDM权重)共用。
    """
    try:
        m = convert_to_sl6c_matrix(chi)
        m_h = (m + m.transpose(-1, -2).conj()) / 2
        n = m_h.shape[0]
        diag_perturb = torch.eye(n, device=m_h.device, dtype=m_h.real.dtype) * 1e-8
        if m_h.is_complex():
            diag_perturb = diag_perturb.to(dtype=m_h.dtype)
        m_h_reg = m_h + diag_perturb
        evals = torch.linalg.eigvalsh(m_h_reg).real
        evals_abs = torch.abs(evals)
        
        sorted_idx = torch.argsort(evals_abs, descending=True)
        g1_idx = sorted_idx[:2]  # 黑洞相 (1S+3T)
        g2_idx = sorted_idx[2:4]  # 物质相 (3S+1T)
        g3_idx = sorted_idx[4:6]  # 暗能量相 (2S+2T)
        
        g1_sum = torch.sum(evals_abs[g1_idx])
        g2_sum = torch.sum(evals_abs[g2_idx])
        g3_sum = torch.sum(evals_abs[g3_idx])
        total_mass = g1_sum + g2_sum + g3_sum + 1e-12
        
        g1_frac = g1_sum / total_mass
        g2_frac = g2_sum / total_mass
        g3_frac = g3_sum / total_mass
        
        S_weights = torch.tensor([1/4, 3/4, 1/2], device=evals.device, dtype=evals.dtype)
        T_weights = torch.tensor([3/4, 1/4, 1/2], device=evals.device, dtype=evals.dtype)
        
        Sigma_S = g1_frac * S_weights[0] * 6 + g2_frac * S_weights[1] * 6 + g3_frac * S_weights[2] * 6
        Sigma_T = g1_frac * T_weights[0] * 6 + g2_frac * T_weights[1] * 6 + g3_frac * T_weights[2] * 6
        
        dev = (torch.abs(Sigma_S - 6.0) + torch.abs(Sigma_T - 6.0)) / 12.0
        return float(dev.item())
    except Exception:
        return 0.0


def compute_boundary_wzw_loss(chi, generators, k_level=None):
    """
    [P4-FIX 2026-05-18] SL(6,C) WZW 边界共形场论损失。
    
    问题：原代码仅实现了体侧（bulk）的里奇-杨-米尔斯流动力学，
    缺少边界 CFT——全息对偶只实现了一半，双侧不自洽。
    
    第一性原理：对于 bulk SL(6,C) Chern-Simons 理论，
    边界自然涌现为 SL(6,C) Wess-Zumino-Witten (WZW) 模型。
    
    作用量：
      S_WZW[g] = S_kinetic + S_WZ
      S_kinetic = (k/8π) ∫ d²x Tr(∂_μ g ∂^μ g^{-1})
      S_WZ      = (k/12π) ∫_B d³y ε^{ijk} Tr(g^{-1}∂_i g · g^{-1}∂_j g · g^{-1}∂_k g)
    
    其中 g ∈ SL(6,C) 是边界上的群值场，k 是 level（中心荷 c = k·dim(G)/(k+h^∨)）。
    
    本实现：
      - 从 chi 场构建边界群元 g = exp(χ^a T_a) （35 个生成元）
      - 计算 S_kinetic 的离散近似（有限差分）
      - 计算 S_WZ 的拓扑项（用结构常数 f_abc）
      - 边界损失 = 体作用量与边界作用量的差，驱动全息自洽
    
    参考：Witten, Commun. Math. Phys. 92, 455 (1984)
          「六维流形时空...」第 5-27 行：SL(6,C) 理论框架
    """
    try:
        device = chi.device
        dtype = chi.dtype
        is_complex = chi.is_complex()
        
        if k_level is None:
            k_level = float(getattr(Config, 'WZW_LEVEL', 1.0))
        
        # 1. 构建边界群元 g ∈ SL(6,C)
        chi_flat = chi.reshape(-1)
        n_gen = min(len(generators), chi_flat.numel())
        
        # 指数映射 g = exp(χ^a T_a)
        g = torch.eye(6, dtype=torch.complex128, device=device)
        for a in range(n_gen):
            coeff = chi_flat[a]
            T_a = generators[a].to(device=device, dtype=torch.complex128)
            g = g + coeff * T_a  # 一阶近似 (小场极限)
        
        # 确保 g ∈ SL(6,C): det(g) = 1
        det_g = torch.linalg.det(g)
        if abs(det_g) > 1e-12:
            g = g / (det_g ** (1.0/6.0))
        
        # 2. 动能项 S_kinetic = (k/8π) ∫ Tr(∂_μ g ∂^μ g^{-1})
        g_inv = torch.linalg.inv(g)
        
        # 用 chi 的相邻分量差分近似导数
        # ∂g/∂x^μ ≈ (g[μ+1] - g[μ-1]) / 2
        kinetic = torch.tensor(0.0, device=device, dtype=torch.float64)
        
        # 简化的动能项：用 chi 梯度替代 g 梯度
        if chi.numel() >= 3:
            # 用 chi 的相邻分量构造"空间导数"
            for mu in range(min(3, chi.numel() - 1)):
                dchi = chi_flat[mu + 1] - chi_flat[mu]
                dg = dchi * g  # ∂_μ g ≈ (∂_μ χ^a) T_a g
                term = torch.trace(dg @ g_inv @ dg.conj().T @ g_inv.conj().T)
                kinetic = kinetic + term.real
        
        S_kinetic = (k_level / (8.0 * math.pi)) * kinetic
        
        # 3. Wess-Zumino 项（拓扑项）
        # S_WZ = (k/12π) ∫ ε^{ijk} Tr(g^{-1}∂_i g · g^{-1}∂_j g · g^{-1}∂_k g)
        S_wz = torch.tensor(0.0, device=device, dtype=torch.float64)
        
        if chi.numel() >= 6:
            # 用结构常数 f_abc 构造 WZ 项的代数近似
            # g^{-1}∂g = dχ^a T_a (在李代数中)
            # ε^{ijk} f_abc χ^a χ^b χ^c
            for i in range(min(3, n_gen)):
                for j in range(i+1, min(4, n_gen)):
                    for k in range(j+1, min(5, n_gen)):
                        coeff_i = chi_flat[i].real if is_complex else chi_flat[i]
                        coeff_j = chi_flat[j].real if is_complex else chi_flat[j]
                        coeff_k = chi_flat[k].real if is_complex else chi_flat[k]
                        # Levi-Civita 符号: ε^{ijk}
                        epsilon = 1.0 if (j-i == 1 and k-j == 1) else (-1.0 if (i-j == 1 and j-k == 1) else 0.0)
                        if abs(epsilon) > 1e-12:
                            S_wz = S_wz + epsilon * coeff_i * coeff_j * coeff_k
        
        S_wz = (k_level / (12.0 * math.pi)) * S_wz
        
        # 4. 总边界作用量
        S_boundary = S_kinetic + S_wz
        
        # 5. 体作用量 proxy: 从 RYM 流残差估计
        # (实际应从 bulk 引力作用量计算，这里用 chi 范数 proxy)
        S_bulk_proxy = k_level * torch.norm(chi_flat).real ** 2 * 0.01
        
        # 6. 全息对偶损失: |S_boundary - S_bulk| (GKPW 关系)
        duality_gap = torch.abs(S_boundary.real - S_bulk_proxy.real)
        L_holographic = duality_gap / (torch.abs(S_boundary.real) + torch.abs(S_bulk_proxy.real) + 1e-12)
        
        if torch.isnan(L_holographic) or torch.isinf(L_holographic):
            return torch.tensor(0.0, device=device, dtype=torch.float64)
        
        return L_holographic.real
        
    except Exception as e:
        print(f"[WARNING] Boundary WZW loss failed: {e}")
        return torch.tensor(0.0, device=chi.device, dtype=torch.float64)

def langevin_sde_step(chi, A_tau_sqrt, dt, kappa_bh=0.01, j_trans=None, tau=None):
    """
    [P2-FIX 2026-05-18] Langevin SDE — 基于 Hawking 辐射率的黑洞信息泄漏。
    
    原版使用手动阈值 Θ_BH_Collapse=50.0 + sigmoid 压制因子——无物理推导。
    
    升级为基于半经典引力的 Hawking 辐射 + Page 曲线：
      - Hawking 温度: T_H = 1/(8πGM) (4D Schwarzschild)
      - 辐射功率: dM/dt = -α/M² (Stefan-Boltzmann 在 Hawking 温标下)
      - Page 时间: t_Page ~ M³ (信息开始泄漏的拐点)
      - 泄漏率: info_leak = tanh((t - t_Page)/τ_leak) · dM/dt
    
    对 (1S+3T) 黑洞相，有效质量由 chi 场模长 proxy：
      M_eff ∝ ||chi||  (在 1+3 签名下)
    黑洞坍缩 → 物质相特征值抑制 + 暗能量相面积补偿，
    保持六维流形全局 ΣS=6, ΣT=6 守恒。
    
    参考：「六维流形时空宇宙演化全景图及模型算法总结20260330」
          第 96-101 行：(1S+3T) 黑洞相描述
    """
    chi_t = chi.detach()
    is_complex = chi_t.is_complex()
    real_dtype = chi_t.real.dtype if is_complex else chi_t.dtype
    
    dt_f = float(dt)
    if not math.isfinite(dt_f):
        dt_f = 0.0
    dt_f = max(dt_f, 1e-12)
    dt_t = torch.tensor(dt_f, device=chi_t.device, dtype=real_dtype)
    
    dW_real = torch.randn_like(chi_t.real) if is_complex else torch.randn_like(chi_t)
    dW = torch.complex(dW_real, torch.randn_like(dW_real)) if is_complex else dW_real
    dW = dW * math.sqrt(dt_f)
    
    drift = -get_rym_flow_drift(chi_t, tau=tau)
    
    chi_req = chi_t.detach().clone().requires_grad_(True)
    try:
        v_topo = compute_vev_thermodynamic_loss(chi_req)
        pot_grad = torch.autograd.grad(v_topo, chi_req, retain_graph=False, create_graph=False, allow_unused=True)[0]
        if pot_grad is None:
            pot_grad = torch.zeros_like(chi_req)
    except Exception as e:
        print(f"[WARNING] VEV gradient failed (phase-signature mode): {e}")
        pot_grad = torch.zeros_like(chi_req)
    
    # ==== [P2-FIX] Hawking 辐射 + Page 曲线泄漏流 ====
    bh_feedback = torch.zeros_like(chi_t)

    if j_trans is not None:
        try:
            if torch.is_tensor(j_trans):
                jt = j_trans.to(device=chi_t.device, dtype=chi_t.dtype)
                chi_norm_val = torch.norm(chi_t).item()
                
                # 有效质量 M_eff ∝ ||chi|| (在 (1S+3T) 签名下)
                M_eff = max(chi_norm_val, 1e-6)
                
                # Hawking 温度: T_H = 1/M_eff (比例常数归一化)
                T_hawking = 1.0 / M_eff
                
                # 辐射功率按 Stefan-Boltzmann: dM/dt ∝ -T_H^4 · Area
                # Area ∝ M_eff^2 (4D), 所以 dM/dt ∝ -1/M_eff^2
                dM_dt_hawking = -1.0 / (M_eff * M_eff)
                
                # Page 时间: t_Page ∝ M_eff^3
                # 使用 chi 的相签名偏差作为内部演化"时钟"的 proxy
                phase_imb = compute_phase_imbalance(chi_t)
                t_page_proxy = M_eff ** 3 * (1.0 + phase_imb)
                
                # Page 曲线泄漏因子：在 t_Page 之前线性增长，之后趋近于 1
                # 用累计步数 proxy 替代真实时间（由外部传入的 j_trans 范数 proxy）
                t_eff = torch.norm(jt).item() * M_eff
                page_factor = 0.5 * (1.0 + math.tanh((t_eff - t_page_proxy) / max(t_page_proxy * 0.1, 1.0)))
                
                # 黑洞辐射功率（绝对值）用于反馈强度
                rad_power = abs(dM_dt_hawking) * page_factor
                
                # 当辐射功率超过阈值时触发维度转换
                rad_threshold = float(getattr(Config, 'HAWKING_RAD_THRESHOLD', 0.01))
                
                if rad_power > rad_threshold:
                    # ---- 黑洞辐射触发的维度转换 ----
                    # 压制物质相（3S+1T）的空间主导分量
                    chi_abs = torch.abs(chi_t)
                    _, collapse_idx = torch.topk(chi_abs.view(-1), k=min(3, chi_abs.numel()))
                    collapse_mask = torch.zeros_like(chi_t, dtype=torch.bool)
                    collapse_mask.view(-1)[collapse_idx] = True
                    
                    # 辐射压制因子：正比于 Hawking 辐射功率
                    suppress_factor = rad_power / (rad_power + 1.0)
                    bh_feedback += -kappa_bh * jt * suppress_factor * collapse_mask.float().to(chi_t.dtype)
                    
                    # 补偿至暗能量相 (2S+2T) — 保持总迹守恒
                    time_indices = torch.tensor([0, 1, 2], device=chi_t.device)
                    time_mask = torch.zeros_like(chi_t, dtype=torch.bool)
                    time_mask.view(-1)[time_indices % chi_t.numel()] = True
                    compensation = +kappa_bh * jt * suppress_factor * 0.5 * time_mask.float().to(chi_t.dtype)
                    bh_feedback += compensation
                else:
                    # 亚阈值：标准线性反馈
                    bh_feedback = kappa_bh * jt
        except Exception as e:
            print(f"[WARNING] Hawking-Page leak flow failed: {e}")
            bh_feedback = torch.zeros_like(chi_t)
    # ==================================================
    
    noise_term = dW
    if torch.is_tensor(A_tau_sqrt) and A_tau_sqrt.dim() >= 2 and chi_t.dim() == 1:
        if A_tau_sqrt.shape[-1] == chi_t.shape[0]:
            A_mat = A_tau_sqrt.to(device=chi_t.device, dtype=chi_t.dtype)
            noise_term = A_mat @ dW
    
    dt_t_c = dt_t.to(dtype=chi_t.dtype) if is_complex else dt_t
    chi_next = chi_t + (drift.to(dtype=chi_t.dtype) - pot_grad.to(dtype=chi_t.dtype) + bh_feedback) * dt_t_c + noise_term
    return chi_next.detach()


def identify_internal_time_dimensions(eigenvalues):
    ev = eigenvalues.real.reshape(-1)
    n = ev.numel()
    if n < 3:
        return []
    diffs = []
    for i in range(n):
        for j in range(i + 1, n):
            diffs.append((torch.abs(ev[i] - ev[j]), i, j))
    diffs.sort(key=lambda x: float(x[0].item()) if torch.is_tensor(x[0]) else float(x[0]))
    _, i0, j0 = diffs[0]
    return [i0, j0]

def apply_bft_ghost_decoupling(g_raw, eigenvalues, eigenvectors, M_geo):
    g_phys = g_raw.clone()
    idx_b = identify_internal_time_dimensions(eigenvalues)
    if not idx_b:
        return g_phys
    m_geo = torch.tensor(float(M_geo), device=g_raw.device, dtype=g_raw.dtype)
    decay = torch.exp(-(m_geo ** 2))
    for idx in idx_b:
        v = eigenvectors[:, idx].unsqueeze(1)
        proj = v @ v.transpose(0, 1)
        g_proj = proj * g_raw
        g_phys = g_phys - g_proj + (g_proj * decay)
    return g_phys

def compute_mode_energy_from_chi(chi, T):
    m = convert_to_sl6c_matrix(chi)
    t = T
    if t.shape != m.shape:
        return torch.zeros((), device=m.device, dtype=m.dtype)
    inner = torch.trace(t.transpose(-1, -2).conj() @ m)
    return (inner.real ** 2) + (inner.imag ** 2)

def compute_cdm_ratio_dynamic(chi, vev_eigenvalues, sl6c_generators, threshold=1e-3, M_geo_penalty=100.0):
    """
    [P0-FIX 2026-05-18] 动态 CDM 比例计算 — M_geo_dynamic(t) 绑定六维流形相签名偏差。
    
    修改要点：
      - 原绑定尼可马库斯对偶偏差 |Σk³-(Σk)²| → 现绑定相签名偏差 |Σ_S-6|+|Σ_T-6|
      - M_geo_dynamic(t) = 1.0 + α · phase_imbalance
      - 三相平衡 (ΣS=6,ΣT=6) → M_geo→1.0 → CDM 冻结归零
      - 相签名失衡 → M_geo↑ → 三维残馀析出为 CDM 纽结
      - 自然逼近 75:15 (5:1) 黄金比例
    
    参考：「六维流形时空宇宙演化全景图及模型算法总结20260330」
          第 129-131 行：75:15 暗物质与重子物质通道比例
    """
    global _LAST_PHASE_IMBALANCE
    alpha_dual = float(getattr(Config, 'DUALITY_ALPHA_DYNAMIC', 0.5))

    v = torch.diag(vev_eigenvalues.to(device=chi.device, dtype=chi.dtype))
    unbroken = torch.zeros((), device=chi.device, dtype=chi.dtype)
    broken = torch.zeros((), device=chi.device, dtype=chi.dtype)
    for T in sl6c_generators:
        try:
            comm = (T @ v) - (v @ T)
            comm_norm = torch.norm(comm).real
            mode_energy = compute_mode_energy_from_chi(chi, T)
            if float(comm_norm.item()) < float(threshold):
                unbroken = unbroken + mode_energy
            else:
                # ==== [P0-FIX] 相签名偏差动态权重（替代固定 M_geo_penalty）====
                phase_imb = compute_phase_imbalance(chi)
                _LAST_PHASE_IMBALANCE = phase_imb
                M_geo_dynamic = 1.0 + alpha_dual * phase_imb

                thr = torch.tensor(float(threshold), device=chi.device, dtype=comm_norm.dtype)
                denom = comm_norm + thr
                comm_scale = comm_norm / denom
                effective_penalty = 1.0 + (M_geo_dynamic - 1.0) * (comm_scale ** 2)
                broken = broken + (mode_energy * effective_penalty.to(dtype=chi.dtype))
                # =================================================
        except Exception:
            continue
    ratio = broken / (unbroken + torch.tensor(1e-12, device=chi.device, dtype=chi.dtype))
    try:
        return float(ratio.real.item())
    except Exception:
        return float(ratio)


def compute_gauge_field_from_chi(chi):
    """
    从chi场构建规范场A
    """
    device = chi.device
    dtype = chi.dtype
    
    # 简化的规范场构建：基于chi的梯度
    chi_expanded = torch.zeros(35, dtype=dtype, device=device)
    if chi.numel() >= 35:
        chi_expanded = chi.flatten()[:35]
    else:
        chi_expanded[:chi.numel()] = chi.flatten()
    
    # 构建规范场A
    A = torch.zeros(35, dtype=dtype, device=device)
    
    # 添加chi场的影响
    A += 0.1 * chi_expanded
    
    return A

def compute_christoffel_symbols(g):
    """
    计算度规的克里斯托费尔符号
    """
    device = g.device
    dtype = g.dtype
    dim = g.shape[0]
    
    # 计算度规的逆
    g_inv = torch.inverse(g)
    
    # 初始化克里斯托费尔符号
    Gamma = torch.zeros((dim, dim, dim), dtype=dtype, device=device)
    
    # 计算克里斯托费尔符号 Γ^k_{ij} = (1/2) g^{kl} (∂_i g_{jl} + ∂_j g_{il} - ∂_l g_{ij})
    for k in range(dim):
        for i in range(dim):
            for j in range(dim):
                for l in range(dim):
                    Gamma[k, i, j] += 0.5 * g_inv[k, l] * (
                        torch.autograd.grad(g[j, l], g, grad_outputs=torch.ones_like(g[j, l]), create_graph=True)[0][i] +
                        torch.autograd.grad(g[i, l], g, grad_outputs=torch.ones_like(g[i, l]), create_graph=True)[0][j] -
                        torch.autograd.grad(g[i, j], g, grad_outputs=torch.ones_like(g[i, j]), create_graph=True)[0][l]
                    )
    
    return Gamma

def compute_deturck_vector(g, Gamma, Gamma_background):
    """
    计算DeTurck向量场 W^j = g^{jk} g^{pq} (Γ^k_{pq} - Γ_background^k_{pq})
    """
    device = g.device
    dtype = g.dtype
    dim = g.shape[0]
    
    g_inv = torch.inverse(g)
    W = torch.zeros(dim, dtype=dtype, device=device)
    
    for j in range(dim):
        for k in range(dim):
            for p in range(dim):
                for q in range(dim):
                    W[j] += g_inv[j, k] * g_inv[p, q] * (Gamma[k, p, q] - Gamma_background[k, p, q])
    
    return W

def compute_lie_derivative(g, W):
    """
    计算向量场W关于度规g的李导数
    """
    device = g.device
    dtype = g.dtype
    dim = g.shape[0]
    
    L_W_g = torch.zeros_like(g)
    
    # 李导数 (L_W g)_{ij} = W^k ∂_k g_{ij} + g_{kj} ∂_i W^k + g_{ik} ∂_j W^k
    for i in range(dim):
        for j in range(dim):
            for k in range(dim):
                # W^k ∂_k g_{ij} 项
                grad_g_ij = torch.autograd.grad(g[i, j], g, grad_outputs=torch.ones_like(g[i, j]), create_graph=True)[0]
                L_W_g[i, j] += W[k] * grad_g_ij[k]
                
                # g_{kj} ∂_i W^k 项
                grad_W_k = torch.autograd.grad(W[k], g, grad_outputs=torch.ones_like(W[k]), create_graph=True)[0]
                L_W_g[i, j] += g[k, j] * grad_W_k[i]
                
                # g_{ik} ∂_j W^k 项
                L_W_g[i, j] += g[i, k] * grad_W_k[j]
    
    return L_W_g

def compute_ricci_tensor(Gamma):
    """
    计算里奇张量
    """
    device = Gamma.device
    dtype = Gamma.dtype
    dim = Gamma.shape[0]
    
    R = torch.zeros((dim, dim), dtype=dtype, device=device)
    
    # 里奇张量 R_{ij} = ∂_k Γ^k_{ij} - ∂_j Γ^k_{ik} + Γ^k_{ij} Γ^l_{kl} - Γ^k_{il} Γ^l_{kj}
    for i in range(dim):
        for j in range(dim):
            for k in range(dim):
                # ∂_k Γ^k_{ij} 项
                grad_Gamma_kij = torch.autograd.grad(Gamma[k, i, j], Gamma, grad_outputs=torch.ones_like(Gamma[k, i, j]), create_graph=True)[0]
                R[i, j] += grad_Gamma_kij[k]
                
                # -∂_j Γ^k_{ik} 项
                grad_Gamma_kik = torch.autograd.grad(Gamma[k, i, k], Gamma, grad_outputs=torch.ones_like(Gamma[k, i, k]), create_graph=True)[0]
                R[i, j] -= grad_Gamma_kik[j]
                
                for l in range(dim):
                    # Γ^k_{ij} Γ^l_{kl} 项
                    R[i, j] += Gamma[k, i, j] * Gamma[l, k, l]
                    
                    # -Γ^k_{il} Γ^l_{kj} 项
                    R[i, j] -= Gamma[k, i, l] * Gamma[l, k, j]
    
    return R

def compute_yang_mills_field_strength(A, f_abc):
    """
    计算杨-米尔斯场强张量 F_{μν} = ∂_μ A_ν - ∂_ν A_μ + g * f_{abc} A^b_μ A^c_ν
    """
    device = A.device
    dtype = A.dtype
    dim = A.shape[0]
    
    F = torch.zeros((dim, dim), dtype=dtype, device=device)
    
    for mu in range(dim):
        for nu in range(dim):
            # ∂_μ A_ν - ∂_ν A_μ 项
            grad_A_nu = torch.autograd.grad(A[nu], A, grad_outputs=torch.ones_like(A[nu]), create_graph=True)[0]
            grad_A_mu = torch.autograd.grad(A[mu], A, grad_outputs=torch.ones_like(A[mu]), create_graph=True)[0]
            F[mu, nu] += grad_A_nu[mu] - grad_A_mu[nu]
            
            # 非线性相互作用项 g * f_{abc} A^b_μ A^c_ν
            for a in range(35):
                for b in range(35):
                    for c in range(35):
                        # 简化的场强计算，使用结构常数
                        F[mu, nu] += 0.1 * f_abc[a, b, c] * A[b] * A[c]
    
    return F

def compute_modified_rym_flow(g, R_ij, L_W_g, F_mu_nu, alpha=1.0):
    """
    计算修正后的里奇-杨-米尔斯流残差
    """
    device = g.device
    dtype = g.dtype
    dim = g.shape[0]
    
    g_inv = torch.inverse(g)
    
    # 构建演化方程残差
    residual = torch.zeros_like(g)
    
    for i in range(dim):
        for j in range(dim):
            # dg/dt + 2*R_{ij} - (L_W g)_{ij} - 2*α*F_{ik}*F_{jl}*g^{kl}
            residual[i, j] = 2.0 * R_ij[i, j] - L_W_g[i, j]
            
            # 添加杨-米尔斯贡献
            for k in range(dim):
                for l in range(dim):
                    residual[i, j] -= 2.0 * alpha * F_mu_nu[i, k] * F_mu_nu[j, l] * g_inv[k, l]
    
    return residual

def compute_ricci_deturck_residual(g, A, Gamma_background, f_abc, alpha=1.0):
    """
    计算基于 DeTurck 规范固定的强抛物型里奇-杨-米尔斯流残差
    """
    # 计算当前度规的克里斯托费尔符号
    Gamma = compute_christoffel_symbols(g)
      
    # 引入 DeTurck 向量场 W 消除微分同胚简并性
    # W_j = g_{jk} g^{pq} (Gamma^k_{pq} - Gamma_background^k_{pq})
    W = compute_deturck_vector(g, Gamma, Gamma_background)
      
    # 计算 W 关于度规 g 的李导数
    L_W_g = compute_lie_derivative(g, W)
      
    R_ij = compute_ricci_tensor(Gamma)
    F_mu_nu = compute_yang_mills_field_strength(A, f_abc)
      
    # 修正后的演化方程残差 (dg_dt_target)
    # 目标为 0 = dg/dt + 2*R_ij - L_W_g - 2*alpha*F_ik*F_jl*g^kl
    residual = compute_modified_rym_flow(g, R_ij, L_W_g, F_mu_nu, alpha)
    return residual

def compute_sl6c_metric(chi, generators, f_abc):
    """
    基于SL(6,C)李代数生成元和结构常数计算度规张量
    """
    # 将chi场映射到李代数空间
    # chi的维度应该与生成元的数量匹配
    chi_expanded = torch.zeros(35, dtype=chi.dtype, device=chi.device)
    
    # 如果chi维度不足，进行填充或截断
    if chi.numel() >= 35:
        chi_expanded = chi.flatten()[:35]
    else:
        chi_expanded[:chi.numel()] = chi.flatten()
    
    # 构建度规张量 g_ij = δ_ij + f_ijk * chi^k
    # 这里使用简化的度规构造，确保非阿贝尔相互作用
    metric = torch.eye(35, dtype=chi.dtype, device=chi.device)
    
    # 添加非线性相互作用项
    for i in range(35):
        for j in range(35):
            # 计算结构常数贡献
            structure_contribution = torch.sum(f_abc[i, j, :] * chi_expanded)
            metric[i, j] += 0.1 * structure_contribution  # 控制相互作用强度
    
    # 确保度规的对称性和正定性
    metric = (metric + metric.T) / 2
    eigenvals = torch.linalg.eigvalsh(metric)
    min_eigenval = eigenvals.min()
    if min_eigenval <= 1e-12:
        metric += torch.eye(35, dtype=chi.dtype, device=chi.device) * (1e-6 - min_eigenval)
    
    return metric

def build_sl6c_algebra(device='cuda'):
    """
    精确构建 sl(6,C) 的 35 个复李代数生成元并计算结构常数
    """
    generators = []
    
    # 1. 构建 5 个 Cartan 子代数生成元 (对角矩阵，迹为 0)
    for i in range(5):
        H = torch.zeros((6, 6), dtype=torch.complex128, device=device)
        H[i, i] = 1.0
        H[i+1, i+1] = -1.0
        generators.append(H)
        
    # 2. 构建 15 个正根 (上三角) 和 15 个负根 (下三角)
    for i in range(6):
        for j in range(6):
            if i != j:
                E = torch.zeros((6, 6), dtype=torch.complex128, device=device)
                E[i, j] = 1.0
                generators.append(E)
                  
    T = torch.stack(generators)  # 形状: (35, 6, 6)
      
    # 预计算结构常数 f_abc
    # [T_a, T_b] = T_a T_b - T_b T_a
    # f_abc 可以通过求解线性方程组或基于 Killing 型的投影获得
    f_abc = torch.zeros((35, 35, 35), dtype=torch.complex128, device=device)
    for a in range(35):
        for b in range(35):
            comm = torch.matmul(T[a], T[b]) - torch.matmul(T[b], T[a])
            # 投影提取结构常数 (此处需基于标准内积展开，以最简点积为例)
            for c in range(35):
                norm_factor = torch.sum(T[c] * T[c])
                if norm_factor.abs() > 1e-12:  # 避免除零
                    f_abc[a, b, c] = -1j * torch.sum(comm * T[c]) / norm_factor
                  
    return T, f_abc

