class EvoAutoResearchController:
    def __init__(self, workspace_dir: str):
        if not _EVOSCIENTIST_AVAILABLE:
            print("[EvoScientist] Running in disabled mode - no strategy updates will be applied")
            self._agent = None
            self._thread_id = None
            self._program_md = ""
            self._disabled = True
            return
        
        try:
            self._agent = create_cli_agent(workspace_dir=workspace_dir)
            self._thread_id = f"ml-master-{int(time.time())}"
            self._program_md = ""
            try:
                program_path = os.path.join(_AUTORESEARCH_REPO_DIR, "program.md")
                with open(program_path, "r", encoding="utf-8") as f:
                    self._program_md = f.read()
            except Exception:
                self._program_md = ""
            self._disabled = False
            print("[EvoScientist] Controller initialized successfully")
        except Exception as e:
            print(f"[EvoScientist] Failed to initialize controller: {e}")
            self._agent = None
            self._thread_id = None
            self._program_md = ""
            self._disabled = True

    def propose_strategy_updates(self, cycle: int, metrics: dict, current_params: dict, context: dict) -> dict:
        if self._disabled or self._agent is None:
            return {}
            
        prompt = {
            "task": "Optimize training strategy for the running SPSGAN/CUDA spacetime simulation.",
            "cycle": cycle,
            "metrics": metrics,
            "current_params": current_params,
            "context": context,
            "autoresearch_program_md": self._program_md,
            "output_contract": {
                "type": "json",
                "schema": {
                    "pinn_lr": "number (optional)",
                    "manifold_lr": "number (optional)",
                    "manifold_loss_interval": "int (optional)",
                    "manifold_coupling_interval": "int (optional)",
                    "manifold_to_flow_alpha": "number (optional)",
                    "optimization_interval": "int (optional)",
                    "cosmic_validation_interval": "int (optional)",
                    "mcts_budget": "int (optional)",
                    "notes": "string (optional)"
                },
                "rules": "Return JSON only. Do not include markdown. Do not include code blocks."
            },
        }

        result_text = None
        try:
            out = self._agent.invoke(
                {"messages": [HumanMessage(content=json.dumps(prompt, ensure_ascii=False))]},
                config={"configurable": {"thread_id": self._thread_id}},
            )
            if isinstance(out, dict) and "messages" in out and out["messages"]:
                last_msg = out["messages"][-1]
                result_text = getattr(last_msg, "content", None)
            elif isinstance(out, str):
                result_text = out
        except Exception as e:
            print(f"[EvoScientist] Strategy update failed: {e}")
            result_text = None

        if not result_text or not isinstance(result_text, str):
            return {}

        try:
            parsed = json.loads(result_text)
            if isinstance(parsed, dict):
                return parsed
        except Exception as e:
            print(f"[EvoScientist] Failed to parse strategy response: {e}")
            return {}
        return {}


def _apply_strategy_updates(updates: dict, *, pinn_optimizer=None, manifold_optimizer=None, locals_ref: dict | None = None) -> dict:
    applied = {}
    if not updates or not isinstance(updates, dict):
        return applied

    if pinn_optimizer is not None and "pinn_lr" in updates:
        try:
            lr = float(updates["pinn_lr"])
            for pg in pinn_optimizer.param_groups:
                pg["lr"] = lr
            applied["pinn_lr"] = lr
        except Exception:
            pass

    if manifold_optimizer is not None and "manifold_lr" in updates:
        try:
            lr = float(updates["manifold_lr"])
            for pg in manifold_optimizer.param_groups:
                pg["lr"] = lr
            applied["manifold_lr"] = lr
        except Exception:
            pass

    if locals_ref is not None:
        for k in (
            "manifold_loss_interval",
            "manifold_coupling_interval",
            "manifold_to_flow_alpha",
            "optimization_interval",
            "cosmic_validation_interval",
            "mcts_budget",
        ):
            if k in updates:
                try:
                    locals_ref[k] = updates[k]
                    applied[k] = updates[k]
                except Exception:
                    pass

    return applied

