# ============================================================================
# 统一相位状态管理器 (2026年3月修复)
# ============================================================================

class UnifiedPhaseManager:
    """
    统一相位状态管理器 - 解决多系统相位不一致问题
    
    功能：
    1. 作为唯一权威的相位状态来源
    2. 统一相位命名约定
    3. 提供相位一致性检查
    4. 管理相位转换逻辑
    """
    
    # 统一相位映射表
    PHASE_MAPPING = {
        # ResearchPhase枚举 -> 标准字符串
        "QUANTUM_FOAM": "quantum_foam",
        "GEOMETRIC_CRYSTALLIZATION": "geometric_crystallization", 
        "MATTER_DOMINATED": "matter",
        "TOPOLOGICAL_TRANSITION": "topological_transition",
        "DARK_ENERGY_PHANTOM": "dark_energy_phantom",
        
        # 兼容性映射
        "HIGH_ENERGY_CHAOS": "quantum_foam",
        "PRE_INFLATION": "geometric_crystallization",
        "GEOMETRIC_INFLATION": "geometric_crystallization",
        "STABILIZATION": "matter",
        "BLACK_HOLE_FORMATION": "topological_transition",
        "DARK_ENERGY_DOMINATION": "dark_energy_phantom",
        "COSMIC_STABILITY": "matter",
        "INITIALIZATION": "quantum_foam",
        
        # SPSGAN映射
        "QUANTUM_FOAM": "quantum_foam",
        "MATTER": "matter",
        "BLACK_HOLE": "topological_transition",  # 映射黑洞到拓扑相变
        "DARK_ENERGY": "dark_energy_phantom",
        
        # 拓扑相位映射
        "3S+1T_Matter": "matter",
        "1S+3T_BlackHole": "topological_transition",
        "Chaotic_Spacetime_Phase": "quantum_foam",
        "1S+3T_BlackHole_or_Knot": "topological_transition"
    }
    
    def __init__(self):
        self.authoritative_phase = "quantum_foam"  # 权威相位状态
        self.phase_history = []
        self.inconsistency_count = 0
        self.last_consistency_check = 0

        self._prev_trace_phase = None
        self._hysteresis_counter = 0
        self._HYSTERESIS_REQUIRED = 5
        
    def get_authoritative_phase(self):
        """获取权威相位状态"""
        return self.authoritative_phase
    
    def set_authoritative_phase(self, phase, source="unknown"):
        """设置权威相位状态"""
        # 标准化相位名称
        normalized_phase = self.normalize_phase_name(phase)
        
        # 记录相位变化
        if normalized_phase != self.authoritative_phase:
            self.phase_history.append({
                'from': self.authoritative_phase,
                'to': normalized_phase,
                'source': source,
                'timestamp': time.time()
            })
            self.authoritative_phase = normalized_phase
            
        return self.authoritative_phase
    
    def normalize_phase_name(self, phase):
        """标准化相位名称"""
        if isinstance(phase, str):
            # 直接查找映射
            if phase in self.PHASE_MAPPING:
                return self.PHASE_MAPPING[phase]
            
            # 模糊匹配
            for key, value in self.PHASE_MAPPING.items():
                if phase.lower() in key.lower() or key.lower() in phase.lower():
                    return value
        
        # 默认返回量子泡沫相
        return "quantum_foam"
    
    def update_from_cosmic_time(self, cosmic_time):
        """基于宇宙时间更新权威相位"""
        if cosmic_time < 1e-35:
            phase = "QUANTUM_FOAM"
        elif cosmic_time < 1e-11:
            phase = "GEOMETRIC_CRYSTALLIZATION"
        elif cosmic_time < 1e17:
            phase = "MATTER_DOMINATED"
        else:
            phase = "DARK_ENERGY_PHANTOM"
        
        return self.set_authoritative_phase(phase, source="cosmic_time")
    
    def update_from_trace_A(self, trace_A):
        """基于trace_A值更新权威相位"""
        # 获取阈值常量 [SL6C-FRAMEWORK 2026-08-19] 统一从 Config 引用, 修复阈值传播断裂
        THETA_STABLE = Config.THETA_STABLE
        THETA_CRIT = Config.THETA_CRIT
        
        if trace_A > THETA_CRIT:
            detected = "QUANTUM_FOAM"
        elif trace_A > THETA_STABLE:
            detected = "GEOMETRIC_CRYSTALLIZATION"
        else:
            detected = "MATTER_DOMINATED"

        if self._prev_trace_phase is None:
            self._prev_trace_phase = detected
            self._hysteresis_counter = 0
            return self.set_authoritative_phase(detected, source="trace_A")

        if detected == self._prev_trace_phase:
            self._hysteresis_counter = 0
            return self.set_authoritative_phase(detected, source="trace_A")

        self._hysteresis_counter += 1
        if self._hysteresis_counter >= self._HYSTERESIS_REQUIRED:
            self._prev_trace_phase = detected
            self._hysteresis_counter = 0
            return self.set_authoritative_phase(detected, source="trace_A_hysteresis")

        return self.get_authoritative_phase()
    
    def check_consistency(self, other_phases):
        """检查相位一致性"""
        inconsistencies = []
        authoritative = self.get_authoritative_phase()
        
        for name, phase in other_phases.items():
            normalized = self.normalize_phase_name(phase)
            if normalized != authoritative:
                inconsistencies.append({
                    'system': name,
                    'phase': phase,
                    'normalized': normalized,
                    'expected': authoritative
                })
        
        if inconsistencies:
            self.inconsistency_count += 1
            print(f"[PHASE_WARNING] Detected {len(inconsistencies)} phase inconsistencies:")
            for inc in inconsistencies:
                print(f"  {inc['system']}: {inc['phase']} (expected: {inc['expected']})")
        
        return len(inconsistencies) == 0
    
    def get_phase_info(self):
        """获取当前相位详细信息"""
        return {
            'authoritative_phase': self.authoritative_phase,
            'phase_history_count': len(self.phase_history),
            'inconsistency_count': self.inconsistency_count,
            'last_transition': self.phase_history[-1] if self.phase_history else None
        }
    
    def sync_all_systems(self, sim):
        """同步所有系统的相位状态"""
        authoritative = self.get_authoritative_phase()
        
        # 同步主模拟器
        if hasattr(sim, 'current_phase'):
            sim.current_phase = authoritative
        
        # 同步快照
        if hasattr(sim, 'snapshot') and hasattr(sim.snapshot, 'current_phase'):
            # 将字符串转换为ResearchPhase枚举
            reverse_mapping = {v: k for k, v in self.PHASE_MAPPING.items() 
                             if k in ["QUANTUM_FOAM", "GEOMETRIC_CRYSTALLIZATION", 
                                    "MATTER_DOMINATED", "TOPOLOGICAL_TRANSITION", 
                                    "DARK_ENERGY_PHANTOM"]}
            
            if authoritative in reverse_mapping:
                enum_phase = reverse_mapping[authoritative]
                sim.snapshot.current_phase = type(sim.snapshot.current_phase)(enum_phase)
        
        # 同步SPSGAN
        if hasattr(sim, 'sps_gan') and hasattr(sim.sps_gan, 'current_phase'):
            sim.sps_gan.current_phase = authoritative
        
        # 同步流求解器
        if hasattr(sim, 'flow_solver') and hasattr(sim.flow_solver, 'current_phase'):
            sim.flow_solver.current_phase = authoritative
        
        print(f"[PHASE_SYNC] Synchronized all systems to: {authoritative}")

# 全局相位管理器实例
unified_phase_manager = UnifiedPhaseManager()

def get_cosmic_phase_name(cosmic_time):
    """基于宇宙时间获取相位名称（统一接口）"""
    return unified_phase_manager.update_from_cosmic_time(cosmic_time)

def sync_phase_state(sim):
    """同步所有系统相位状态"""
    return unified_phase_manager.sync_all_systems(sim)

def check_phase_consistency(sim):
    """检查相位一致性"""
    other_phases = {}
    
    # 收集各系统相位
    if hasattr(sim, 'snapshot') and hasattr(sim.snapshot, 'current_phase'):
        other_phases['snapshot'] = sim.snapshot.current_phase.value if hasattr(sim.snapshot.current_phase, 'value') else str(sim.snapshot.current_phase)
    
    if hasattr(sim, 'sps_gan') and hasattr(sim.sps_gan, 'current_phase'):
        other_phases['spsgan'] = sim.sps_gan.current_phase
        
    if hasattr(sim, 'flow_solver') and hasattr(sim.flow_solver, 'current_phase'):
        other_phases['flow_solver'] = sim.flow_solver.current_phase
        
    return unified_phase_manager.check_consistency(other_phases)

class ManifoldTensorMechanics(nn.Module):
    def __init__(self, geo_dim=70, vis_dim=15, dark_dim=75):
        super().__init__()
        # 几何生成元保留70维，但总系统自由度扩展为90维
        self.geo_dim = int(geo_dim)
        self.vis_dim = int(vis_dim)
        self.dark_dim = int(dark_dim)
        self.total_dim = self.vis_dim + self.dark_dim  # 90 DOF
        
        # 温斯坦稳定性硬钳位参数
        self.max_frobenius_norm = 10.0
        
        # [新增] 状态缓存用于delta_drift计算
        self.previous_chi_tensor = None

        # 核心几何张量 (70维，用于映射 sl(6,C))
        self.chi_tensor = nn.Parameter(
            (torch.randn(self.geo_dim, dtype=torch.complex128) * 0.01)
        )
          
        # 物质态张量分离：可见物质 (15) 与 暗物质影子扇区 (75)
        self.matter_tensor = nn.Parameter(
            (torch.randn(self.total_dim, dtype=torch.float64) * 0.01)
        )

        self.A_matrix = nn.Parameter(
            (torch.eye(self.geo_dim, dtype=torch.complex128) * 0.1)
        )
          
    def get_mass_ratio(self):
        # 强行锁定并输出质量均分比例
        return float(self.dark_dim) / float(self.vis_dim)  # 预期 5.0

    def get_hermitian_metric(self):
        chi = self.chi_tensor
        return torch.outer(chi, chi.conj())
    
    def compute_and_log_delta_drift(self, current_chi_tensor, dt_step):
        """
        计算基于 Eldan-Chen 随机流的几何漂移参数
        """
        if self.previous_chi_tensor is None:
            self.previous_chi_tensor = current_chi_tensor.detach().clone()
            return 0.0
          
        # 计算高维流形距离变动 (Frobenius 范数)
        drift_distance = torch.linalg.norm(current_chi_tensor - self.previous_chi_tensor)
        delta_drift_val = (drift_distance / (dt_step + 1e-8)).item()
          
        # 缓存当前步，供下一步使用
        self.previous_chi_tensor = current_chi_tensor.detach().clone()
        return delta_drift_val

    def get_hermitian_A(self):
        A = self.A_matrix
        return 0.5 * (A + A.conj().transpose(-2, -1))

    def map_to_sl6c_with_parity(self, chi_tensor: torch.Tensor, matter_tensor: torch.Tensor):
        """
        落实几何宇称 P_G = -1 的强制投影保护
        迫使影子扇区在李代数结构中具有奇宇称，防止其衰变
        """
        # chi_tensor: [..., 70], dtype=torch.complex128
        # matter_tensor: [..., 90], dtype=torch.float64
        
        vis_sector = matter_tensor[..., 0:15]   # 15维可见物质
        shadow_sector = matter_tensor[..., 15:90] # 75维影子扇区
        
        # 施加几何宇称 P_G = -1 的代数保护
        # 迫使影子扇区在李代数结构中具有奇宇称，防止其衰变
        parity_operator = torch.tensor(-1.0, dtype=matter_tensor.dtype, device=matter_tensor.device)
        protected_shadow = shadow_sector * parity_operator
        
        # 重组带有宇称标签的物质张量参与后续李代数映射
        protected_matter = torch.cat([vis_sector, protected_shadow], dim=-1)
        
        # 继续进行标准的无迹投影与 expm 矩阵指数映射
        generator = self.map_to_sl6c(chi_tensor)
        
        return generator, protected_matter

    def map_to_sl6c(self, chi_tensor):
        """
        将 70 维 chi_tensor 映射为 6x6 复矩阵生成元
        """
        batch_size = chi_tensor.shape[0] if chi_tensor.dim() > 1 else 1
        device = chi_tensor.device
        dtype = chi_tensor.dtype
        
        # 简化映射：将 70 维向量重塑为 6x6 矩阵的实部和虚部
        # 70 = 6*6 + 4 (额外维度用于复数信息)
        chi_flat = chi_tensor.view(-1)
        
        # 取前 36 个元素作为实部，后 36 个元素作为虚部（如果有的话）
        real_part = chi_flat[:36]
        imag_part = chi_flat[36:72] if chi_flat.numel() >= 72 else torch.zeros(36, device=device, dtype=dtype)
        
        # 重塑为 6x6 矩阵
        real_matrix = real_part.view(6, 6)
        imag_matrix = imag_part.view(6, 6)
        
        # 构造复矩阵
        base_generator = torch.complex(real_matrix, imag_matrix)
        
        return base_generator
    
    def safe_matrix_exp_with_wsc(self, traceless_generator):
        """
        带温斯坦稳定性约束 (WSC) 与双重防御钳位的李群指数映射
        """
        # 第一层防御：原有的动态缩放机制
        current_norm = torch.linalg.matrix_norm(traceless_generator, ord='fro')
        scale_factor = torch.clamp(self.max_frobenius_norm / (current_norm + 1e-8), max=1.0)
        scaled_generator = traceless_generator * scale_factor
        
        # [新增逻辑] 第二层防御：针对 chi_tensor 和生成元的绝对物理势垒钳位
        # 根据六维理论将截断限制在保证鬼态解耦的合理范围内
        safe_potential_limit = 10000.0
        clamped_generator = torch.clamp(scaled_generator, min=-safe_potential_limit, max=safe_potential_limit)
        
        # 将此 clamped_generator 结果反馈更新给 chi_tensor (确保 CSV 记录的是钳位后的安全数值)
        self.chi_tensor.data = torch.clamp(self.chi_tensor.data, min=-safe_potential_limit, max=safe_potential_limit)
        
        # 执行指数映射
        A_matrix = torch.matrix_exp(clamped_generator)
        return A_matrix
    
    def forward(self, chi_tensor=None, effective_temperature=1.0):  
        """
        基于 sl(6,C) 李代数的度规生成机制，新增威克转动动力学
        """
        if chi_tensor is None:
            chi_tensor = self.chi_tensor
        
        # chi_tensor [batch_size, 70] 需映射为复数生成元矩阵  
        batch_size = chi_tensor.shape[0] if chi_tensor.dim() > 1 else 1
          
        # 映射为 6x6 复矩阵生成元  
        base_generator = self.map_to_sl6c(chi_tensor)
          
        # 新增：动态威克转动 W(tau) 算符
        # effective_temperature 从 1.0 (极早期) 降至 0.0 (相变后)
        # theta 从 0 平滑过渡到 pi/2
        theta = (1.0 - effective_temperature) * (math.pi / 2.0)
          
        # 构造威克转动时间子空间相角矩阵 (对角线时间轴旋转)
        wick_phase = torch.tensor([[1j if i==0 else 1 for i in range(6)]],   
                                  dtype=torch.complex128, device=chi_tensor.device)
        W_tau = torch.exp(1j * theta * wick_phase)
        base_generator = base_generator * W_tau
          
        # 1. 强制无迹性投射 (Trace = 0) 确保 sl(6,C) 代数结构  
        trace = torch.trace(base_generator) / batch_size if batch_size > 1 else torch.trace(base_generator)
        identity = torch.eye(6, dtype=torch.complex128, device=chi_tensor.device)
        traceless_generator = base_generator - (trace / 6.0) * identity
        
        # 使用新的WSC方法进行安全的矩阵指数映射
        A_matrix = self.safe_matrix_exp_with_wsc(traceless_generator)
        
        return A_matrix

# ========================================================================
# [P5-MANIFOLD 2026-05-19] ManifoldSteeringCoupler
# 基于 arXiv 2605.05115 (Goodfire AI / Stanford)
# 将 chi 场演化的度规构建从 I+0.01*randn 白噪声升级为
# UMAP 拟合的激活流形 Mh 上的 pullback 度规
#
# 三层 pullback 桥接：
#   Mh (激活流形, 来自 chi 场历史) 
#    ↓ pullback f: Mh → My  
#   My (行为流形, 来自度规特征值)
#    ↓ pushforward to SL(6,C) moduli
#   SL(6,C) 模空间 (6×6 复矩阵生成元)
#
# 核心替换公式：
#   旧: g = I + 0.01*||χ||*randn          (白噪声扰动)
#   新: g = exp_map(χ_loc, v_geodesic)     (黎曼测地线扰动)
#   其中 χ_loc = UMAP.fit(chi_history).transform(χ_current)
#        v_geodesic = -ε * grad_{Mh} L(χ)   (测地线方向)
# ========================================================================
class ManifoldSteeringCoupler:
    """
    Mh↔My↔SL(6,C) 三层 pullback 桥接器。
    
    第一性原理：神经网络激活形成弯曲流形 Mh；
    自然行为沿 Mh 测地线展开；欧几里得操控切入非流形区域。
    本模块将这一原理注入 chi 场演化。
    """
    
    def __init__(self, dim_chi=70, dim_metric=35, history_size=None):
        self.dim_chi = dim_chi
        self.dim_metric = dim_metric
        self.history_size = history_size or getattr(Config, 'MANIFOLD_CHI_HISTORY_SIZE', 50)
        
        # chi 场历史环形缓冲区
        self.chi_history = []
        self.chi_history_max = self.history_size
        
        # UMAP 拟合状态
        self._umap_fitted = False
        self._umap_reducer = None
        self._chi_embedding = None       # 当前 chi 在 Mh 上的嵌入坐标
        self._tangent_basis = None       # 局部切空间基 (Mh)
        self._pullback_metric = None     # pullback 度规 f^*(g_My)
        
        # 累计测地线步数
        self.geodesic_step_count = 0
        
    def register_chi(self, chi_tensor: torch.Tensor):
        """
        将当前 chi 场注册到历史缓冲区。
        用于构造激活流形 Mh 的点云。
        """
        with torch.no_grad():
            chi_flat = chi_tensor.detach().cpu().reshape(-1)
            # 截取或填充到固定维度
            if chi_flat.shape[0] > self.dim_chi:
                chi_flat = chi_flat[:self.dim_chi]
            elif chi_flat.shape[0] < self.dim_chi:
                chi_flat = torch.cat([
                    chi_flat,
                    torch.zeros(self.dim_chi - chi_flat.shape[0])
                ])
            
            self.chi_history.append(chi_flat.numpy())
            while len(self.chi_history) > self.chi_history_max:
                self.chi_history.pop(0)
    
    def fit_activation_manifold(self) -> bool:
        """
        用 UMAP 拟合激活流形 Mh。
        返回 True 表示成功拟合，False 表示样本不足。
        """
        if len(self.chi_history) < 10:
            return False
        
        try:
            import numpy as np
            # 尝试导入 umap（如果已安装）
            try:
                import umap
            except ImportError:
                print("[MANIFOLD-STEER] UMAP not available, falling back to PCA approximation")
                return self._fit_pca_fallback()
            
            X = np.stack(self.chi_history, axis=0)  # (N, dim_chi)
            
            n_neighbors = getattr(Config, 'MANIFOLD_UMAP_N_NEIGHBORS', 15)
            min_dist = getattr(Config, 'MANIFOLD_UMAP_MIN_DIST', 0.1)
            
            # UMAP 拟合：2D 嵌入用于可视化+切空间估计
            n_components = min(5, X.shape[0] - 1, X.shape[1])
            if n_components < 2:
                n_components = 2
            
            self._umap_reducer = umap.UMAP(
                n_neighbors=min(n_neighbors, X.shape[0] - 1),
                min_dist=min_dist,
                n_components=n_components,
                metric='euclidean',
                random_state=42
            )
            self._chi_embedding = self._umap_reducer.fit_transform(X)
            self._umap_fitted = True
            
            # 估计局部切空间基（使用最近邻差分）
            self._estimate_tangent_basis()
            
            print(f"[MANIFOLD-STEER] Mh fitted: {X.shape[0]} points → "
                  f"{n_components}D embedding, tangent dim={self._tangent_basis.shape[1] if self._tangent_basis is not None else 'N/A'}")
            return True
            
        except Exception as e:
            print(f"[MANIFOLD-STEER] UMAP fitting failed: {e}, falling back to PCA")
            return self._fit_pca_fallback()
    
    def _fit_pca_fallback(self) -> bool:
        """
        PCA 降维作为 UMAP 的回退方案。
        计算主成分作为切空间的近似。
        """
        import numpy as np
        X = np.stack(self.chi_history, axis=0)
        X_centered = X - X.mean(axis=0, keepdims=True)
        
        try:
            # SVD 分解
            U, S, Vt = np.linalg.svd(X_centered, full_matrices=False)
            # 取前几个主成分作为切空间基
            n_components = min(5, len(S) - 1)
            self._tangent_basis = Vt[:n_components].T  # (dim_chi, n_components)
            self._chi_embedding = (X_centered @ self._tangent_basis)
            self._umap_fitted = True
            self._umap_reducer = None
            
            print(f"[MANIFOLD-STEER] PCA fallback: {n_components} components, "
                  f"explained var={np.sum(S[:n_components]**2)/np.sum(S**2):.3f}")
            return True
        except Exception as e:
            print(f"[MANIFOLD-STEER] PCA fallback also failed: {e}")
            return False
    
    def _estimate_tangent_basis(self):
        """
        从 UMAP 嵌入估计局部切空间基。
        使用当前 chi 的最邻近点在嵌入空间的差分方向。
        """
        import numpy as np
        if not self._umap_fitted or self._chi_embedding is None:
            return
        
        # 取最新 chi 的嵌入坐标
        chi_current_emb = self._chi_embedding[-1]
        
        # 找最近邻（在嵌入空间）
        dists = np.linalg.norm(self._chi_embedding - chi_current_emb, axis=1)
        k = min(6, len(dists) - 1)  # k 近邻
        if k < 2:
            return
        
        nn_idx = np.argsort(dists)[1:k+1]  # 排除自身
        
        # 近邻差分向量作为切空间基
        tangent_vecs = self._chi_embedding[nn_idx] - chi_current_emb
        
        # SVD 得到正交基
        try:
            U, S, Vt = np.linalg.svd(tangent_vecs, full_matrices=False)
            self._tangent_basis = Vt[:min(k, len(S))].T
        except Exception:
            self._tangent_basis = tangent_vecs.T  # 直接使用差分方向
    
    def compute_riemann_metric(self, chi: torch.Tensor) -> torch.Tensor:
        """
        [P5a 核心替代] 黎曼测地线度规构建。
        
        替代原 compute_metric_from_chi() 的 I+0.01*randn 白噪声。
        
        公式：g = g_0 + ε * pullback(χ_loc, v_geodesic)
        其中：
          - g_0 = 单位度规（平坦背景）
          - χ_loc = chi 在 Mh 嵌入坐标中的投影
          - v_geodesic = 沿 Mh 的测地线方向 = -grad_{Mh} L(χ)
          - pullback = f^*：将 Mh 扰动映射到 My 度规扰动
        
        Args:
            chi: (35,) 或 (70,) 复张量
        Returns:
            g: (35, 35) 厄米度规张量
        """
        device = chi.device
        dtype = chi.dtype
        is_complex = chi.is_complex()
        
        # 1. 基础平坦度规
        g0 = torch.eye(self.dim_metric, dtype=dtype, device=device)
        
        # 如果没有拟合好 Mh 或未启用，回退到原版
        enable_steering = getattr(Config, 'ENABLE_MANIFOLD_STEERING', False)
        if not enable_steering or not self._umap_fitted:
            # 回退到原版 compute_metric_from_chi 的逻辑
            chi_norm = torch.norm(chi)
            if is_complex:
                noise_real = torch.randn(self.dim_metric, self.dim_metric, dtype=chi.real.dtype, device=device)
                noise_imag = torch.randn(self.dim_metric, self.dim_metric, dtype=chi.real.dtype, device=device)
                noise = torch.complex(noise_real, noise_imag)
            else:
                noise = torch.randn(self.dim_metric, self.dim_metric, dtype=dtype, device=device)
            g = g0 + 0.01 * chi_norm * noise
            if is_complex:
                g = (g + g.transpose(-1, -2).conj()) / 2
            else:
                g = (g + g.T) / 2
            return g  # 原版逻辑
        
        # 2. 黎曼流形版本
        chi_detached = chi.detach()
        
        # 2a. 将 chi 投影到 Mh 的局部切空间
        chi_flat = chi_detached.reshape(-1).cpu()
        if chi_flat.shape[0] > self.dim_chi:
            chi_flat = chi_flat[:self.dim_chi]
        elif chi_flat.shape[0] < self.dim_chi:
            chi_flat = torch.cat([chi_flat, torch.zeros(self.dim_chi - chi_flat.shape[0])])
        
        # 使用 PCA 基 (tangent_basis) 做投影
        if self._tangent_basis is not None:
            import numpy as np
            chi_np = chi_flat.numpy()
            
            # 计算中心化（使用历史均值）
            if len(self.chi_history) > 0:
                history_mean = np.mean(np.stack(self.chi_history, axis=0), axis=0)
                chi_centered = chi_np - history_mean
            else:
                chi_centered = chi_np
            
            # 投影到切空间坐标
            tangent_coords = chi_centered @ self._tangent_basis  # (n_components,)
            tang_norm = np.linalg.norm(tangent_coords)
            
            # 2b. 从局部曲率估计调整扰动强度
            #    平坦区域→弱扰动，弯曲区域→强扰动
            eps = getattr(Config, 'MANIFOLD_GEODESIC_STEP_SIZE', 0.01)
            curvature_factor = 1.0 + 0.1 * np.log1p(tang_norm)  # 对数尺度防止爆炸
            
            # 2c. 构造 pullback 扰动
            #     扰动方向 = chi 在切空间的投影方向（测地线近似的 Darboux 坐标）
            pullback_strength = float(eps * curvature_factor * tang_norm)
            
            # 将扰动注入到度规矩阵
            if tang_norm > 1e-10:
                # 将切空间坐标映射回原始空间作为扰动方向
                perturb_direction = self._tangent_basis @ tangent_coords  # (dim_chi,)
                
                # 构建 (35,35) 扰动矩阵：从扰动方向构造反对称+对称部分
                perturb_vec = perturb_direction[:self.dim_metric]
                perturb_norm = np.linalg.norm(perturb_vec) + 1e-10
                perturb_unit = perturb_vec / perturb_norm
                
                # 构造低秩扰动：u·u^H（沿测地线方向的投影算符）
                perturb_unit_t = torch.tensor(perturb_unit, dtype=torch.float64, device=device)
                if is_complex:
                    perturb_unit_c = perturb_unit_t.to(dtype)
                    perturbation = pullback_strength * torch.outer(perturb_unit_c, perturb_unit_c.conj())
                else:
                    perturbation = pullback_strength * torch.outer(perturb_unit_t, perturb_unit_t)
                
                # 2d. 组合：g = g0 + pullback_perturbation
                g = g0 + perturbation.to(device)
            else:
                g = g0
        else:
            g = g0
        
        # 3. 确保对称性和正定性
        if is_complex:
            g = (g + g.transpose(-1, -2).conj()) / 2
        else:
            g = (g + g.T) / 2
        
        # 正定性修正
        eigenvals = torch.linalg.eigvalsh(g)
        min_eigenval = eigenvals.min()
        if min_eigenval <= 1e-12:
            g += torch.eye(self.dim_metric, dtype=dtype, device=device) * (1e-6 - min_eigenval)
        
        self.geodesic_step_count += 1
        return g
    
    def compute_geodesic_update(self, chi_grad: torch.Tensor, step_size: float = None) -> torch.Tensor:
        """
        [P5b 核心替代] 沿 Mh 测地线的参数更新方向。
        
        替代欧几里得梯度步: χ ← χ - η * ∇ L
        改为黎曼测地线步: χ ← exp_{χ}( -η * grad_{Mh} L )
        
        其中 grad_{Mh} L 是欧几里得梯度在 Mh 切空间上的投影。
        
        Args:
            chi_grad: 欧几里得梯度 (与 chi 相同 shape)
            step_size: 步长，默认从 Config 读取
        Returns:
            chi_update: 黎曼更新方向
        """
        if step_size is None:
            step_size = getattr(Config, 'MANIFOLD_GEODESIC_STEP_SIZE', 0.01)
        
        if not self._umap_fitted or self._tangent_basis is None:
            # 未拟合 → 回退到欧几里得更新
            return -step_size * chi_grad
        
        import numpy as np
        
        # 1. 将欧几里得梯度投影到 Mh 切空间
        grad_flat = chi_grad.detach().cpu().reshape(-1)
        if grad_flat.shape[0] > self.dim_chi:
            grad_flat = grad_flat[:self.dim_chi]
        elif grad_flat.shape[0] < self.dim_chi:
            grad_flat = torch.cat([grad_flat, torch.zeros(self.dim_chi - grad_flat.shape[0])])
        
        grad_np = grad_flat.numpy()
        
        # 投影：grad_Mh = T @ T^T @ grad（切空间投影算符）
        T = self._tangent_basis  # (dim_chi, n_components)
        grad_tangent = T @ (T.T @ grad_np)  # 在流形上的分量
        grad_normal = grad_np - grad_tangent  # 垂直于流形的分量（丢弃）
        
        # 2. 测地线步：沿切空间方向，但调整步长考虑曲率
        tang_norm = np.linalg.norm(grad_tangent)
        normal_norm = np.linalg.norm(grad_normal)
        
        # 曲率自适应步长：曲率大（法向分量大）→ 小步
        curvature_ratio = normal_norm / (tang_norm + 1e-8)
        adaptive_step = step_size / (1.0 + curvature_ratio)
        
        # 3. 构造更新方向
        geodesic_direction = -adaptive_step * grad_tangent
        
        update_tensor = torch.tensor(geodesic_direction, dtype=chi_grad.dtype, device=chi_grad.device)
        
        # 重塑为 chi_grad 的原始形状
        if update_tensor.numel() < chi_grad.numel():
            pad = torch.zeros(chi_grad.numel() - update_tensor.numel(), 
                            dtype=chi_grad.dtype, device=chi_grad.device)
            update_tensor = torch.cat([update_tensor, pad])
        update_tensor = update_tensor[:chi_grad.numel()].reshape(chi_grad.shape)
        
        return update_tensor
    
    def get_manifold_stats(self) -> dict:
        """返回流形操控统计信息"""
        return {
            'geodesic_steps': self.geodesic_step_count,
            'history_size': len(self.chi_history),
            'umap_fitted': self._umap_fitted,
            'tangent_dim': self._tangent_basis.shape[1] if self._tangent_basis is not None else 0,
            'method': 'UMAP' if self._umap_reducer is not None else ('PCA_fallback' if self._umap_fitted else 'not_fitted')
        }

# 全局流形操控实例（懒加载）
_manifold_steerer: ManifoldSteeringCoupler = None

def get_manifold_steerer() -> ManifoldSteeringCoupler:
    """获取或创建全局流形操控桥接器实例"""
    global _manifold_steerer
    if _manifold_steerer is None:
        _manifold_steerer = ManifoldSteeringCoupler(
            dim_chi=getattr(Config, 'DIM_REAL', 70),
            dim_metric=getattr(Config, 'DIM_COMPLEX', 35),
            history_size=getattr(Config, 'MANIFOLD_CHI_HISTORY_SIZE', 50)
        )
    return _manifold_steerer
    """检查相位一致性"""
    other_phases = {}
    
    # 收集各系统相位
    if hasattr(sim, 'snapshot') and hasattr(sim.snapshot, 'current_phase'):
        other_phases['snapshot'] = sim.snapshot.current_phase.value if hasattr(sim.snapshot.current_phase, 'value') else str(sim.snapshot.current_phase)
    
