def apply_adaptive_clamping(l_kls: torch.Tensor, matter_tensor: torch.Tensor):
    """
    将静态截断升级为"自适应局部方差钳位"
    使截断上限与暗物质影子扇区的局部方差动态挂钩
    """
    try:
        # 提取影子扇区计算局部方差
        if matter_tensor.shape[-1] >= 90:
            shadow_tensor = matter_tensor[..., 15:90]
        else:
            shadow_tensor = matter_tensor
            
        local_variance = torch.var(shadow_tensor, dim=-1, keepdim=True) # dtype=float64
        
        # 基础阈值设为 1e4，根据局部拓扑张力动态放大限幅天花板
        base_limit = 10000.0
        adaptive_max = base_limit * (1.0 + local_variance)
        
        # 安全地进行自适应钳位，既防溢出，又保留非微扰奇点梯度
        clamped_l_kls = torch.where(l_kls > adaptive_max, adaptive_max, l_kls)
        
        return clamped_l_kls
        
    except Exception as e:
        print(f"[WARNING] Adaptive clamping failed: {e}")
        # 回退到静态钳位
        return torch.clamp(l_kls, max=1e4)

def compute_topological_losses(A_matrix, chi_tensor, local_curvature=None, curvature_threshold=1e3, current_iteration=0, phase_transition_threshold=100):
    """
    更新后的拓扑损失与宇宙相位状态判定逻辑
    支持混沌时空相和常规相态转换
    """
    # 异常拦截
    if torch.isnan(A_matrix).any() or torch.isinf(A_matrix).any():
        print("[WARNING] NaN/Inf detected in A_matrix at function entry")
        return torch.tensor(0.0, device=A_matrix.device, dtype=A_matrix.dtype), \
               torch.tensor(0.0, device=A_matrix.device, dtype=A_matrix.dtype), \
               torch.tensor(1e-3, device=A_matrix.device, dtype=A_matrix.dtype), \
               "Chaotic_Spacetime_Phase"
    
    if torch.isnan(chi_tensor).any() or torch.isinf(chi_tensor).any():
        print("[WARNING] NaN/Inf detected in chi_tensor at function entry")
        return torch.tensor(0.0, device=chi_tensor.device, dtype=chi_tensor.dtype), \
               torch.tensor(0.0, device=chi_tensor.device, dtype=chi_tensor.dtype), \
               torch.tensor(1e-3, device=chi_tensor.device, dtype=chi_tensor.dtype), \
               "Chaotic_Spacetime_Phase"
    
    # [新增逻辑] 1. 第一次相变至第二次相变前的全纯对称期
    if current_iteration < phase_transition_threshold:
        # 此时度规处于 (3S+3T) 全秩状态，未发生自发破缺
        phase_flag = "Chaotic_Spacetime_Phase"
        
        # 返回基础几何流损失，不施加低能物质相的拓扑约束
        A_matrix_real = A_matrix.real if A_matrix.is_complex() else A_matrix
        A_matrix_real = A_matrix_real.to(dtype=torch.get_default_dtype())
        
        eigenvalues = torch.linalg.eigvals(A_matrix_real)
        sorted_eig, _ = torch.sort(eigenvalues.real, descending=False)
        
        # 获取行列式守恒损失  
        det_H = torch.linalg.det(A_matrix.real) if A_matrix.is_complex() else torch.linalg.det(A_matrix)
        l_det = torch.abs(det_H - 1.0).mean()
        
        # 混沌相的基础几何损失：保持全对称性
        loss_symmetry = torch.var(sorted_eig)  # 最小化特征值方差以保持对称
        l_kls = loss_symmetry + 10.0 * l_det
        
        # WSC和rank损失保持正常计算
        if torch.isnan(chi_tensor).any() or torch.isinf(chi_tensor).any():
            l_wsc = torch.tensor(0.0, device=chi_tensor.device, dtype=chi_tensor.dtype)
        else:
            chi_flat = chi_tensor.reshape(-1)
            l_wsc = torch.sqrt(torch.sum(chi_flat * chi_flat.conj())) * 0.01
            if torch.isnan(l_wsc) or torch.isinf(l_wsc):
                l_wsc = torch.tensor(0.0, device=chi_tensor.device, dtype=chi_tensor.dtype)
        
        if torch.isnan(A_matrix).any() or torch.isinf(A_matrix).any():
            l_rank = torch.tensor(1e-3, device=A_matrix.device, dtype=A_matrix.dtype)
        else:
            try:
                l_rank = torch.linalg.matrix_norm(A_matrix, ord='nuc')
            except Exception as e:
                l_rank = torch.tensor(1e-3, device=A_matrix.device, dtype=A_matrix.dtype)
        
        return l_kls, l_wsc, l_rank, phase_flag
    
    A_matrix_real = A_matrix.real if A_matrix.is_complex() else A_matrix
    A_matrix_real = A_matrix_real.to(dtype=torch.get_default_dtype())
      
    eigenvalues = torch.linalg.eigvals(A_matrix_real)
    sorted_eig, _ = torch.sort(eigenvalues.real, descending=False)
      
    # 获取行列式守恒损失  
    det_H = torch.linalg.det(A_matrix.real) if A_matrix.is_complex() else torch.linalg.det(A_matrix)
    l_det = torch.abs(det_H - 1.0).mean()

    # 拓扑路由分支机制 - 集成暗物质纽结检测
    if 'matter_tensor' in locals() or (hasattr(compute_topological_losses, 'matter_tensor') and compute_topological_losses.matter_tensor is not None):
        # 获取matter_tensor
        matter_tensor = getattr(compute_topological_losses, 'matter_tensor', None)
        if matter_tensor is not None:
            # 使用持久同调Betti数替代全局均值曲率判据
            has_knots, betti_1_count, betti_2_count = detect_dark_matter_knots(matter_tensor)
            
            if has_knots:
                phase_flag = "1S+3T_BlackHole_or_Knot"  # 触发拓扑重组
            else:
                phase_flag = "3S+1T_Matter"
        else:
            # 回退到传统曲率判据
            if local_curvature is not None and local_curvature.mean() > curvature_threshold:
                phase_flag = "1S+3T_BlackHole"
            else:
                phase_flag = "3S+1T_Matter"
    elif local_curvature is not None and local_curvature.mean() > curvature_threshold:  
        # --- 分支 A：触发 Bourgain 体积补偿 (1S+3T 黑洞相) ---  
        # 1. 空间坍缩为一维径向通道 (单态 a 为正，且受压)  
        loss_s1 = torch.relu(sorted_eig[-1] - 0.1).mean()   
        # ======================================================================  
        # [深度重构区]：修复黑洞相中的 Bourgain 体积守恒梯度陷阱  
        # 弃用 -torch.log，改用带硬件上限壁垒的 Softplus 反相形式  
        # ======================================================================  
        max_eig_val = 1e4  # 物理截断能标  
        clamped_eig = torch.clamp(torch.abs(sorted_eig[:3]), max=max_eig_val)  
        loss_t123 = -torch.mean(F.softplus(clamped_eig))   
        l_kls = loss_s1 + loss_t123 + 10.0 * l_det  
        phase_flag = "1S+3T_BlackHole"  
    else:  
        # --- 分支 B：常规 (3S+1T 物质相) ---  
        loss_t1 = torch.relu(sorted_eig[0] + 0.1).mean()     
        loss_t23 = torch.abs(sorted_eig[2] - sorted_eig[1]).mean()  
        loss_s123 = -torch.mean(torch.log(1.0 + torch.abs(sorted_eig[3:6])))  
        l_kls = loss_t1 + loss_t23 + loss_s123 + 10.0 * l_det  
        phase_flag = "3S+1T_Matter"  
        
    # 添加数值稳定性检查
    l_kls = NumericalStabilityManager.check_tensor_safety(l_kls, "l_kls", clamp_range=1e4)
    
    # 额外的 Inf/NaN 防护
    if torch.isinf(l_kls) or torch.isnan(l_kls):
        l_kls = torch.tensor(1e3, device=l_kls.device, dtype=l_kls.dtype)
        print("[WARNING] l_kls had Inf/NaN, clamped to 1e3")
    
    # 应用自适应局部方差钳位
    if 'matter_tensor' in locals() or (hasattr(compute_topological_losses, 'matter_tensor') and compute_topological_losses.matter_tensor is not None):
        matter_tensor = getattr(compute_topological_losses, 'matter_tensor', None)
        if matter_tensor is not None:
            l_kls = apply_adaptive_clamping(l_kls, matter_tensor)
        else:
            # 回退到静态钳位
            l_kls = torch.clamp(l_kls, max=1e4)
    else:
        # 回退到静态钳位
        l_kls = torch.clamp(l_kls, max=1e4)
        
    # 修复l_wsc计算 - 添加输入张量NaN检查
    if torch.isnan(chi_tensor).any() or torch.isinf(chi_tensor).any():
        print("[WARNING] NaN/Inf detected in chi_tensor, using zeros for l_wsc")
        l_wsc = torch.tensor(0.0, device=chi_tensor.device, dtype=chi_tensor.dtype)
    else:
        # 使用更稳定的范数计算
        chi_flat = chi_tensor.reshape(-1)
        l_wsc = torch.sqrt(torch.sum(chi_flat * chi_flat.conj())) * 0.01
        
        # 检查计算结果
        if torch.isnan(l_wsc) or torch.isinf(l_wsc):
            print("[WARNING] NaN detected in l_wsc, replacing with zeros")
            l_wsc = torch.tensor(0.0, device=chi_tensor.device, dtype=chi_tensor.dtype)
    
    l_wsc = NumericalStabilityManager.check_tensor_safety(l_wsc, "l_wsc", clamp_range=1e3)
    
    # 修复l_rank计算 - 添加A_matrix NaN检查
    if torch.isnan(A_matrix).any() or torch.isinf(A_matrix).any():
        print("[WARNING] NaN/Inf detected in A_matrix, using small value for l_rank")
        l_rank = torch.tensor(1e-3, device=A_matrix.device, dtype=A_matrix.dtype)
    else:
        # 使用更稳定的矩阵范数计算
        try:
            # 修复：确保矩阵范数计算使用实数
            if A_matrix.is_complex():
                A_real = A_matrix.real
            else:
                A_real = A_matrix
            l_rank = torch.linalg.matrix_norm(A_real, ord='nuc')
        except Exception as e:
            print(f"[WARNING] Matrix norm computation failed: {e}, using fallback")
            # 修复：使用一致的数据类型
            target_dtype = A_matrix.dtype if not A_matrix.is_complex() else torch.float32
            l_rank = torch.tensor(1e-3, device=A_matrix.device, dtype=target_dtype)
    
    l_rank = NumericalStabilityManager.check_tensor_safety(l_rank, "l_rank", clamp_range=1e3)
    
    # 增强的 rank 稳定性检查 - 更严格的钳位
    if torch.isinf(l_rank) or torch.isnan(l_rank) or l_rank > 1e3:
        # 修复：使用一致的数据类型，避免复数到实数的转换错误
        target_dtype = l_rank.dtype if not l_rank.is_complex() else torch.float32
        l_rank = torch.tensor(1e2, device=l_rank.device, dtype=target_dtype)
        print("[WARNING] l_rank had Inf/NaN or too large, clamped to 1e2")
    
    # 确保不会爆炸 - 更保守的钳位
    l_rank = torch.clamp(l_rank, max=1e3)
        
    return l_kls, l_wsc, l_rank, phase_flag

def get_rym_flow_residual(chi_tensor, tau, skip_safety=False):
    """
    计算RYM流残差，增强数值稳定性。
    skip_safety=True: 跳过holomorphic安全检查以保留梯度链（用于get_rym_flow_drift）。
    """
    try:
        # 输入验证和安全处理
        if torch.isnan(chi_tensor).any() or torch.isinf(chi_tensor).any():
            print("[WARNING] NaN/Inf detected in chi_tensor at function entry — sanitizing")
            chi_tensor = torch.nan_to_num(chi_tensor.clone(), nan=0.0, posinf=1.0, neginf=-1.0)
        
        chi_vec = chi_tensor.reshape(-1)
        
        # 使用全纯性保留方法处理复数张量（梯度模式下跳过以保留grad链）
        if chi_vec.is_complex() and not skip_safety:
            chi_safe = OptimizedNumericalStabilityManager.check_tensor_safety_holomorphic(
                chi_vec, step_count=0, m_geo_gap=1.0, dt=0.01
            )
        else:
            chi_safe = chi_vec
        
        # 计算H_pred，使用更稳定的方法
        if chi_safe.is_complex():
            H_pred = torch.outer(chi_safe, chi_safe.conj())
            if H_pred.is_complex():
                H_pred = H_pred.real
        else:
            H_pred = torch.outer(chi_safe, chi_safe)
        
        # Clamp large values in H_pred that cause overflow in the norm
        H_pred = torch.clamp(H_pred, min=-1e6, max=1e6)
        
        # 数值稳定性检查
        if torch.isnan(H_pred).any() or torch.isinf(H_pred).any():
            print("[WARNING] NaN/Inf in H_pred, using sanitized outer product")
            chi_clean = torch.nan_to_num(chi_safe, nan=0.0, posinf=1.0, neginf=-1.0)
            chi_clean = torch.clamp(chi_clean, min=-1e4, max=1e4)
            if chi_clean.is_complex():
                H_pred = torch.outer(chi_clean, chi_clean.conj()).real
            else:
                H_pred = torch.outer(chi_clean, chi_clean)
            H_pred = torch.clamp(H_pred, min=-1e6, max=1e6)
        
        # 计算Ricci张量
        Ricci_tensor = H_pred - torch.diag(torch.diag(H_pred))
        
        # 修复：确保Ricci张量是实数类型
        if Ricci_tensor.is_complex():
            Ricci_tensor = Ricci_tensor.real
        
        # 计算残差范数，使用更稳定的范数
        rym_residual = torch.linalg.norm(Ricci_tensor, ord='fro')
        
        # NaN/Inf check — when skip_safety=True (gradient mode), let NaN propagate
        # so get_rym_flow_drift's try/except can handle it consistently.
        # When skip_safety=False, safely clamp to a constant.
        if torch.isnan(rym_residual) or torch.isinf(rym_residual) or rym_residual > 1e3:
            if skip_safety:
                # In gradient mode, NaN means we can't compute a meaningful gradient.
                # Let it propagate so the caller can fall back to zero grad.
                rym_residual = rym_residual * 0.0 + 1e2  # preserve device/dtype, create usable fallback
            else:
                target_dtype = chi_tensor.dtype if not chi_tensor.is_complex() else torch.float32
                rym_residual = torch.tensor(1e2, device=chi_tensor.device, dtype=target_dtype)
                print("[WARNING] rym_residual had Inf/NaN or too large, clamped to 1e2")
        
        # 确保不会爆炸 - 更保守的钳位
        rym_residual = torch.clamp(rym_residual, min=1e-8, max=1e3)
        
        # 确保返回实数标量
        if rym_residual.is_complex():
            rym_residual = rym_residual.real
        
        return rym_residual
        
    except Exception as e:
        print(f"[ERROR] get_rym_flow_residual failed: {e}")
        return torch.tensor(1e2, device=chi_tensor.device, dtype=torch.float64)

def monitor_sgw_signatures(flow_residual_history, dt_array):
    """
    SGW 频域监控与多模态信号提取
    检测高频和低频引力波特征信号
    """
    import torch
    
    # flow_residual_history: 记录近期演化步长内的 get_rym_flow_residual 输出  
    # 转化为 PyTorch 兼容的频域张量进行梯度反传分析  
    if not torch.is_tensor(flow_residual_history):
        flow_residual_history = torch.tensor(flow_residual_history, dtype=torch.float32)
    
    if not torch.is_tensor(dt_array):
        dt_array = torch.tensor(dt_array, dtype=torch.float32)
    
    spectrum = torch.abs(torch.fft.fft(flow_residual_history))
    freqs = torch.fft.fftfreq(flow_residual_history.size(-1), d=dt_array.mean())
    
    # Type-I SGW 监控 (高频大统一相变)  
    high_freq_mask = (freqs > 400.0) & (freqs < 500.0)  # 对应 450 GHz 预设区间  
    type_i_power = torch.sum(spectrum[high_freq_mask])
    
    # Type-II SGW 监控 (低频几何急冷)  
    low_freq_mask = (freqs > 1.0) & (freqs < 2.5)  # 对应 1.71 Hz 预设区间  
    type_ii_power = torch.sum(spectrum[low_freq_mask])
    
    # 返回频域能量特征，可作为先验损失引导网络演化  
    return type_i_power, type_ii_power

def compute_ricci_curvature(A_matrix):
    """
    计算里奇张量标量曲率，用于拓扑分支判断
    基于度规张量的几何不变量
    """
    try:
        # 使用全纯性保留方法处理复数张量
        if A_matrix.is_complex():
            # 使用温斯坦稳定性硬钳位(WSC)保留全纯性，而非暴力截断
            A_safe = OptimizedNumericalStabilityManager.check_tensor_safety_holomorphic(
                A_matrix, step_count=0, m_geo_gap=1.0, dt=0.01
            )
            # 对于曲率计算，使用模长平方作为实值度量
            A_real = torch.abs(A_safe) ** 2
        else:
            A_real = A_matrix
            
        # 计算度规的逆
        A_inv = torch.inverse(A_real + 1e-6 * torch.eye(A_real.size(0), device=A_real.device))
        
        # 计算里奇张量的简化版本（标量曲率代理）
        # R = Tr(g^(-1) * ∇²g) 的离散近似
        laplacian_A = 0.0
        for i in range(A_real.size(0)):
            for j in range(A_real.size(1)):
                # 二阶导数的有限差分近似
                if i > 0 and i < A_real.size(0) - 1:
                    d2A_dx2 = A_real[i+1, j] - 2*A_real[i, j] + A_real[i-1, j]
                else:
                    d2A_dx2 = 0.0
                    
                if j > 0 and j < A_real.size(1) - 1:
                    d2A_dy2 = A_real[i, j+1] - 2*A_real[i, j] + A_real[i, j-1]
                else:
                    d2A_dy2 = 0.0
                    
                laplacian_A += d2A_dx2 + d2A_dy2
        
        # 标量曲率
        scalar_curvature = torch.trace(torch.mm(A_inv, laplacian_A * torch.eye_like(A_real)))
        
        # 取绝对值作为曲率强度指标
        curvature_magnitude = torch.abs(scalar_curvature)
        
        return curvature_magnitude
        
    except Exception as e:
        print(f"[WARNING] Ricci curvature computation failed: {e}")
        # 返回默认值
        return torch.tensor(0.0, device=A_matrix.device, dtype=A_matrix.dtype)

class CGICEDynamicsCoupler:  
    def __init__(self, eta_coupling=0.0046):  
        # eta_coupling 对应理论设定的 0.46% 黑洞转化率  
        self.eta_coupling = eta_coupling  
        self.global_rho_de = 0.0  # 初始暗能量密度

    def update_dark_energy_density(self, phase_flags_batch, delta_volume_bh, dt):  
        """  
        闭环动态哈勃演化反馈流: d(rho_DE)/dt = eta * d(V_BH)/dt  
        """  
        # 统计批次中触发 1S+3T 黑洞相变的体积增长率  
        bh_mask = [flag == "1S+3T_BlackHole" for flag in phase_flags_batch]  
        bh_fraction = sum(bh_mask) / len(phase_flags_batch) if phase_flags_batch else 0.0  
          
        # 将黑洞体积变化率转化为暗能量密度增量  
        d_rho_de = self.eta_coupling * (bh_fraction * delta_volume_bh / dt)  
        self.global_rho_de += d_rho_de  
          
        return self.global_rho_de

# 废弃原有的 compute_terminal_hubble_loss  
# def compute_terminal_hubble_loss(predicted_hubble_today, target_h0=67.42):  
#    ...

class GeometricInertiaTracker:  
    """  
    基于六维流形理论的几何动量追踪器，用于替代每25步的错误重置逻辑。  
    模拟 K-essence 场的哈勃阻尼与模空间几何惯性。  
    """  
    def __init__(self, beta_geo=0.99, alpha_kls=1.0, kappa_6=1.0):  
        self.beta_geo = beta_geo  
        self.alpha_kls = alpha_kls  
        self.kappa_6 = kappa_6  
        # 维持状态的连续记忆  
        self.chi_dot_squared_ema = 0.0  
        self.w_a_ema = 0.0
        self.w_ema = -1.0
        self.step_count = 0
          
    def update_and_get_bounds(self, w_pred, z_batch, current_H, current_rho_de):  
        """  
        利用网络当前输出和自动微分，更新几何惯性，并返回动态边界  
        """  
        # 1. 计算标量场对红移的导数 (模拟 \dot{\chi})  
        try:
            if (not isinstance(w_pred, torch.Tensor)) or (not isinstance(z_batch, torch.Tensor)):
                raise TypeError("w_pred and z_batch must be torch.Tensor")
            if (not w_pred.requires_grad) or (not z_batch.requires_grad):
                raise RuntimeError("w_pred/z_batch missing gradients")

            w_grad = torch.autograd.grad(
                outputs=w_pred.sum(),
                inputs=z_batch,
                create_graph=True,
                retain_graph=True
            )[0]  
            # 转换为对数标度导数  
            chi_dot_inst = w_grad * (1.0 + z_batch) * current_H   
        except Exception as e:
            print(f"[WARNING] Autograd failed in GeometricInertiaTracker: {e}")
            # 无法保证计算图连通时，返回零漂移的安全近似，避免 detach/clone 破坏上游梯度图
            chi_dot_inst = torch.zeros_like(z_batch, dtype=z_batch.dtype, device=z_batch.device)
          
        # 2. 连续动量累积，消除离散跳跃  
        inst_inertia = (chi_dot_inst ** 2).mean().item()  
        self.chi_dot_squared_ema = (self.beta_geo * self.chi_dot_squared_ema) + \
                                   ((1 - self.beta_geo) * inst_inertia)  
          
        # 3. 理论推导 w_a < 0 的瞬时值  
        R_moduli = 1.0  # 假设正截面曲率归一化  
        w_a_inst = - (R_moduli * self.chi_dot_squared_ema) / (self.kappa_6 * current_rho_de.item() + 1e-8)  
        self.w_a_ema = (self.beta_geo * self.w_a_ema) + ((1 - self.beta_geo) * w_a_inst)  
        
        # 4. 更新w的指数移动平均
        w_inst = w_pred.mean().item() if hasattr(w_pred, 'mean') else float(w_pred)
        self.w_ema = (self.beta_geo * self.w_ema) + ((1 - self.beta_geo) * w_inst)
          
        # 5. 根据 KLS 谱隙与全息压制计算动态下界  
        holographic_factor = (current_H.item() / 1e19)**2  # 1e19 简化代指普朗克能标  
        phantom_bound = -1.5 - (self.alpha_kls * holographic_factor * self.chi_dot_squared_ema)
        
        self.step_count += 1
          
        return phantom_bound, self.w_a_ema, self.w_ema
    
    def get_physics_residual_loss(self, w_pred, z_batch, current_H, current_rho_de):
        """
        计算物理残差损失，强制网络学习正确的演化规律
        """
        try:
            if (not isinstance(w_pred, torch.Tensor)) or (not isinstance(z_batch, torch.Tensor)):
                raise TypeError("w_pred and z_batch must be torch.Tensor")
            if (not w_pred.requires_grad) or (not z_batch.requires_grad):
                raise RuntimeError("w_pred/z_batch missing gradients")
            
            # 计算w对ln a的导数
            w_grad = torch.autograd.grad(outputs=w_pred.sum(), inputs=z_batch,
                                         create_graph=True, retain_graph=True)[0]
            dw_dln_a = w_grad * (1.0 + z_batch) * current_H
            
            # 理论预测的惯性项
            theoretical_inertia = -self.w_a_ema * w_pred  # 简化的理论预测
            
            # 物理残差
            residual = dw_dln_a - theoretical_inertia
            residual_loss = torch.mean(residual ** 2)
            
            return residual_loss
            
        except Exception as e:
            print(f"[WARNING] Physics residual loss calculation failed: {e}")
            # 若梯度链路断裂，返回0以避免产生“伪可微”叶子节点污染 NTK/反向传播
            return torch.zeros((), device=w_pred.device if isinstance(w_pred, torch.Tensor) else Config.DEVICE, dtype=w_pred.dtype if isinstance(w_pred, torch.Tensor) else torch.float32, requires_grad=False)

    def _compute_enhanced_physics_residual(self, w_pred, z_batch, current_H, current_rho_de):
        import torch

        w_mean = w_pred.mean()
        w_grad = torch.autograd.grad(
            outputs=w_mean,
            inputs=z_batch,
            create_graph=True,
            retain_graph=True,
            allow_unused=True,
        )[0]

        if w_grad is None:
            delta = 1e-6
            z_plus = z_batch + delta
            z_minus = z_batch - delta
            w_plus = w_pred + 0.0 * z_plus
            w_minus = w_pred + 0.0 * z_minus
            w_grad = (w_plus - w_minus) / (2.0 * delta)

        dw_dln_a = w_grad * (1.0 + z_batch) * current_H
        theoretical_inertia = (-self.w_a_ema) * w_pred
        residual = dw_dln_a - theoretical_inertia
        physics_loss = torch.mean(residual ** 2)

        stability = self._compute_stability_constraints(w_pred, z_batch, current_H, current_rho_de)
        return physics_loss + stability

    def _compute_enhanced_physics_loss(self, w_pred, z_batch, current_H, current_rho_de):
        import torch

        w_pred_safe = torch.nan_to_num(w_pred, nan=-1.0, posinf=0.5, neginf=-1.5)
        base = torch.mean((w_pred_safe + 1.0) ** 2)
        stability = self._compute_stability_constraints(w_pred_safe, z_batch, current_H, current_rho_de)
        return base + stability

    def _compute_stability_constraints(self, w_pred, z_batch, current_H, current_rho_de):
        import torch

        w_clamped = torch.clamp(w_pred, min=-1.5, max=0.5).detach()
        clamp_penalty = torch.mean((w_pred - w_clamped) ** 2)

        if w_pred.numel() > 1:
            diffs = w_pred[1:] - w_pred[:-1]
            smooth_penalty = torch.mean(diffs ** 2)
        else:
            smooth_penalty = torch.tensor(0.0, device=w_pred.device)

        rho_penalty = torch.tensor(0.0, device=w_pred.device)
        if torch.is_tensor(current_rho_de):
            rho_safe = torch.clamp(current_rho_de, min=1e-10)
            rho_penalty = torch.mean((torch.log10(rho_safe) + 10.0) ** 2) * 0.0

        return 0.5 * clamp_penalty + 0.1 * smooth_penalty + rho_penalty

# MD建议20260304-2：正则化的几何惯性追踪器
class OptimizedGeometricInertiaTracker:
    """
    修正的几何动量追踪器，修复除零奇点，通过可导的Log-Sum-Exp机制提供安全的下界
    """
    def __init__(self, kappa_6, alpha_kls=1.0, beta_geo=0.99):
        self.kappa_6 = kappa_6
        self.alpha_kls = alpha_kls
        self.beta_geo = beta_geo
        self.w_a_ema = 0.0
        self.chi_dot_squared_ema = 0.0
        self.w_ema = -1.0
        self.step_count = 0

    def update_and_get_bounds(self, w_pred, z_batch, current_H, current_rho_de):
        """
        利用网络当前输出和自动微分，更新几何惯性，并返回动态边界
        使用优化的稳定性计算方法
        """
        import torch
        
        # 1. 计算标量场对红移的导数 (模拟 \dot{\chi})
        try:
            if (not isinstance(w_pred, torch.Tensor)) or (not isinstance(z_batch, torch.Tensor)):
                raise TypeError("w_pred and z_batch must be torch.Tensor")
            if (not w_pred.requires_grad) or (not z_batch.requires_grad):
                raise RuntimeError("w_pred/z_batch missing gradients")

            w_mean = w_pred.mean()
            w_grad = torch.autograd.grad(
                outputs=w_mean,
                inputs=z_batch,
                create_graph=True,
                retain_graph=True,
                allow_unused=True
            )[0]
            if w_grad is None:
                w_grad = torch.zeros_like(z_batch)
            chi_dot_inst = w_grad * (1.0 + z_batch) * current_H
        except Exception as e:
            print(f"[WARNING] Autograd failed in OptimizedGeometricInertiaTracker: {e}")
            chi_dot_inst = torch.zeros_like(z_batch)
          
        # 2. 连续动量累积，消除离散跳跃（跨步状态必须为纯标量）
        inst_inertia = float((chi_dot_inst ** 2).mean().item())
        self.chi_dot_squared_ema = float(
            (self.beta_geo * float(self.chi_dot_squared_ema))
            + ((1 - self.beta_geo) * inst_inertia)
        )
          
        # 3. 使用优化的方法计算w_a
        R_moduli = 1.0  # 假设正截面曲率归一化  
        w_a_inst = self.calculate_w_a_stable(R_moduli, self.chi_dot_squared_ema, current_rho_de)
        self.w_a_ema = float(self.w_a_ema)
        
        # 4. 更新w的指数移动平均
        w_inst = float(w_pred.mean().item()) if hasattr(w_pred, 'mean') else float(w_pred)
        self.w_ema = float(
            (self.beta_geo * float(self.w_ema))
            + ((1 - self.beta_geo) * w_inst)
        )
          
        # 5. 根据 KLS 谱隙与全息压制计算动态下界  
        H_val = float(current_H.item()) if hasattr(current_H, "item") else float(current_H)
        holographic_factor = float((H_val / 1e19) ** 2)  # 1e19 简化代指普朗克能标
        phantom_bound = float(-1.5 - (self.alpha_kls * holographic_factor * float(self.chi_dot_squared_ema)))
        
        self.step_count = int(self.step_count) + 1
          
        # Return tensors on same device as w_pred to avoid device mismatch
        device = w_pred.device if isinstance(w_pred, torch.Tensor) else Config.DEVICE
        dtype = w_pred.dtype if isinstance(w_pred, torch.Tensor) else torch.float32
        phantom_bound_tensor = torch.tensor(phantom_bound, device=device, dtype=dtype)
        current_w_a_tensor = torch.tensor(self.w_a_ema, device=device, dtype=dtype)
        w_ema_tensor = torch.tensor(self.w_ema, device=device, dtype=dtype)
        return phantom_bound_tensor, current_w_a_tensor, w_ema_tensor

    def get_physics_residual_loss(self, w_pred, z_batch, current_H, current_rho_de):
        """
        计算物理残差损失，强制网络学习正确的演化规律
        使用优化的稳定性计算
        """
        import torch
        
        try:
            if (not isinstance(w_pred, torch.Tensor)) or (not isinstance(z_batch, torch.Tensor)):
                raise TypeError("w_pred and z_batch must be torch.Tensor")
            if (not w_pred.requires_grad) or (not z_batch.requires_grad):
                raise RuntimeError("w_pred/z_batch missing gradients")

            enhanced_residual_loss = self._compute_enhanced_physics_residual(w_pred, z_batch, current_H, current_rho_de)
            return enhanced_residual_loss

        except Exception as e:
            print(f"[WARNING] Physics residual loss calculation failed: {e}")
            if isinstance(w_pred, torch.Tensor):
                return torch.zeros((), device=w_pred.device, dtype=w_pred.dtype, requires_grad=False)
            return torch.zeros((), device=Config.DEVICE, dtype=torch.float32, requires_grad=False)

    def _compute_enhanced_physics_residual(self, w_pred, z_batch, current_H, current_rho_de):
        import torch

        w_mean = w_pred.mean()
        w_grad = torch.autograd.grad(
            outputs=w_mean,
            inputs=z_batch,
            create_graph=True,
            retain_graph=True,
            allow_unused=True,
        )[0]

        if w_grad is None:
            delta = 1e-6
            z_plus = z_batch + delta
            z_minus = z_batch - delta
            w_plus = w_pred + 0.0 * z_plus
            w_minus = w_pred + 0.0 * z_minus
            w_grad = (w_plus - w_minus) / (2.0 * delta)

        dw_dln_a = w_grad * (1.0 + z_batch) * current_H
        theoretical_inertia = (-self.w_a_ema) * w_pred
        residual = dw_dln_a - theoretical_inertia
        physics_loss = torch.mean(residual ** 2)

        stability = self._compute_stability_constraints(w_pred, z_batch, current_H, current_rho_de)
        return physics_loss + stability

    def _compute_enhanced_physics_loss(self, w_pred, z_batch, current_H, current_rho_de):
        import torch

        w_pred_safe = torch.nan_to_num(w_pred, nan=-1.0, posinf=0.5, neginf=-1.5)
        base = torch.mean((w_pred_safe + 1.0) ** 2)
        stability = self._compute_stability_constraints(w_pred_safe, z_batch, current_H, current_rho_de)
        return base + stability

    def _compute_stability_constraints(self, w_pred, z_batch, current_H, current_rho_de):
        """
        基于红移的动态非对称屏障约束
        强制晚期宇宙状态方程落入 Phantom 区域
        """
        import torch
        
        # 计算全息因子（极早期高能发散保护）
        H_val = float(current_H.item()) if hasattr(current_H, "item") else float(current_H)
        holographic_factor = float((H_val / 1e19) ** 2)  # 1e19 简化代指普朗克能标
        
        # 构建随红移 z 衰减的自适应上限，z->0 时上限逼近 -1.0  
        z_mean = z_batch.mean() if z_batch.numel() > 1 else z_batch
        dynamic_upper_bound = -1.0 + (z_mean / (z_mean + 1.0)) * 1.5
        
        # 单边非对称障碍罚函数，强制晚期宇宙状态方程落入 Phantom 区域  
        phantom_penalty = torch.relu(w_pred - dynamic_upper_bound).mean()
        
        # 结合 holographic_factor 提供极早期高能发散保护  
        quantum_gravity_suppression = holographic_factor * torch.relu(-w_pred - 2.0).mean()
        
        # 平滑惩罚保持原逻辑  
        if w_pred.numel() > 1:
            diffs = w_pred[1:] - w_pred[:-1]
            smooth_penalty = torch.mean(diffs ** 2)
        else:
            smooth_penalty = torch.tensor(0.0, device=w_pred.device)
        
        return phantom_penalty + quantum_gravity_suppression + 0.5 * smooth_penalty

    def calculate_w_a_stable(self, r_moduli, chi_dot_squared_ema, rho_de):
        """
        引入软下界防止暗能量密度穿越零点时导致惯性发散。
        """
        import torch
        import torch.nn.functional as F
        
        # 使用更保守的softplus参数，提供更稳定的下界
        if torch.is_tensor(rho_de):
            rho_de_tensor = rho_de
        else:
            # 如果rho_de是标量，转换为张量
            rho_de_tensor = torch.tensor(rho_de, dtype=torch.float32)

        safe_rho = F.softplus(self.kappa_6 * rho_de_tensor, beta=10.0) + 1e-4

        # 添加额外的数值稳定性检查（避免 tensor 直接用于 if 判断）
        safe_rho_val = safe_rho.item() if torch.is_tensor(safe_rho) and safe_rho.numel() == 1 else None
        if safe_rho_val is not None and safe_rho_val < 1e-6:
            safe_rho = torch.tensor(1e-6, dtype=safe_rho.dtype, device=safe_rho.device)

        # 计算w_a，但限制chi_dot_squared_ema的范围（确保 device 一致）
        chi_dot_tensor = torch.tensor(chi_dot_squared_ema, dtype=safe_rho.dtype, device=safe_rho.device)
        chi_dot_limited = torch.clamp(chi_dot_tensor, min=0.0, max=100.0)
        w_a_inst = - (r_moduli * chi_dot_limited) / safe_rho
        
        # 更严格的梯度软截断
        if torch.is_tensor(w_a_inst):
            w_a_inst = torch.clamp(w_a_inst, min=-2.0, max=2.0)
        else:
            w_a_inst = max(-2.0, min(2.0, w_a_inst))
        
        # 更新平滑 EMA，但限制变化幅度
        w_a_change = w_a_inst - self.w_a_ema
        if torch.is_tensor(w_a_change):
            w_a_change_limited = torch.clamp(w_a_change, min=-0.1, max=0.1)
        else:
            w_a_change_tensor = torch.tensor(w_a_change, dtype=torch.float32)
            w_a_change_limited = torch.clamp(w_a_change_tensor, min=-0.1, max=0.1)
        # 关键：跨步 EMA 必须是纯标量，禁止携带梯度图
        self.w_a_ema = float(self.w_a_ema) + float(w_a_change_limited.item())
        
        # 最终安全检查
        self.w_a_ema = max(-2.0, min(2.0, self.w_a_ema))
        
        return self.w_a_ema

# MD建议20260304-2：诱导(1+2+3)聚类的谱惩罚函数
def vev_clustering_loss(eigenvalues):
    """
    模拟Vandermonde斥力与三次Casimir势阱，引导系统落入(1+2+3)最优结构。
    传入的 eigenvalues 应为当前张量分解后的对数本征值张量。
    """
    import torch.nn.functional as F
    
    # 确保特征值降序排列
    lambda_sorted, _ = torch.sort(eigenvalues, descending=True)
    
    if lambda_sorted.size(0) < 6:
        return torch.tensor(0.0, device=eigenvalues.device)
        
    # 定义期望的三大簇：宏观时间(1), 内部信息时间(2), 宏观空间(3)
    # 聚类内部应当高度简并（方差趋近于0）
    cluster_2_var = torch.var(lambda_sorted[1:3])
    cluster_3_var = torch.var(lambda_sorted[3:6])
    
    # 模拟 SU(6) 李代数的三次 Casimir 不变量，提供势阱红利
    trace_cubic = torch.sum(lambda_sorted[:6] ** 3)
    
    # 损失目标：极小化簇内离散度，极大化非零的 Casimir 迹（即惩罚完全对称的虚假真空）
    # 权重系数 1e-3 调节几何张力与聚类约束的平衡
    clustering_penalty = cluster_2_var + cluster_3_var - 1e-3 * torch.abs(trace_cubic)
    
    return F.relu(clustering_penalty)

# MD建议20260303：统一的数值稳定性管理器
class NumericalStabilityManager:
    """统一的数值稳定性管理器，替代重复的NaN/Inf检查逻辑"""
    
    @staticmethod
    def check_tensor_safety(tensor, name="tensor", clamp_range=1e4, return_real=False):
        """统一的张量安全检查，支持复数类型，降低clamp_range防止数值爆炸"""
        if torch.is_complex(tensor):
            # 处理复数张量
            real_safe = NumericalStabilityManager._process_real_part(tensor.real, name, clamp_range)
            imag_safe = NumericalStabilityManager._process_real_part(tensor.imag, name, clamp_range)
            result = torch.complex(real_safe, imag_safe)
            if return_real:
                return result.real
            return result
        else:
            return NumericalStabilityManager._process_real_part(tensor, name, clamp_range)
    
    @staticmethod
    def _process_real_part(tensor, name, clamp_range):
        """处理实数张量"""
        if torch.isnan(tensor).any():
            print(f"[WARNING] NaN detected in {name}, replacing with zeros")
            tensor = torch.nan_to_num(tensor, nan=0.0, posinf=clamp_range, neginf=-clamp_range)
        
        if torch.isinf(tensor).any():
            print(f"[WARNING] Inf detected in {name}, clamping")
            tensor = torch.clamp(tensor, min=-clamp_range, max=clamp_range)
        
        return tensor
    
    @staticmethod
    def safe_stats(tensor, name="tensor"):
        """安全的统计信息计算"""
        try:
            if torch.is_complex(tensor):
                tensor = tensor.real
            mean_val = tensor.mean().item()
            std_val = tensor.std().item()
            min_val = tensor.min().item()
            max_val = tensor.max().item()
            return mean_val, std_val, min_val, max_val
        except (ValueError, RuntimeError) as e:
            print(f"[WARNING] Failed to compute stats for {name}: {e}")
            return 0.0, 0.0, 0.0, 0.0

# MD建议20260304-2：保留全纯性的张量净化机制
class OptimizedNumericalStabilityManager:
    """
    基于温斯坦稳定性约束(WSC)的优化数值稳定性管理器
    保留全纯函数的解析性，避免暴力.real截断
    """
    
    @staticmethod
    def check_tensor_safety_holomorphic(chi_tensor, step_count, m_geo_gap=1.0, dt=0.01):
        """
        利用温斯坦稳定性约束(WSC)动态压制复张量的虚部，替代暴力的.real截断，
        保留Lefschetz顶针积分所需的解析延拓能力。
        """
        if chi_tensor.is_complex():
            real_part = chi_tensor.real
            imag_part = chi_tensor.imag
            
            # 依据WSC，运用KLS谱隙引入物理指数衰减压制非因果虚部涨落
            # decay_factor ~ exp(- M_geo^2 * t)
            decay_factor = torch.exp(- (m_geo_gap ** 2) * dt * step_count)
            imag_part = imag_part * decay_factor
            
            # 重构全纯张量
            chi_tensor = torch.complex(real_part, imag_part)
        
        # 避免1e6的硬clamp破坏梯度，使用双曲正切平滑包裹，防止极点爆炸
        magnitude = torch.abs(chi_tensor)
        safe_magnitude = 1e6 * torch.tanh(magnitude / 1e6)
        
        # 维持原有的相位角度
        safe_chi = chi_tensor * (safe_magnitude / (magnitude + 1e-12))
        return safe_chi

# MD建议20260304-2：协方差矩阵的谱归一化
def update_covariance_stable(A_t, hessian_V, dt):
    """
    Riccati耗散方程的安全数值积分。
    包含谱归一化，防止负特征值平方后导致的 trace_A 爆炸。
    """
    # 显式欧拉步进： dA = - A * Hess * A - A^2
    dA = -torch.matmul(A_t, torch.matmul(hessian_V, A_t)) - torch.matmul(A_t, A_t)
    A_next = A_t + dt * dA
    
    # 强制对称性，消除浮点数累积误差
    A_next = 0.5 * (A_next + A_next.transpose(-2, -1))
    
    # 执行特征值分解 (适用于实对称矩阵)
    L, Q = torch.linalg.eigh(A_next)
    
    # 物理约束应用：消除导致发散的负特征值，并限制上限确保耗散
    # 保证协方差半正定，严格执行几何结晶
    L_clamped = torch.clamp(L, min=1e-8, max=1.0)
    
    # 重构稳定的协方差矩阵
    A_stable = torch.matmul(Q, torch.matmul(torch.diag_embed(L_clamped), Q.transpose(-2, -1)))
    
    return A_stable

class ChiTensorManager:
    """统一的chi张量管理器"""
    
    @staticmethod
    def get_safe_chi(flow_solver, step=None):
        """获取安全的chi张量"""
        chi_current = flow_solver.chi
        
        # 基本状态检查（降低输出频率）
        if step is None or step % 1000 == 0:  # 每1000步输出一次
            print(f"[DEBUG] Raw chi - shape: {chi_current.shape}, dtype: {chi_current.dtype}")
            print(f"[DEBUG] Raw chi contains NaN: {torch.isnan(chi_current).any()}")
            print(f"[DEBUG] Raw chi contains Inf: {torch.isinf(chi_current).any()}")
        
        # 类型转换
        if torch.is_complex(chi_current):
            if torch.isnan(chi_current).any() or torch.isinf(chi_current).any():
                chi_current = chi_current.real
            else:
                chi_current = chi_current.real.float()
        elif chi_current.dtype != torch.float32:
            chi_current = chi_current.float()
        
        # 数值稳定性处理 - 使用更严格的限制防止爆炸
        chi_current = NumericalStabilityManager.check_tensor_safety(chi_current, "chi_current", clamp_range=1e3)
        
        # 统计信息
        mean_val, std_val, min_val, max_val = NumericalStabilityManager.safe_stats(chi_current, "chi_current")
        print(f"[DEBUG] chi stats - mean: {mean_val:.6f}, std: {std_val:.6f}, "
              f"min: {min_val:.6f}, max: {max_val:.6f}")
        
        return chi_current

class LogManager:
    """统一的日志管理器"""
    
    @staticmethod
    def debug_nan(tensor, name):
        """调试NaN信息"""
