# MD建议20260301-1：VC-PINN架构实现
class VCPINNBranch(nn.Module):
    """
    VC-PINN 分支网络：专门用于逼近变系数 w(z) 和 G(step)
    基于MD建议20260301-1：解决标准PINN在处理变系数PDE时的维度不匹配和刚性失效问题
    """
    def __init__(self, input_dim=2, hidden_dim=128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(input_dim, hidden_dim).to(dtype=torch.get_default_dtype()),
            nn.Tanh(),  # VC-PINN推荐使用平滑激活函数
            nn.Linear(hidden_dim, hidden_dim).to(dtype=torch.get_default_dtype()),
            nn.Tanh(),
            nn.Linear(hidden_dim, 2).to(dtype=torch.get_default_dtype())  # 输出 [w, G]
        )
          
    def forward(self, z, step, geom_tracker=None, env_params=None):
        """
        前向传播 - 集成几何动量追踪器
        Args:
            z: 红移参数
            step: 时间步参数
            geom_tracker: GeometricInertiaTracker实例
            env_params: 环境参数字典，包含H, rho_de等
        Returns:
            w: 暗能量状态方程参数
            g: 引力常数
            w_a: 暗能量演化参数
        """
        # 修复：确保输入是实数类型
        if torch.is_complex(z):
            z = z.real
            print("[WARNING] VC-PINN received complex z input, using real part")
        if torch.is_complex(step):
            step = step.real
            print("[WARNING] VC-PINN received complex step input, using real part")
        
        # 输入归一化处理
        x = torch.cat([z, step], dim=-1)
        # 确保输入张量使用正确的数据类型
        x = x.to(dtype=torch.get_default_dtype())
        coeffs = self.net(x)

        step_val = None
        try:
            if torch.is_tensor(step):
                step_val = int(step.detach().flatten()[0].item())
            else:
                step_val = int(step)
        except Exception:
            step_val = None
        
        # 修复：检查coeffs是否为复数类型
        if torch.is_complex(coeffs):
            coeffs_real = coeffs.real.to(dtype=torch.get_default_dtype())
            coeffs_imag = coeffs.imag.to(dtype=torch.get_default_dtype())
        else:
            coeffs_real = coeffs.to(dtype=torch.get_default_dtype())
            coeffs_imag = torch.zeros_like(coeffs_real)
        
        # 提取原始w预测
        w_raw = coeffs_real[..., 0:1]
        g_raw = coeffs_real[..., 1:2]
        
        # 集成几何动量追踪器进行动态物理截断
        if geom_tracker is not None and env_params is not None:
            try:
                # 获取动态物理边界
                phantom_bound, current_w_a, w_ema = geom_tracker.update_and_get_bounds(
                    w_raw, z, env_params['H'], env_params['rho_de']
                )
                
                # 实施受理论保护的动态物理截断
                w_real = torch.clamp(w_raw, phantom_bound, 0.5)
                
                # CPL 参数化映射，强制网络输出符合大尺度几何属性
                scale_factor = 1.0 / (1.0 + z)
                w_cpl_enforced = -1.0 + current_w_a * (1.0 - scale_factor)
                
                # 使用残差融合策略，兼顾网络的局部灵活性与理论的宏观刚性
                w_final = 0.5 * w_real + 0.5 * w_cpl_enforced
                
                # G的动态截断（基于几何惯性）
                g_lower = 0.8 * (1.0 + 0.1 * geom_tracker.chi_dot_squared_ema)
                g_upper = 1.5 * (1.0 - 0.05 * geom_tracker.chi_dot_squared_ema)
                g_real = torch.clamp(g_raw, g_lower, g_upper)
                
                # 降低调试信息显示频率
                if step_val is not None and step_val % 50 == 0:
                    # 安全地处理float和tensor类型
                    phantom_val = phantom_bound.item() if hasattr(phantom_bound, 'item') else phantom_bound
                    g_lower_val = g_lower.item() if hasattr(g_lower, 'item') else g_lower
                    g_upper_val = g_upper.item() if hasattr(g_upper, 'item') else g_upper
                    w_ema_val = w_ema.item() if hasattr(w_ema, 'item') else w_ema
                    current_w_a_val = current_w_a.item() if hasattr(current_w_a, 'item') else current_w_a
                    
                    print(f"[DEBUG] Dynamic bounds: w∈[{phantom_val:.3f}, 0.5], G∈[{g_lower_val:.3f}, {g_upper_val:.3f}]")
                    print(f"[DEBUG] w_ema={w_ema_val:.6f}, w_a={current_w_a_val:.6f}")
                
                return w_final, g_real, current_w_a
                
            except Exception as e:
                print(f"[WARNING] GeometricInertiaTracker integration failed: {e}")
                # 回退到静态截断
                w_real = torch.clamp(w_raw, -1.5, 0.5)
                g_real = torch.clamp(g_raw, 0.8, 1.5)
                return w_real, g_real, 0.0
        else:
            # 回退到原始静态截断
            w_real = torch.clamp(w_raw, -1.5, 0.5)
            g_real = torch.clamp(g_raw, 0.8, 1.5)
            return w_real, g_real, 0.0

# MD建议20260301-1：NTK权重平衡器实现
class NTKWeightBalancer:
    """
    基于NTK启发式梯度统计的损失平衡器
    基于MD建议20260301-1：解决物理残差损失与初始条件损失之间的梯度量级差异
    """
    def __init__(self, moving_avg_beta=0.9):
        self.weights = {"physics": 1.0, "boundary": 1.0}
        self.weights_list = None
        self.beta = moving_avg_beta

    def update_weights(self, losses, shared_parameters=None, network_parameters=None):
        """\
        基于梯度迹/范数的自适应多任务平衡策略（MD建议20260306-2）。

        支持两种调用方式：
        1) update_weights([l_kls, l_wsc, l_rank, loss_physics, loss_boundary], params)
        2) update_weights(loss_physics, loss_boundary, params)  (兼容旧接口)
        """
        # New API: update_weights(losses_list, shared_parameters)
        if isinstance(losses, (list, tuple)):
            loss_list = list(losses)
            params = shared_parameters
        else:
            # Legacy API: update_weights(physics_loss, boundary_loss, network_parameters)
            physics_loss = losses
            boundary_loss = shared_parameters
            params = network_parameters
            loss_list = [physics_loss, boundary_loss]

        grad_norms = []
        for loss in loss_list:
            grad_norms.append(self._get_grad_norm(loss, params, retain_graph=True))

        norms = torch.tensor(
            grad_norms,
            device=loss_list[0].device if loss_list else Config.DEVICE,
            dtype=torch.float32
        )
        inv = 1.0 / (norms + 1e-8)
        w = torch.softmax(inv, dim=0)
        self.weights_list = w.detach().cpu().tolist()

        # backward-compatible dict update when physics/boundary exist
        if len(loss_list) >= 2:
            self.weights["physics"] = float(w[-2].detach().cpu().item())
            self.weights["boundary"] = float(w[-1].detach().cpu().item())

    def update_weights_legacy(self, physics_loss, boundary_loss, network_parameters):
        self.update_weights(physics_loss, boundary_loss, network_parameters)
              
    def _get_grad_norm(self, loss, network_parameters, retain_graph=True):
        """
        Safely computes the rigorous L2 norm of the gradients with respect to network parameters.
        Implements NaN shielding to prevent moving average corruption.
        """
        # Ensure the engine does not attempt to compute a backward pass on a corrupted loss scalar
        if torch.isnan(loss) or torch.isinf(loss):
            return 1.0  # Return strictly neutral norm to prevent downstream NaN contamination
        
        # 检查网络参数是否为空
        if not network_parameters or len(network_parameters) == 0:
            print("[WARNING] Autograd failed in NTKWeightBalancer: grad requires non-empty inputs.")
            return 1.0
        
        # 过滤出有效的参数（有梯度的参数）
        valid_parameters = [p for p in network_parameters if p is not None and p.requires_grad]
        if not valid_parameters:
            print("[WARNING] Autograd failed in NTKWeightBalancer: no valid parameters with gradients.")
            return 1.0
        
        # 确保损失有梯度
        if not loss.requires_grad:
            return 1.0  # silently skip non-gradient losses
        
        try:
            grads = torch.autograd.grad(
                loss,
                valid_parameters,
                create_graph=False,
                retain_graph=retain_graph,
                allow_unused=True
            )
            
            # 计算梯度范数
            grad_norm = 0.0
            for grad in grads:
                if grad is not None:
                    grad_norm += torch.sum(grad ** 2).item()
            
            grad_norm = math.sqrt(grad_norm)
            
            # 防止NaN或无穷大
            if torch.isnan(torch.tensor(grad_norm)) or torch.isinf(torch.tensor(grad_norm)):
                return 1.0
            
            return max(grad_norm, 1e-8)  # 防止除零
            
        except Exception as e:
            print(f"[WARNING] Autograd failed in NTKWeightBalancer: {e}")
            return 1.0

