    # 工具函数实现
    def _update_simulation_parameters(self, params: Dict[str, Any]):
        """更新模拟参数"""
        if hasattr(self.engine, 'update_simulation_parameters'):
            self.engine.update_simulation_parameters(params)
        else:
            # 直接设置引擎属性
            for key, value in params.items():
                if hasattr(self.engine, key):
                    setattr(self.engine, key, value)
        
        self.logger.info(f"Simulation parameters updated: {params}")
    
    def _save_checkpoint(self, step: int):
        """保存检查点"""
        if hasattr(self.engine, 'save_state'):
            self.engine.save_state(step)
        self.logger.info(f"Checkpoint saved at step {step}")
    
    def _trigger_tda_analysis(self, resolution: str = "STANDARD"):
        """触发TDA分析"""
        current_positions = getattr(self.engine, 'current_positions', None)
        if current_positions is not None:
            analyst = TopologyAnalyst()
            result = analyst._analyze_topology(current_positions)
            return result
        return {"error": "No position data available"}
    
    def _adjust_dark_energy(self, w: float = -1.0):
        """调整暗能量参数"""
        if hasattr(self.engine, 'flow_solver') and hasattr(self.engine.flow_solver, 'set_dark_energy_params'):
            self.engine.flow_solver.set_dark_energy_params(w=w)
        self.logger.info(f"Dark energy parameter adjusted to w={w}")
    
    def _get_current_metrics(self) -> Dict[str, Any]:
        """获取当前指标"""
        metrics = {}
        
        # 从引擎获取基础指标
        if hasattr(self.engine, 'get_current_metrics'):
            metrics = self.engine.get_current_metrics()
        else:
            # 提供默认指标
            metrics = {
                "ricci_mean": 0.0,
                "trace_A": 0.0,
                "step": getattr(self.engine, 'current_step', 0)
            }
        
        # 添加其他指标
        if hasattr(self.engine, 'flow_solver'):
            metrics["dark_energy_w"] = getattr(self.engine.flow_solver, 'w', -1.0)
        
        # AI优化时空演化代码建议20260224：添加动态暗能量参数
        if hasattr(self.engine, 'w_a_de'):
            metrics["dark_energy_wa"] = self.engine.w_a_de
        
        # AI优化时空演化代码建议20260224：添加时空相配分参数
        if hasattr(self.engine, 'phase_partitions'):
            metrics["phase_partitions"] = self.engine.phase_partitions
        
        # AI优化时空演化代码建议20260224：添加协方差矩阵迹细分参数
        if hasattr(self.engine, 'trace_A_matter'):
            metrics["trace_A_matter"] = self.engine.trace_A_matter
        if hasattr(self.engine, 'trace_A_bh'):
            metrics["trace_A_bh"] = self.engine.trace_A_bh
        if hasattr(self.engine, 'trace_A_de'):
            metrics["trace_A_de"] = self.engine.trace_A_de
        
        # 添加粒子位置数据用于拓扑分析
        if hasattr(self.engine, 'pos'):
            metrics["positions"] = self.engine.pos.clone().detach()  # 确保是张量副本
            print(f"[TOPOLOGY] Added positions data for dark matter detection: {metrics['positions'].shape}")
        else:
            print("[WARNING] No positions data available for topology analysis")
        
        return metrics
    
    def _modify_research_phase(self, phase: str):
        """修改研究阶段"""
        try:
            new_phase = ResearchPhase(phase)
            self.state.current_phase = new_phase
            self.logger.info(f"Research phase modified to: {phase}")
        except ValueError:
            self.logger.error(f"Invalid research phase: {phase}")
    
    def _save_world_state(self, filepath: str = None):
        """保存世界状态"""
        if filepath is None:
            filepath = f"world_state_{int(time.time())}.json"
        
        try:
            with open(filepath, 'w') as f:
                f.write(self.state.to_json())
            self.logger.info(f"World state saved to: {filepath}")
        except Exception as e:
            self.logger.error(f"Failed to save world state: {e}")
    
    def _update_config_snapshot(self):
        """更新配置快照"""
        config_snapshot = {}
        
        # 收集关键配置参数
        if hasattr(self.engine, 'adaptive_dt'):
            config_snapshot["adaptive_dt"] = self.engine.adaptive_dt
        
        if hasattr(self.engine, 'box_size'):
            config_snapshot["box_size"] = self.engine.box_size
        
        if hasattr(self.engine, 'n_particles'):
            config_snapshot["n_particles"] = self.engine.n_particles
        
        self.state.current_config = config_snapshot
    
    def should_run_cycle(self, step: int) -> bool:
        """判断是否应该运行编排周期"""
        return (step - self.last_cycle_step) >= self.cycle_interval
    
    def get_status(self) -> Dict[str, Any]:
        """获取编排器状态"""
        return {
            "cycle_count": self.cycle_count,
            "last_cycle_step": self.last_cycle_step,
            "current_phase": self.state.current_phase.value,
            "pending_tasks": len(self.state.planned_tasks),
            "completed_tasks": len(self.state.completed_tasks),
            "insights_count": len(self.state.insights),
            "novelty_events": len(self.state.novelty_events),
            "pending_tda_tasks": len(self.pending_tda_tasks),
            "research_objective": self.state.research_objective
        }
    
    def shutdown(self):
        """关闭编排器"""
        self.logger.info("Shutting down Cosmic Orchestrator")
        
        # 关闭线程池
        self.tda_executor.shutdown(wait=True)
        
        # 保存最终状态
        self._save_world_state("final_world_state.json")
        
        self.logger.info("Cosmic Orchestrator shutdown complete")

