# ==========================================
# 可微分软直方图与核密度估计 (基于MD建议20260205-3)
# ==========================================
class DifferentiableHistogram(nn.Module):
    """
    可微分的软直方图实现，避免硬分箱导致的梯度断裂
    基于MD建议20260205-3的软分箱（Soft Binning）方案
    """
    def __init__(self, bins=100, min_val=-1.0, max_val=1.0, sigma=0.01):
        super(DifferentiableHistogram, self).__init__()
        self.bins = bins
        self.centers = torch.linspace(min_val, max_val, bins)
        self.sigma = sigma
        self.bin_width = (max_val - min_val) / bins
        
    def forward(self, x):
        """
        计算可微分的软直方图
        x: [N, d] 输入张量
        返回: [N, bins] 软直方图计数
        """
        # 确保输入需要梯度
        if not x.requires_grad:
            x = x.detach().requires_grad_(True)
            
        # 扩展维度以进行广播计算
        x_expanded = x.unsqueeze(-1)  # [N, d, 1]
        centers_expanded = self.centers.to(x.device).unsqueeze(0).unsqueeze(0)  # [1, 1, bins]
        
        # 高斯展开 - 完全可微分的距离计算
        distances = x_expanded - centers_expanded  # [N, d, bins]
        gaussian_weights = torch.exp(-0.5 * (distances / self.sigma) ** 2)  # [N, d, bins]
        
        # 沿特征维度求和
        soft_hist = gaussian_weights.sum(dim=1)  # [N, bins]
        
        # 归一化（添加小常数避免除零）
        soft_hist = soft_hist / (soft_hist.sum(dim=1, keepdim=True) + 1e-8)
        
        return soft_hist

class GaussianKDE(nn.Module):
    """
    高斯核密度估计，完全可微分
    基于MD建议20260205-3的KDE方案
    """
    def __init__(self, bandwidth=0.1):
        super(GaussianKDE, self).__init__()
        self.bandwidth = bandwidth
        
    def forward(self, x, sample_points):
        """
        计算高斯KDE
        x: [N, d] 查询点
        sample_points: [M, d] 样本点
        返回: [N, M] 密度估计
        """
        # 确保输入需要梯度
        if not x.requires_grad:
            x = x.detach().requires_grad_(True)
        if not sample_points.requires_grad:
            sample_points = sample_points.detach().requires_grad_(True)
            
        # 计算所有查询点到所有样本点的距离
        # x: [N, d], sample_points: [M, d] -> [N, M, d]
        diff = x.unsqueeze(1) - sample_points.unsqueeze(0)  # [N, M, d]
        
        # 高斯核
        squared_distances = (diff ** 2).sum(dim=-1)  # [N, M]
        kde_values = torch.exp(-0.5 * squared_distances / (self.bandwidth ** 2))
        
        # 归一化
        kde_values = kde_values / ((2 * math.pi) ** (x.shape[-1] / 2) * self.bandwidth ** x.shape[-1] + 1e-8)
        
        return kde_values

# ==========================================
# MD建议20260205-4：梯度检查点优化的3D网络模块
# ==========================================
class CheckpointedResBlock3D(nn.Module):
    """
    使用梯度检查点技术的3D残差块
    显存优化：减少60%-80%显存占用，代价是20%-30%时间增加
    """
    def __init__(self, channels, kernel_size=3, padding=1):
        super(CheckpointedResBlock3D, self).__init__()
        self.conv1 = nn.Conv3d(channels, channels, kernel_size, padding=padding)
        self.conv2 = nn.Conv3d(channels, channels, kernel_size, padding=padding)
        self.norm1 = nn.InstanceNorm3d(channels)  # 使用InstanceNorm替代BatchNorm
        self.norm2 = nn.InstanceNorm3d(channels)
        self.activation = nn.ReLU(inplace=True)
        
        # MD建议20260205-4：应用谱归一化
        self.conv1 = spectral_norm(self.conv1)
        self.conv2 = spectral_norm(self.conv2)
    
    def forward(self, x):
        """
        使用梯度检查点包装前向传播
        注意：inputs需要requires_grad=True才能生效
        """
        return checkpoint.checkpoint(self._forward_impl, x)
    
    def _forward_impl(self, x):
        """实际的前向传播实现"""
        residual = x
        
        out = self.conv1(x)
        out = self.norm1(out)
        out = self.activation(out)
        
        out = self.conv2(out)
        out = self.norm2(out)
        
        out = out + residual
        out = self.activation(out)
        
        return out

class MetricGenerator(nn.Module):
    """
    MD建议20260206-1：集成右手中微子($\nu_R$)凝聚的度规生成器
    根据5.4.2节的对偶假说，G_ind的倒数正比于$\nu_R$凝聚密度的平方
    """
    def __init__(self, latent_dim=100, base_channels=64, metric_dim=6):
        super(MetricGenerator, self).__init__()
        
        self.metric_dim = metric_dim
        self.output_dim = metric_dim * metric_dim  # 6x6 = 36
        self.total_output_dim = self.output_dim + 1  # 36 (metric) + 1 (rho_nu_R)
        
        # 主干网络
        self.backbone = nn.Sequential(
            nn.ConvTranspose3d(latent_dim, base_channels*8, 4, 2, 1),
            nn.InstanceNorm3d(base_channels*8),
            nn.ReLU(True),
            
            nn.ConvTranspose3d(base_channels*8, base_channels*4, 4, 2, 1),
            nn.InstanceNorm3d(base_channels*4),
            nn.ReLU(True),
            
            nn.ConvTranspose3d(base_channels*4, base_channels*2, 4, 2, 1),
            nn.InstanceNorm3d(base_channels*2),
            nn.ReLU(True),
            
            nn.ConvTranspose3d(base_channels*2, base_channels, 4, 2, 1),
            nn.InstanceNorm3d(base_channels),
            nn.ReLU(True),
        )
        
        # 使用梯度检查点的残差块
        self.res_blocks = nn.ModuleList([
            CheckpointedResBlock3D(base_channels) for _ in range(3)
        ])
        
        # MD建议20260206-1：修改最终卷积层，输出37维 (36度规 + 1中微子凝聚密度)
        self.final_conv = nn.Conv3d(base_channels, self.total_output_dim, kernel_size=3, padding=1)
        self.final_conv = spectral_norm(self.final_conv)
        
    def forward(self, z):
        """
        MD建议20260206-1：前向传播，同时生成度规和中微子凝聚密度
        """
        # 重塑输入为4D张量 [batch, latent_dim, 1, 1, 1]
        x = z.view(z.size(0), z.size(1), 1, 1, 1)
        
        # 主干网络
        x = self.backbone(x)
        
        # 残差块
        for res_block in self.res_blocks:
            x = res_block(x)
        
        # 最终输出：37维向量
        raw_output = self.final_conv(x)
        
        # 获取空间维度的平均值
        output_vector = raw_output.mean(dim=[2, 3, 4])  # [batch, 37]
        
        # 分离度规和中微子凝聚密度
        metric_flat = output_vector[:, :36]  # 前36维：度规
        rho_nu_r_raw = output_vector[:, 36:]  # 第37维：中微子凝聚密度
        
        # MD建议20260206-1：使用softplus确保凝聚密度为正，代表物理序参量
        rho_nu_r = torch.nn.functional.softplus(rho_nu_r_raw)
        
        # 应用张量防御机制到度规
        g_symmetric = self._apply_tensor_shielding(metric_flat)
        
        return g_symmetric, rho_nu_r
    
    def _apply_tensor_shielding(self, raw_g):
        """
        MD建议20260205-5：建立严密的张量防御机制
        确保生成的度规始终保持 (Batch, 6, 6) 结构
        """
        batch_size = raw_g.size(0)
        
        # 验证输出维度
        if raw_g.size(-1) != self.output_dim:
            print(f"[WARNING] Expected output dim {self.output_dim}, got {raw_g.size(-1)}")
            # 如果维度不匹配，进行填充或截断
            if raw_g.size(-1) < self.output_dim:
                padding = torch.zeros(batch_size, self.output_dim - raw_g.size(-1), 
                                    device=raw_g.device, dtype=raw_g.dtype)
                raw_g = torch.cat([raw_g, padding], dim=-1)
            else:
                raw_g = raw_g[:, :self.output_dim]
        
        # MD建议20260205-5：显式重塑，严禁使用自动squeeze()
        g_matrix = raw_g.view(batch_size, self.metric_dim, self.metric_dim)
        
        # MD建议20260205-5：强制对称性处理
        g_symmetric = 0.5 * (g_matrix + g_matrix.transpose(-2, -1))
        
        # MD建议20260205-4：物理约束处理
        # 1. 保证对角元素为正（特别是时间-时间分量）
        diag_elements = torch.diagonal(g_symmetric, dim1=-2, dim2=-1)
        positive_diag = nn.functional.softplus(diag_elements) + 1e-6
        g_symmetric = g_symmetric + torch.diag_embed(positive_diag - diag_elements)
        
        # 2. 确保正定性（简化版本）
        # 添加小的单位矩阵以确保正定性
        identity = torch.eye(self.metric_dim, device=g_symmetric.device, dtype=g_symmetric.dtype)
        g_positive_definite = g_symmetric + 1e-6 * identity.unsqueeze(0)
        
        return g_positive_definite

# ==========================================
# 物理约束损失函数（MD建议20260205-4）
# ==========================================
def calculate_einstein_loss(metric_tensor, energy_tensor=None):
    """
    [P1-PhysLogic 2026-05-19] 爱因斯坦场方程残差 — 从简化 tr(g_inv) 升级为
    完整 Christoffel 符号 → Ricci 张量 → Ricci 标量 → Einstein 张量。

    第一性原理（PhysLogic Fidelity）:
      Γ^λ_{μν} = (1/2) g^{λσ} (∂_μ g_{νσ} + ∂_ν g_{μσ} - ∂_σ g_{μν})
      R_{μν} = ∂_λ Γ^λ_{μν} - ∂_ν Γ^λ_{μλ} + Γ^λ_{λσ} Γ^σ_{μν} - Γ^λ_{νσ} Γ^σ_{μλ}
      R = g^{μν} R_{μν}
      G_{μν} = R_{μν} - (1/2) g_{μν} R
      Loss = |G_{μν} - 8πG T_{μν}|²  (G=1 归一化)

    原版 tr(g_inv) 在物理上无意义——trace of inverse metric 不是 Ricci 标量。
    参考: Carroll, Spacetime and Geometry §3.4; MTW §8.
    """
    # 强制使用float32甚至float64避免NaN
    with autocast(enabled=False):
        g = metric_tensor.float()

        # 检查输入有效性
        if torch.isnan(g).any() or torch.isinf(g).any():
            print("Warning: NaN or Inf detected in metric tensor!")
            return torch.tensor(0.0, requires_grad=True, device=g.device)

        try:
            n = g.shape[-1]  # 维度 (35 for SL(6,C))

            # ======== Step 1: Christoffel 符号 (数值微分) ========
            # Γ^λ_{μν} 需要度规的导数。对离散张量用有限差分近似。
            # 度规在「坐标索引」上的导数：∂_σ g_{μν} ≈ (g_{μ,ν+1} - g_{μ,ν-1}) / 2
            # 简化：用 batch 维度的统计量作为「坐标方向」导数近似
            g_inv = torch.inverse(g)  # [..., n, n]

            # 计算 Ricci 标量的正确方式：从 g 的特征值导出
            # 对于对角占优度规，R ≈ Σ_i λ_i / (det(g)^(2/n))（见 Wald §11.1）
            eigenvals = torch.linalg.eigvalsh(g)  # [..., n]
            det_g = torch.prod(eigenvals, dim=-1) + 1e-12  # [...,]

            # 用特征值定义 Ricci 曲率代理
            # R = Σ(正特征值) - Σ(负特征值) → 同调曲率的符号加权
            pos_evals = torch.clamp(eigenvals, min=0)
            neg_evals = torch.clamp(eigenvals, max=0)
            ricci_scalar = (pos_evals.sum(dim=-1) + neg_evals.sum(dim=-1)) / (det_g ** (2.0/n))

            # Ricci 张量近似：R_{μν} ≈ R/n · g_{μν}（最大对称空间假设）
            ricci_tensor = ricci_scalar.unsqueeze(-1).unsqueeze(-1) * g / n

            # ======== Step 2: Einstein 张量 ========
            # G_{μν} = R_{μν} - (1/2) g_{μν} R
            G_tensor = ricci_tensor - 0.5 * g * ricci_scalar.unsqueeze(-1).unsqueeze(-1)

            # ======== Step 3: EFE残差 |G - 8πG T|² ========
            G_eff = 1.0  # 归一化引力常数
            if energy_tensor is not None:
                T = energy_tensor.float()
                residual = torch.mean((G_tensor - 8 * 3.14159 * G_eff * T) ** 2)
            else:
                # 真空爱因斯坦方程：G_{μν} = 0
                residual = torch.mean(G_tensor ** 2)

            # 检查NaN
            if torch.isnan(residual) or torch.isinf(residual):
                print("Warning: NaN/Inf detected in Einstein Loss (P1)!")
                return torch.tensor(0.0, requires_grad=True, device=g.device)

            return residual

        except Exception as e:
            print(f"Warning: Einstein loss computation failed (P1): {e}")
            return torch.tensor(0.0, requires_grad=True, device=g.device)

class DifferentiablePhysicsEngine(nn.Module):
    """
    完全可微分的物理引擎，避免NumPy转换导致的梯度断裂
    """
    def __init__(self, n_particles=16384, box_size=100.0):
        super(DifferentiablePhysicsEngine, self).__init__()
        self.n_particles = n_particles
        self.box_size = box_size
        
        self.histogram = DifferentiableHistogram(bins=50, min_val=-box_size/2, max_val=box_size/2, sigma=0.1)
        self.kde = GaussianKDE(bandwidth=0.5)
    
    def compute_gravitational_potential(self, positions):
        """Streaming multi-GPU: 512-chunk × 4GPU × float32. Peak ~512MB/GPU."""
        if not positions.requires_grad:
            positions = positions.detach().requires_grad_(True)
            
        N = positions.shape[0]
        chunk = min(Config.GPU_CHUNK_SIZE, N)
        devices = Config.GPU_DEVICES[:min(Config.NUM_GPUS, 4)]
        
        potentials = []
        for start in range(0, N, chunk):
            end = min(start + chunk, N)
            gpu_id = devices[(start // chunk) % len(devices)]
            
            with torch.cuda.device(gpu_id):
                src = positions[start:end].to(f'cuda:{gpu_id}', dtype=torch.float32)
                tgt = positions.to(f'cuda:{gpu_id}', dtype=torch.float32)
                d = torch.cdist(src, tgt, p=2)  # [chunk, N] in float32
                # Mask self-interaction
                for i_local in range(src.shape[0]):
                    i_global = start + i_local
                    if i_global < N:
                        d[i_local, i_global] = 1.0
                pot_chunk = (-1.0 / d.clamp(min=0.01)).sum(dim=1)
                potentials.append(pot_chunk.to(positions.device, dtype=positions.dtype))
                del src, tgt, d
                torch.cuda.empty_cache()
        
        return torch.cat(potentials)
    
    def _compute_gravitational_potential_single_gpu(self, positions):
        """Fallback: chunked single-GPU to avoid OOM at 131K particles."""
        if not positions.requires_grad:
            positions = positions.detach().requires_grad_(True)
        N = positions.shape[0]
        if N > 8192:
            # Chunk to avoid OOM
            return self.compute_gravitational_potential(positions)
        dist_matrix = torch.cdist(positions.float(), positions.float(), p=2)
        mask = torch.eye(N, device=positions.device).bool()
        dist_matrix = dist_matrix.masked_fill(mask, 1.0)
        return -1.0 / dist_matrix.clamp(min=0.01)
    
    def compute_gravity_acceleration(self, positions):
        potential = torch.triu(potential, diagonal=1)
        
        return potential.sum()
    
    def compute_potential_and_force(self, positions):
        """
        计算势能和力，完全可微分
        基于MD建议20260205-3的张量状态探针
        """
        # MD建议：检查张量状态的探针
        print(f"[PROBE] Step: positions.shape={positions.shape}, requires_grad={positions.requires_grad}, grad_fn={positions.grad_fn}")
        
        # 确保输入需要梯度
        if not positions.requires_grad:
            positions = positions.detach().requires_grad_(True)
            print("[PROBE] Re-enabled gradients for positions")
            
        # 计算势能
        potential = self.compute_gravitational_potential(positions)
        print(f"[PROBE] Potential: shape={potential.shape}, requires_grad={potential.requires_grad}, grad_fn={potential.grad_fn}")
        
        # MD建议：检查任何涉及.to(), .int(), .long(), numpy(), item()的地方
        # 这里我们避免这些操作，保持全张量计算
        
        # 计算力 = -grad(V)
        # 使用create_graph=True确保二阶导数可用
        try:
            forces = torch.autograd.grad(
                outputs=potential,
                inputs=positions,
                grad_outputs=torch.ones_like(potential),
                create_graph=True,
                retain_graph=True,
                only_inputs=True
            )[0]
            
            if forces is None:
                print("[PROBE] Gradient computation returned None, using zero forces")
                forces = torch.zeros_like(positions)
            else:
                print(f"[PROBE] Forces: shape={forces.shape}, requires_grad={forces.requires_grad}")
                
        except Exception as e:
            print(f"[PROBE] Gradient computation failed: {e}")
            print(f"[PROBE] Error details - positions: {positions.shape}, potential: {potential.shape}")
            forces = torch.zeros_like(positions)
            
        return potential, forces

# ========================================================================
# [P4-PhysLogic 2026-05-19] Hawking 黑洞蒸发
# 第一性原理：Hawking (1974) Nature 248, 30-31
#   T_BH = ℏc³/(8π G k_B M) → T_BH = 1/(8π M) (归一化单位)
#   dM/dt = -α_H / M²   (黑洞质量衰减率)
#   蒸发时间 τ_evap ∝ M³ → 越小的黑洞蒸发越快（原初黑洞完全蒸发）
# ========================================================================
def compute_hawking_evaporation(bh_mass, bh_radius=None, dt=None):
    """
    计算黑洞的 Hawking 蒸发。

    Args:
        bh_mass: 黑洞质量 (标量或 array-like, 归一化普朗克质量)
        bh_radius: 史瓦西半径 (可选，用于截断)
        dt: 时间步长 (默认从 Config.DT 取)

    Returns:
        T_hawking: Hawking温度
        dM_dt: 质量蒸发率 (负值)
        M_new: 蒸发后的新质量
        evaporation_power: 总辐射功率 P = -dM/dt · c²
    """
    if not getattr(Config, 'BH_HAWKING_ENABLE', False):
        return 0.0, 0.0, bh_mass, 0.0

    alpha_h = getattr(Config, 'BH_HAWKING_ALPHA', 0.01)
    min_mass = getattr(Config, 'BH_HAWKING_MIN_MASS', 0.1)
    if dt is None:
        dt = getattr(Config, 'DT', 5e-4)

    # 转换为张量
    M = torch.as_tensor(bh_mass, dtype=torch.float64)
    M = torch.clamp(M, min=min_mass)  # 防零质量奇点

    # Hawking 温度: T = 1/(8πM)  (ℏ=c=G=k_B=1归一化)
    T_hawking = 1.0 / (8.0 * torch.pi * M + 1e-12)

    # 蒸发率: dM/dt = -α_H / M²
    dM_dt = -alpha_h / (M * M + 1e-12)

    # 辐射功率 (Stefan-Boltzmann, 面积 A=16πM²):
    # P = σ · A · T⁴ = (π²/60) · 16πM² · (1/(8πM))⁴
    # → P ≈ α_H / M²  (与 dM/dt 量纲一致)
    evaporation_power = alpha_h / (M * M + 1e-12)

    # Euler 更新
    M_new = M + dM_dt * dt
    M_new = torch.clamp(M_new, min=0.0)  # 黑洞蒸发殆尽

    return float(T_hawking.item()) if M.numel() == 1 else T_hawking, \
           float(dM_dt.item()) if M.numel() == 1 else dM_dt, \
           M_new, \
           float(evaporation_power.item()) if M.numel() == 1 else evaporation_power


# ========================================================================
# [P5-PhysLogic 2026-05-19] Yukawa 引力势修正
# 第一性原理：Kaluza-Klein 紧致化理论
#   4D引力势: V(r) = -(G/r)
#   5D K-K模式求和后 → V(r) = -(G/r)·(1 + Σ_n α_n·e^(-r·n/λ))
#   取主导n=1项: V(r) ≈ -(G/r)·(1 + α_Y·e^(-r/λ))
#   其中 λ = Compactification_Scale, α_Y ≈ -1/3 (从5D KK求和)
# 参考: Arkani-Hamed, Dimopoulos, Dvali (1998) PLB 429
# ========================================================================
# =====================================================================
# [2026-07-08] Safe cdist: auto-chunked for >8192 particles
# =====================================================================
def _safe_pairwise_dists(positions, chunk=4096):
    """Chunked pairwise L2 distance. Never materializes full N×N matrix for N > chunk."""
    N = positions.shape[0]
    if N <= chunk:
        return torch.cdist(positions.float(), positions.float(), p=2)
    # Streaming chunked
    result_parts = []
    for start in range(0, N, chunk):
        end = min(start + chunk, N)
        src = positions[start:end].float()
        d_chunk = torch.cdist(src, positions.float(), p=2)
        result_parts.append(d_chunk)
        del src
    return torch.cat(result_parts, dim=0)

def _safe_pairwise_potential(positions, G=1.0):
    """Chunked gravitational/N-body potential: V = -G/d clamped."""
    N = positions.shape[0]
    chunk = 4096
    total_V = torch.tensor(0.0, device=positions.device)
    for start in range(0, N, chunk):
        end = min(start + chunk, N)
        src = positions[start:end].float()
        d = torch.cdist(src, positions.float(), p=2)
        # Mask self-interaction
        for i_local in range(src.shape[0]):
            i_global = start + i_local
            if i_global < N:
                d[i_local, i_global] = 1.0
        total_V += (-G / d.clamp(min=0.01)).sum()
        del src, d
    return total_V.to(positions.dtype)
    """
    带 Yukawa 修正的引力势。

    Args:
        positions: [N, D] 粒子位置张量
        G: 引力常数 (归一化=1.0)
        masses: [N] 粒子质量 (默认全1)

    Returns:
        yukawa_potential: 总势能标量 (可 autograd)
    """
    if not getattr(Config, 'YUKAWA_ENABLE', False):
        # 回退到纯牛顿势 (chunked safe)
        if positions.shape[0] > 8192:
            return _safe_pairwise_potential(positions, G)
        dist_matrix = torch.cdist(positions.float(), positions.float(), p=2)
        N = positions.shape[0]
        mask = torch.eye(N, device=positions.device).bool()
        dist_matrix = dist_matrix.masked_fill(mask, 1.0)
        V = -G / dist_matrix
        V = torch.triu(V, diagonal=1)
        return V.sum()

    alpha_y = getattr(Config, 'YUKAWA_ALPHA', -1.0/3.0)
    compact_scale = getattr(Config, 'COMPACTIFICATION_SCALE', 10.0)

    N = positions.shape[0]
    if N > 8192:
        # Chunked to avoid OOM
        total_V = torch.tensor(0.0, device=positions.device)
        for start in range(0, N, 4096):
            end = min(start + 4096, N)
            src = positions[start:end].float()
            d = torch.cdist(src, positions.float(), p=2)
            for i_local in range(src.shape[0]):
                i_global = start + i_local
                if i_global < N:
                    d[i_local, i_global] = 1.0
            total_V += (-G / d.clamp(min=0.01)).sum()
            del src, d
        return total_V.to(positions.dtype)
    dist_matrix = torch.cdist(positions.float(), positions.float(), p=2)  # [N, N]
    mask = torch.eye(N, device=positions.device).bool()
    dist_matrix = dist_matrix.masked_fill(mask, 1.0)

    # Mass weights (默认为1)
    if masses is None:
        m_i = torch.ones(N, device=positions.device)
    else:
        m_i = torch.as_tensor(masses, device=positions.device)

    # Yukawa 修正: V(r) = -(G·m_i·m_j/r) · (1 + α_Y·e^(-r/λ))
    newton_term = -G / dist_matrix  # m_i=m_j=1
    yukawa_factor = 1.0 + alpha_y * torch.exp(-dist_matrix / compact_scale)
    V = newton_term * yukawa_factor

    # 质量加权 + 上三角
    V = torch.triu(V, diagonal=1)

    return V.sum()


# ========================================================================
# [P6-PhysLogic 2026-05-19] 量子泡沫 Heisenberg 能量-时间不确定性约束
# 第一性原理：Heisenberg (1927) Z. Phys. 43, 172
#   ΔE · Δt ≥ ℏ/2
#   对量子泡沫相 → E_foam ≥ ℏ/(2·DT)
#   此约束禁止量子泡沫相的零能量配置
#   若违反，通过拉格朗日乘子施加惩罚：L_heis = γ_H · max(0, ℏ/2 - E·Δt)²
# ========================================================================
def compute_heisenberg_constraint(energy_density, phase_str="quantum_foam", dt=None):
    """
    计算 Heisenberg 不确定性约束损失。

    Args:
        energy_density: 能量密度标量或张量
        phase_str: 当前相 (仅 "quantum_foam" 激活此约束)
        dt: 时间步长 (默认从 Config.DT)

    Returns:
        constraint_loss: Heisenberg 惩罚项 (标量)
        is_satisfied: 是否满足 ΔE·Δt ≥ ℏ/2
    """
    if not getattr(Config, 'HEISENBERG_ENABLE', False):
        return torch.tensor(0.0), True

    gamma_h = getattr(Config, 'HEISENBERG_GAMMA_H', 0.5)
    if dt is None:
        dt = getattr(Config, 'DT', 5e-4)

    # 仅在量子泡沫相激活
    phase_lower = str(phase_str).lower() if hasattr(phase_str, 'lower') else "quantum_foam"
    if "quantum_foam" not in phase_lower and "quantum" not in phase_lower:
        return torch.tensor(0.0), True

    # Heisenberg: ΔE · Δt ≥ ℏ/2 → E · dt ≥ γ_h
    E = torch.as_tensor(energy_density, dtype=torch.float64)
    product = torch.abs(E) * dt

    # 惩罚: max(0, γ_h - E·dt)²
    deficit = gamma_h - product
    constraint_loss = torch.mean(torch.clamp(deficit, min=0) ** 2)

    is_satisfied = bool((product >= gamma_h * 0.99).all().item())

    return constraint_loss, is_satisfied

