    class PhysicsMetrics:
        """高级物理指标计算器"""
        
        @staticmethod
        def compute_einstein_residual(metric_tensor: torch.Tensor, stress_tensor: torch.Tensor) -> float:
            """计算爱因斯坦场方程残差"""
            try:
                G = 6.67430e-11  # 引力常数
                einstein_lhs = metric_tensor
                einstein_rhs = 8 * np.pi * G * stress_tensor
                residual = torch.norm(einstein_lhs - einstein_rhs, p='fro')
                volume = metric_tensor.numel()
                # 修复：使用torch.sqrt处理tensor
                return float(residual / torch.sqrt(torch.tensor(volume, dtype=residual.dtype)))
            except Exception as e:
                print(f"[WARNING] 爱因斯坦残差计算失败: {e}")
                return 999.9
        
        @staticmethod
        def compute_topological_stability(betti_numbers: Dict[int, int], history_length: int = 10) -> Tuple[float, bool]:
            """计算拓扑稳定性"""
            try:
                current_betti = betti_numbers
                stability_score = 1.0 / (1.0 + np.var(list(current_betti.values())))
                is_crystallized = all(
                    isinstance(b, int) and b >= 0 for b in current_betti.values()
                )
                return float(stability_score), is_crystallized
            except Exception as e:
                print(f"[WARNING] 拓扑稳定性计算失败: {e}")
                return 0.0, False
        
        @staticmethod
        def compute_unitarity_check(eigenvalues: torch.Tensor) -> Tuple[float, bool]:
            """幺正性判据检查"""
            try:
                positive_eigenvalues = eigenvalues[eigenvalues > 0]
                if len(positive_eigenvalues) == 0:
                    return 0.0, False
                lambda_gap = torch.min(positive_eigenvalues)
                unitarity_score = float(torch.tanh(lambda_gap))
                is_unitary = lambda_gap > 1e-6
                return unitarity_score, is_unitary
            except Exception as e:
                print(f"[WARNING] 幺正性检查失败: {e}")
                return 0.0, False
        
        @staticmethod
        def compute_physics_bias(params: dict, metrics: dict) -> float:
            """计算物理启发式偏置"""
            try:
                bias = 0.0
                
                # 暗能量状态方程偏置
                w = params.get('dark_energy_w', -1.0)
                if w < -1.2:  # 幽灵能量区域
                    bias += 0.1
                elif -1.1 <= w <= -1.0:  # 理想暗能量区域
                    bias += 0.05
                
                # 拓扑稳定性偏置
                if metrics.get('topological_stability', 0) > 0.8:
                    bias += 0.1
                
                # 爱因斯坦残差偏置
                residual = metrics.get('einstein_residual', 999.9)
                if residual < 1.0:
                    bias += 0.1
                
                return bias
            except Exception as e:
                print(f"[WARNING] 物理偏置计算失败: {e}")
                return 0.0

