# MD建议20260207：参数优化器类
# ==========================================
class ParameterOptimizer:
    """参数优化器 - 基于数据分析的参数自适应调整"""
    
    def __init__(self):
        self.optimization_params = {
            'G_adaptation_rate': 0.8,
            'G_damping_factor': 1.2,
            'w_evolution_rate': 0.6,
            'expansion_boost': 1.15,
            'noise_reduction': 0.7,
            'spectral_feedback': 0.1,
            'phase_coupling': 1.3,
            'w_hysteresis_factor': 0.9,
            'covariance_decay': 0.85,
            'covariance_regularization': 0.1
        }
        
        self.stability_thresholds = {
            'G_stability': 0.1,
            'w_stability': 0.1,
            'trace_A_stability': 0.3,
            'spectral_gap_stability': 0.2
        }
        
        self.parameter_history = {}
        self.optimization_log = []
    
    def optimize_gravity_constant(self, G_current, trend_slope, stability):
        """优化引力常数"""
        if stability > 0.02:  # 稳定性阈值
            if trend_slope < -1e-6:  # 下降趋势
                optimized_G = G_current * self.optimization_params['G_damping_factor']
                self.optimization_log.append(f"Gravity constant: {G_current:.6f} -> {optimized_G:.6f} (damping)")
                return optimized_G
        return G_current
    
    def optimize_dark_energy_w(self, w_current, stability, change_points):
        """优化暗能量状态方程"""
        if stability > 0.1:  # 不稳定
            # 向-1.0回归
            optimized_w = w_current * 0.95 + (-1.0) * 0.05
            self.optimization_log.append(f"Dark energy w: {w_current:.6f} -> {optimized_w:.6f} (regression)")
            return optimized_w
        
        if change_points > 10:  # 变化点过多
            optimized_w = w_current * self.optimization_params['w_hysteresis_factor']
            self.optimization_log.append(f"Dark energy w: {w_current:.6f} -> {optimized_w:.6f} (hysteresis)")
            return optimized_w
            
        return w_current
    
    def optimize_expansion_rate(self, rate_current, radius_trend):
        """优化膨胀率"""
        if radius_trend < 0:  # 收缩趋势
            optimized_rate = rate_current * self.optimization_params['expansion_boost']
            self.optimization_log.append(f"Expansion rate: {rate_current:.6f} -> {optimized_rate:.6f} (boost)")
            return optimized_rate
        return rate_current
    
    def optimize_trace_A(self, trace_A_current, stability):
        """优化模空间协方差迹"""
        if stability > 0.3:  # 稳定性不足
            # 增强正则化
            regularization = self.optimization_params['covariance_regularization'] * trace_A_current
            optimized_trace_A = trace_A_current * self.optimization_params['covariance_decay'] + regularization
            self.optimization_log.append(f"Trace A: {trace_A_current:.6f} -> {optimized_trace_A:.6f} (regularization)")
            return optimized_trace_A
        return trace_A_current
    
    def compute_parameter_trend(self, param_name, values):
        """计算参数趋势"""
        if len(values) < 10:
            return 0, 0, 0, []
        
        iterations = np.arange(len(values))
        slope, intercept, r_value, p_value, std_err = stats.linregress(iterations, values)
        
        # 变化点检测
        diff_values = np.diff(values)
        change_points = find_peaks(np.abs(diff_values), height=np.std(diff_values))[0]
        
        return slope, r_value, std_err, change_points
    
    def analyze_csv_data(self, csv_file):
        """分析CSV数据并生成优化建议"""
        if not DATA_ANALYSIS_AVAILABLE:
            print("[WARNING] Data analysis modules not available")
            return {}
        
        try:
            df = pd.read_csv(csv_file)
            analysis_results = {}
            
            # 分析关键参数
            key_params = ['gravity_constant_G', 'dark_energy_w', 'universe_radius', 'trace_A', 'expansion_rate']
            
            for param in key_params:
                if param in df.columns:
                    values = df[param].values
                    
                    # 基础统计
                    mean_val = np.mean(values)
                    std_val = np.std(values)
                    stability = std_val / abs(mean_val) if mean_val != 0 else np.inf
                    
                    # 趋势分析
                    slope, r_value, std_err, change_points = self.compute_parameter_trend(param, values)
                    
                    analysis_results[param] = {
                        'mean': mean_val,
                        'std': std_val,
                        'stability': stability,
                        'trend_slope': slope,
                        'trend_strength': abs(r_value),
                        'change_points': len(change_points),
                        'current_value': values[-1] if len(values) > 0 else None
                    }
            
            return analysis_results
            
        except Exception as e:
            print(f"[ERROR] Failed to analyze CSV data: {e}")
            return {}
    
    def apply_optimizations(self, current_params, analysis_results):
        """应用参数优化"""
        optimized_params = current_params.copy()
        
        for param, analysis in analysis_results.items():
            if param == 'gravity_constant_G' and param in current_params:
                optimized_params[param] = self.optimize_gravity_constant(
                    current_params[param], 
                    analysis['trend_slope'], 
                    analysis['stability']
                )
            
            elif param == 'dark_energy_w' and param in current_params:
                optimized_params[param] = self.optimize_dark_energy_w(
                    current_params[param],
                    analysis['stability'],
                    analysis['change_points']
                )
            
            elif param == 'expansion_rate' and param in current_params:
                # 需要宇宙半径趋势信息
                radius_trend = analysis_results.get('universe_radius', {}).get('trend_slope', 0)
                optimized_params[param] = self.optimize_expansion_rate(
                    current_params[param],
                    radius_trend
                )
            
            elif param == 'trace_A' and param in current_params:
                optimized_params[param] = self.optimize_trace_A(
                    current_params[param],
                    analysis['stability']
                )
        
        return optimized_params
    
    def get_optimization_summary(self):
        """获取优化总结"""
        if not self.optimization_log:
            return "No optimizations applied in this cycle."
        
        summary = f"Applied {len(self.optimization_log)} optimizations:\n"
        for i, log_entry in enumerate(self.optimization_log[-5:], 1):  # 显示最近5条
            summary += f"  {i}. {log_entry}\n"
        
        return summary

class StabilityMonitor:
    """稳定性监控器"""
    
    def __init__(self):
        self.stability_history = {}
        self.alert_threshold = 0.5  # 高稳定性阈值
    
    def check_parameter_stability(self, param_name, current_value, history_window=50):
        """检查参数稳定性"""
        if param_name not in self.stability_history:
            self.stability_history[param_name] = []
        
        # 添加当前值到历史记录
        self.stability_history[param_name].append(current_value)
        
        # 保持窗口大小
        if len(self.stability_history[param_name]) > history_window:
            self.stability_history[param_name] = self.stability_history[param_name][-history_window:]
        
        # 计算稳定性
        if len(self.stability_history[param_name]) >= 10:
            values = np.array(self.stability_history[param_name])
            stability = np.std(values) / abs(np.mean(values)) if np.mean(values) != 0 else np.inf
            return stability
        
        return 0.0  # 数据不足，返回0
    
    def generate_stability_report(self):
        """生成稳定性报告"""
        report = "Stability Report:\n"
        
        for param_name, history in self.stability_history.items():
            if len(history) >= 10:
                values = np.array(history)
                stability = np.std(values) / abs(np.mean(values)) if np.mean(values) != 0 else np.inf
                status = "STABLE" if stability < 0.1 else "UNSTABLE" if stability > self.alert_threshold else "MODERATE"
                report += f"  {param_name}: {status} (stability={stability:.4f})\n"
        
        return report

