# ==========================================
# 几何信息动力学方程组
# ==========================================

# ============================================================================
# [15_1 / PDE-JEPA 2026-10-13] 结构化潜动力学增强
# 依据: PDE-JEPA — Predictive Representation Learning of Latent Dynamics
#       Modeling for Parametric PDEs (arXiv:2609.34715), 方程 (12)-(17)
#   dq/dt = C_theta(q) + sum_j r_j(xi) * D_theta^{(j)}(q)          (Eq.13)
#   q_{t+1} = Phi_ODE(q_t, F_theta, xi, dt)   [RK4 定步长]         (Eq.16)
#   L_pre = ||q_hat_{t+1} - q_{t+1}||^2 / (||dq_t||^2 + eps)       (Eq.17)
# 物理对齐几何 (PAG, Eq.4-11): 轨迹转向一致性 s_{t,l} = <d_t, d_{t+l}> (Eq.7)
#   对齐损失 L_geo = sum_l w_l SmoothL1(s^q, sg(s^u))            (Eq.8)
#   恒等锚   L_anchor = ||q-z||^2/(||z||^2+eps)                   (Eq.9)
# ============================================================================
class PhysicsStructuredLatentPredictor(nn.Module):
    """PDE-JEPA Eq.13/16: 共享演化 + 参数响应分解 + RK4 连续时间传播。"""

    def __init__(self, dim: int = 8, n_params: int = 3, hidden: int = 64):
        super().__init__()
        self.dim = dim
        self.n_params = n_params
        self.shared = nn.Sequential(
            nn.Linear(dim, hidden), nn.GELU(), nn.Linear(hidden, dim)
        )
        self.responses = nn.ModuleList([
            nn.Sequential(nn.Linear(dim, hidden), nn.GELU(), nn.Linear(hidden, dim))
            for _ in range(n_params)
        ])
        # 零初始化响应头 → 初始退化为共享演化 (同 Eq.5 零初始化设计思想)
        for r in self.responses:
            nn.init.zeros_(r[-1].weight)
            nn.init.zeros_(r[-1].bias)

    def vector_field(self, q: torch.Tensor, xi: torch.Tensor) -> torch.Tensor:
        """dq/dt = C(q) + sum_j r_j(xi) D_j(q)   —— PDE-JEPA Eq.13"""
        dq = self.shared(q)
        for j in range(self.n_params):
            dq = dq + xi[..., j:j + 1] * self.responses[j](q)
        return dq

    def rk4_step(self, q: torch.Tensor, xi: torch.Tensor, dt: float = 1.0) -> torch.Tensor:
        """四阶 Runge-Kutta 定步长积分 —— PDE-JEPA Eq.16"""
        k1 = self.vector_field(q, xi)
        k2 = self.vector_field(q + 0.5 * dt * k1, xi)
        k3 = self.vector_field(q + 0.5 * dt * k2, xi)
        k4 = self.vector_field(q + dt * k3, xi)
        return q + (dt / 6.0) * (k1 + 2.0 * k2 + 2.0 * k3 + k4)

    def rollout(self, q0: torch.Tensor, xi: torch.Tensor, dt: float = 1.0,
                n_steps: int = 8) -> torch.Tensor:
        """递归积分长时程预测 —— PDE-JEPA Sec.4.3"""
        qs = [q0]
        q = q0
        for _ in range(n_steps):
            q = self.rk4_step(q, xi, dt)
            qs.append(q)
        return torch.stack(qs, dim=0)

    def pre_loss(self, q_hat: torch.Tensor, q_true: torch.Tensor) -> torch.Tensor:
        """L_pre = ||q_hat - q_true||^2 / (||dq||^2 + eps) —— PDE-JEPA Eq.17"""
        dq = q_true[1:] - q_true[:-1]
        return (((q_hat[1:] - q_true[1:]) ** 2).sum()
                / ((dq ** 2).sum() + 1e-8))


def pde_jepa_turn_alignment(q_traj: torch.Tensor, u_traj: torch.Tensor,
                            lags=(1, 2, 4)) -> dict:
    """PAG 轨迹几何对齐度量 —— PDE-JEPA Eq.6-8。
    返回潜空间/物理空间的多滞后转向相似度（越一致越接近）。"""
    def _dirs(x):
        d = x[1:] - x[:-1]
        return d / (d.norm(dim=-1, keepdim=True) + 1e-8)
    dq, du = _dirs(q_traj), _dirs(u_traj)
    out = {}
    for l in lags:
        if dq.shape[0] > l:
            sq = (dq[:-l] * dq[l:]).sum(-1).mean()
            su = (du[:-l] * du[l:]).sum(-1).mean()
            out[f'turn_sim_lag{l}_latent'] = float(sq)
            out[f'turn_sim_lag{l}_phys'] = float(su)
    return out


def pde_jepa_anchor_loss(q: torch.Tensor, z: torch.Tensor) -> float:
    """L_anchor = ||q-z||^2 / (||z||^2+eps) —— PDE-JEPA Eq.9 (几何对齐保信息锚)。"""
    return float(((q - z) ** 2).sum() / ((z ** 2).sum() + 1e-8))



# ============================================================================
# [15_1 / v5 闭环 2026-10-13] 16 维潜状态桥接（加载 train_jepa_v5.py 产物）
#   潜状态 q = [标准化物理状态 8 维] ⊕ [冻结 FNO(chi 场 142 维) 8 维]
#   预测器同构于 v5 StructuredPredictor (hidden=128, 多步监督训练)
# ============================================================================
class JEPA_SpectralConv1d(nn.Module):
    def __init__(self, cin, cout, modes=16):
        super().__init__()
        self.modes = modes
        self.w = nn.Parameter(torch.randn(cin, cout, modes) / (cin * cout) ** 0.5)

    def forward(self, x):
        L = x.shape[-1]
        xf = torch.fft.rfft(x, dim=-1)
        m = min(self.modes, xf.shape[-1])
        out = torch.zeros(x.shape[0], self.w.shape[1], xf.shape[-1],
                          dtype=xf.dtype, device=x.device)
        out[:, :, :m] = torch.einsum("bcl,com->bom", xf[:, :, :m],
                                     self.w[:, :, :m].to(xf.dtype))
        return torch.fft.irfft(out, n=L, dim=-1)


class JEPA_FNOEncoder(nn.Module):
    """PDE-JEPA Eq.4 谱编码塔（与 v5 训练时同构，推理时冻结）。"""

    def __init__(self, cin, width=64, latent=8, modes=16):
        super().__init__()
        self.lift = nn.Linear(cin, width)
        self.spec = JEPA_SpectralConv1d(width, width, modes)
        self.point = nn.Conv1d(width, width, 1)
        self.proj = nn.Sequential(nn.GELU(), nn.Linear(width, latent))

    def forward(self, u):
        x = self.lift(u).unsqueeze(-1)
        x = torch.nn.functional.gelu(self.spec(x) + self.point(x))
        return self.proj(x.mean(dim=-1))


class JEPA_StructuredPredictor(nn.Module):
    """PDE-JEPA Eq.13/16（与 train_jepa_v5.py 的 StructuredPredictor 同构）。"""

    def __init__(self, d, n_params=3, hidden=128):
        super().__init__()
        self.n_params = n_params
        self.shared = nn.Sequential(
            nn.Linear(d, hidden), nn.GELU(), nn.Linear(hidden, hidden), nn.GELU(),
            nn.Linear(hidden, hidden), nn.GELU(), nn.Linear(hidden, d))
        self.responses = nn.ModuleList([
            nn.Sequential(nn.Linear(d, hidden), nn.GELU(), nn.Linear(hidden, hidden),
                          nn.GELU(), nn.Linear(hidden, d))
            for _ in range(n_params)])

    def vf(self, q, xi):
        dq = self.shared(q)
        for j in range(self.n_params):
            dq = dq + xi[..., j:j+1] * self.responses[j](q)
        return dq

    def rk4(self, q, xi, dt=1.0):
        k1 = self.vf(q, xi)
        k2 = self.vf(q + .5 * dt * k1, xi)
        k3 = self.vf(q + .5 * dt * k2, xi)
        k4 = self.vf(q + dt * k3, xi)
        return q + dt / 6 * (k1 + 2 * k2 + 2 * k3 + k4)


class JEPA_FNO_Bridge:
    """加载 v5 训练产物并提供逐步潜状态推理（真闭环）。"""

    def __init__(self, ckpt_path):
        self.ok = False
        self.ckpt_path = ckpt_path
        ck = torch.load(ckpt_path, map_location="cpu", weights_only=False)
        self.u_mu = torch.tensor(ck["u_mu"], dtype=torch.float32)
        self.u_sd = torch.tensor(ck["u_sd"], dtype=torch.float32)
        self.s_mu = torch.tensor(ck["s_mu"], dtype=torch.float32)
        self.s_sd = torch.tensor(ck["s_sd"], dtype=torch.float32)
        self.xi_mu = torch.tensor(ck["xi_mu"], dtype=torch.float32)
        self.xi_sd = torch.tensor(ck["xi_sd"], dtype=torch.float32)
        self.chi_dim = int(ck["chi_dim"])
        self.q_dim = int(ck["q_dim"])
        self.agg = ck.get("agg", {})
        self.enc = JEPA_FNOEncoder(self.chi_dim, 64, 8)
        self.enc.load_state_dict(ck["encoder"])
        self.enc.eval()
        for _p in self.enc.parameters():
            _p.requires_grad_(False)
        self.pred = JEPA_StructuredPredictor(self.q_dim, 3, 256)   # [v7b] hidden 256
        self.pred.load_state_dict(ck["predictor"])
        # [修复] 全局默认 dtype 可能为 double；训练产物为 float32 → 统一为 float32
        self.enc = self.enc.float()
        self.pred = self.pred.float()
        self.enc.eval()
        self.pred.eval()
        self.ok = True

    # ── 从运行中的 sim 构造 142 维 chi 特征（与 save_chi_to_csv 的列一致） ──
    def _chi_feature(self, sim, step):
        chi = getattr(getattr(sim, "flow_solver", None), "chi", None)
        if chi is None:
            return None
        R_loc = getattr(sim.flow_solver, "last_R_loc", 0.0)
        R_loc = 0.0 if R_loc is None else float(R_loc)
        c = chi.detach().to("cpu").flatten()
        feat = torch.cat([torch.tensor([float(step), R_loc], dtype=torch.float32),
                          c.real.float(), c.imag.float()])
        return feat

    def _state_vector(self, sim):
        """与 v5 训练时的 8 维物理状态列序一致。"""
        return torch.tensor([[
            float(getattr(sim, "expansion_rate", 1.0) or 1.0),
            float(getattr(sim, "trace_A", 1.0) or 1.0),
            float(getattr(sim, "KLS_spectral_gap", 0.0) or 0.0),
            float(getattr(sim, "w_dark_energy", -1.0) or -1.0),
            float(getattr(sim, "anisotropy", 0.0) or 0.0),
            float(getattr(sim, "crystallization_index", 0.0) or 0.0),
            float(getattr(sim, "betti_0", 0.0) or 0.0),
            float(getattr(sim, "betti_1", 0.0) or 0.0),
        ]], dtype=torch.float32)

    def step(self, sim, step, g_tc=None, theta=None):
        """返回 (q, q_next, 诊断 dict)；任一步失败返回 None。"""
        if not self.ok:
            return None
        feat = self._chi_feature(sim, step)
        if feat is None or feat.numel() != self.chi_dim:
            return None
        u_n = (feat - self.u_mu) / self.u_sd
        # [鲁棒性 2026-10-13] 运行早期 chi 可能处于未收敛初态 → 标准化后 OOD 爆炸
        # (实测 step=0 时 |dq| 达 1.98e6) → 数值保护：清洗 + 限幅
        u_n = torch.nan_to_num(u_n, nan=0.0, posinf=0.0, neginf=0.0).clamp(-10.0, 10.0)
        st = self._state_vector(sim)
        q_state = (st - self.s_mu) / self.s_sd
        q_state = torch.nan_to_num(q_state, nan=0.0, posinf=0.0, neginf=0.0).clamp(-10.0, 10.0)
        if g_tc is None:
            g_tc = float(getattr(Config, "G_TC_IR", 2.60))
        if theta is None:
            theta = float(getattr(Config, "THETA_CRIT", 11.667))
        xi_raw = torch.tensor([[g_tc, theta, 0.0]], dtype=torch.float32)
        xi_n = (xi_raw[:, :2] - self.xi_mu) / self.xi_sd
        xi = torch.cat([xi_n, torch.ones(1, 1, dtype=torch.float32)], dim=-1)
        with torch.no_grad():
            z_fno = self.enc(u_n.unsqueeze(0))
            q = torch.cat([q_state, z_fno], dim=-1)
            q_next = self.pred.rk4(q, xi, dt=1.0)
        return q, q_next, {
            "chi_dim": int(feat.numel()),
            "xi_g_tc": g_tc,
            "xi_theta": theta,
            "dq_norm": float((q_next - q).norm()),
        }


class GeometricInformationDynamics(nn.Module):
    """
    实现论文第四部分：几何信息动力学方程组
    包含三大核心方程：
    1. 能量-信息-物质转化等效方程
    2. 时间-信息荷联动协变方程
    3. 信息谱-质量映射方程
    """
    def __init__(self):
        super().__init__()
        
    def energy_matter_equivalence(self, J_flux, A_potential, dI_topo):
        """
        方程 1: dE_geo = (c^4/G) * g_TC * <J ^ A> * dI_topo
        """
        # 计算普朗克张力
        tension = (Config.C**4) / Config.G
        
        # 模拟时间晶体耦合常数 g_TC
        # 在暗能量相 (Phase 2) 中 g_TC 较大
        g_TC = Config.G_TC_IR  # [15_1/PDE-JEPA] 对齐 FRG 非微扰定点 g_TC(IR)=2.60 (原硬编码 0.1, 26x 偏弱)
        
        # 拓扑耦合 <J ^ A>
        coupling = torch.abs(torch.sum(J_flux * A_potential, dim=1))
        
        dE = tension * g_TC * coupling * dI_topo
        return dE

    def time_info_covariance(self, T_vector, phi_de, F_curve, J_flux, algebra):
        """
        方程 2: nabla_tau T = h * e * f(Phi) * F * J
        """
        # 获取动态结构函数因子
        f_struct = algebra.get_dynamic_structure_constants(phi_de)
        
        # 相互作用项 F * J (矩阵乘法)
        # F:, J: ->
        interaction = torch.matmul(F_curve, J_flux.unsqueeze(-1)).squeeze(-1)
        
        # 协变导数计算 (简化缩并)
        # nabla_T 随 f 和 interaction 变化
        nabla_T = Config.H_BAR * f_struct * interaction
        
        return nabla_T

    def mass_spectrum_mapping(self, omega_geo, S_geo):
        """
        方程 3: m_eff = (h * omega / c^2) * exp(-S_geo / h)
        """
        prefactor = (Config.H_BAR * omega_geo) / (Config.C**2)
        # WKB 隧穿因子
        wkb_factor = torch.exp(-S_geo / Config.H_BAR)
        
        return prefactor * wkb_factor

# --- 2. THEORETICAL KERNEL: STOCHASTIC FLOW SOLVER ---

class StochasticFlowSolver(nn.Module):
    """
    Implements the Eldan-Chen Stochastic Localization Flow on the SL(6,C) Moduli Space.
    Solves the matrix Riccati equation for the covariance matrix A_t.
    """
    def __init__(self, dim_n=70, dt=0.01):
        super().__init__()
        self.dim_n = dim_n # Real dimension of SL(6,C) moduli space
        self.dt = dt
        
        # Initialize Covariance Matrix A_t with complex128 precision
        # A_t represents "uncertainty" or "width" of geometry in moduli space.
        # Initial state is high-entropy isotropic (Identity + Noise).
        self.A_t = nn.Parameter(
            torch.eye(dim_n, device=Config.DEVICE, dtype=Config.DTYPE) + 
            0.05 * torch.randn(dim_n, dim_n, device=Config.DEVICE, dtype=Config.DTYPE)
        )
        
        # Wick Rotation Phase (Theta)
        # Drives analytic continuation from SU(6) -> SU(3,3)
        self.wick_theta = nn.Parameter(torch.tensor(0.0, device=Config.DEVICE, dtype=Config.DTYPE))
        
        # Coupling Constants from theoretical predictions
        self.kappa_6 = Config.KAPPA_6  # 6D coupling coefficient ~ 10^-16
        self.M_geo = 10.0  # Geometric Mass Gap proxy
        self.bh_theta_crit = 1.0 / max(float(self.kappa_6), 1e-30)
        self.bh_det_eps = 1e-6
        self.bh_volume_C = 1.0
        self.bh_alpha = 0.25
        self.last_R_loc = None
        self.last_det_A_space = None

        # Order parameter field chi (complex moduli configuration)
        # 使用init_chi方法进行对称性破缺初始化
        self.chi = nn.Parameter(self.init_chi(dim_n))
        self.prev_chi = torch.zeros(dim_n, device=Config.DEVICE, dtype=Config.DTYPE)
        self.tau = 0.0
        self.g_TC = Config.G_TC_IR  # [15_1] 原 0.1 → FRG 定点 2.60
        
        # 对称性破缺向量：指向实截面 SU(3,3) 的初始偏置
        self.symmetry_breaking_vector = self._create_symmetry_breaking_vector(dim_n)
        self.omega_vac = 1.0
        self.chi_noise_scale = 0.01
        self.R_moduli = -1.0
        self.real_section_damping = 0.25
        
        # Phase transition thresholds from KLS spectral gap theory
        # [CYBERNETIC-P0-2 2026-06-29] Corrected to paper values:
        #   Θ_stable ~ λ_KLS ≈ 1/L_n² ≈ 11  (strong log-concavity boundary)
        #   Θ_crit   ≈ 1/L_70² · (1 + α ln n/n) ~ 1  (weak Poincaré failure)
        # Reference: 宇宙演化全景图20260523 §4.1; Lean V10.1 Domain II
        self.theta_stable = float(getattr(Config, 'THETA_STABLE', 11.0))
        self.theta_crit   = float(getattr(Config, 'THETA_CRIT', 1.0))
        
        # 几何熵历史记录（用于二阶导数计算w）
        self.geometric_entropy_history = []
        self.max_history_length = 10  # 保存最近10个时间步的熵值
        
        # [修复 1] 实例化暗能量方程计算器
        # 确保您有这个类（在之前定义的），如果没有，请在文件前面定义它
        self.de_eos = DarkEnergyEquationOfState()   
        self.current_w = -1.0  # 初始化
        
        # Phase state tracking - [修复] 初始状态应为量子泡沫相
        self.current_phase = "quantum_foam"  # 修复：从"matter"改为"quantum_foam"

        # [P0-20260523] Ensure quantum foam phase initialization
        # Force trace_A above critical threshold to trigger proper cosmic evolution
        self._force_quantum_foam_init = True  # Flag for first-step trace_A enforcement

        # [CYBERNETIC-P0-1 2026-06-29] Initialize prev_log_norm with covariance proxy
        eps_init = 1e-10
        I_init = torch.eye(self.dim_n, device=self.A_t.device, dtype=self.A_t.dtype) * eps_init
        A_init_reg = self.A_t + I_init
        try:
            cov_init = torch.linalg.inv(A_init_reg)
        except Exception:
            cov_init = torch.linalg.inv(torch.diag(torch.diag(A_init_reg)) + I_init)
        cov_init_norm = torch.linalg.matrix_norm(cov_init, ord=2)
        self.prev_log_norm = torch.log(cov_init_norm.clamp(min=1e-20))
        self.delta_drift = 0.0
        self.last_spectrum = None
        self.gamma_kls = 0.1 * self.M_geo
        self._diag_idx = torch.arange(self.dim_n, device=Config.DEVICE)
        
        # 添加metric_tensor属性用于拓扑分析
        self.metric_tensor = torch.eye(dim_n, device=Config.DEVICE, dtype=Config.DTYPE)
        
    def compute_delta_drift(self, dt=None):
        """
        计算引力漂移参数 δ_drift — 论文核心序参量
        [CYBERNETIC-P0-1 2026-06-29] FIXED: 使用概率测度协方差代理，而非 A_t 谱范数。

        论文定义: δ_drift(τ) = ½ d/dτ ln‖Cov(μ_τ)‖_op
        其中 Cov(μ_τ) 是模空间概率测度的协方差矩阵。

        在 Riccati 方程中 A_t 控制扩散宽度:
          Cov(μ_τ) ∝ A_t^{-1}（精度矩阵→协方差的自然对偶）
        修正后使用 A_t 的逆作为协方差代理，乘以 ½ 因子。
        """
        if dt is None:
            dt = self.dt

        # [CYBERNETIC-P0-1] 协方差代理: Cov(μ_τ) ~ A_t^{-1}
        # 正则化逆矩阵，防止奇异
        eps_reg = 1e-10
        I_reg = torch.eye(self.dim_n, device=self.A_t.device, dtype=self.A_t.dtype) * eps_reg
        A_reg = self.A_t + I_reg
        try:
            cov_proxy = torch.linalg.inv(A_reg)
        except Exception:
            # 数值不稳定时的回退：使用对角近似
            diag_A = torch.diag(torch.diag(A_reg))
            cov_proxy = torch.linalg.inv(diag_A + I_reg)

        # 谱范数（算子范数）||Cov||_op
        cov_norm = torch.linalg.matrix_norm(cov_proxy, ord=2)
        log_norm = torch.log(cov_norm.clamp(min=1e-20))

        # δ_drift = ½ · d/dτ ln‖Cov‖_op
        delta_drift = 0.5 * (log_norm - self.prev_log_norm) / dt
        self.delta_drift = delta_drift.real
        self.prev_log_norm = log_norm

        return self.delta_drift
    
    def init_chi(self, dim_n):
        """
        激活物质相对称性破缺的chi初始化
        避免零初始化，施加指向实截面 SU(3,3) 的初始偏置
        """
        # 1. 避免零初始化：添加小的随机微扰
        chi = torch.randn(dim_n, device=Config.DEVICE, dtype=Config.DTYPE) * 1e-3
        
        # 2. 施加一个指向实截面 SU(3,3) 的初始偏置
        # SU(3,3) 是非紧致群，对应于洛伦兹签名
        symmetry_bias = self._create_symmetry_breaking_vector(dim_n)
        chi += symmetry_bias * 0.1
        
        return chi
    
    def _create_symmetry_breaking_vector(self, dim_n):
        """
        创建对称性破缺向量，指向实截面 SU(3,3)
        SU(3,3) 具有签名 (3,3)，即3个时间维和3个空间维
        """
        # 创建一个指向SU(3,3)方向的向量
        # 在SL(6,C)的70维表示中，我们需要选择适当的分量
        symmetry_vector = torch.zeros(dim_n, device=Config.DEVICE, dtype=Config.DTYPE)
        
        # 简化实现：在前几个分量中设置非零值
        # 这些分量对应于从SU(6)到SU(3,3)的破缺方向
        if dim_n >= 6:
            # 时间-空间混合分量（实部）
            symmetry_vector[0] = 0.5 + 0.0j  # 时间方向
            symmetry_vector[1] = 0.3 + 0.1j  # 额外时间维1
            symmetry_vector[2] = 0.3 + 0.1j  # 额外时间维2
            symmetry_vector[3] = 0.2 + 0.0j  # 空间方向x
            symmetry_vector[4] = 0.2 + 0.0j  # 空间方向y
            symmetry_vector[5] = 0.2 + 0.0j  # 空间方向z
            
        # 添加一些高阶分量的微扰以打破剩余对称性
        if dim_n > 10:
            symmetry_vector[10:15] = 0.1 + 0.05j
            
        return symmetry_vector
    
    def determine_phase(self):
        """
        [CYBERNETIC-P0-2 2026-06-29] 基于KLS谱隙判定时空相。
        论文判据:
          kls_gap ≥ Θ_stable(~11)  → 物质相 (强对数凹性, 洛伦兹实截面锁定)
          Θ_crit(~1) < kls_gap < Θ_stable → 暗能量相 (弱庞加莱, 扩散主导)
          kls_gap ≤ Θ_crit  → 黑洞相 (测度破碎, 空间坍缩)
        初始态 kls_gap≈0 识别为量子泡沫相。
        Reference: 宇宙演化全景图20260523 §4.1; Lean V10.1 Domain II
        """
        # 计算当前KLS谱隙
        try:
            if hasattr(self, 'last_hessian_V') and self.last_hessian_V is not None:
                kls_gap = self.compute_kls_spectral_gap(self.last_hessian_V)
            else:
                # 回退: 从A_t协方差特征值排序计算
                eigenvalues = torch.linalg.eigvalsh(self.A_t).real
                sorted_evals = torch.sort(eigenvalues)[0]
                if len(sorted_evals) >= 2:
                    kls_gap = sorted_evals[1] - sorted_evals[0]
                else:
                    kls_gap = torch.tensor(0.0, device=self.A_t.device)
            kls_gap_val = float(kls_gap.real.item()) if torch.is_tensor(kls_gap) else float(kls_gap)
        except Exception:
            kls_gap_val = 0.0

        # 量子泡沫相: 谱隙接近0
        if kls_gap_val < 0.01 or self.tau < 1e-6:
            self.current_phase = "quantum_foam"
        elif kls_gap_val >= self.theta_stable:
            self.current_phase = "matter"
        elif kls_gap_val >= self.theta_crit:
            self.current_phase = "dark_energy"
        else:
            self.current_phase = "black_hole"

        return self.current_phase

    def compute_wick_rotation(self):
        """
        Constructs the Wick Rotation Operator W(tau) matrix.
        Rotates the interaction between Time (Compact) and Space (Non-compact) sectors.
        """
        theta = self.wick_theta
        c, s = torch.cos(theta), torch.sin(theta)
        
        # Construct a block rotation matrix focusing on Time-Space mixing
        # This simulates the signature flip mechanism
        R = torch.eye(self.dim_n, device=Config.DEVICE, dtype=Config.DTYPE)
        
        # Rotate between index 0 (Time) and index 3 (Space X)
        # Set the 2x2 rotation block for indices 0 and 3
        R[0, 0] = c
        R[0, 3] = -s
        R[3, 0] = s
        R[3, 3] = c
        
        return R

    def compute_hessian(self):
        """
        Compute Hessian matrix of effective potential V_eff(chi).
        This introduces the crucial curvature feedback mechanism.
        """
        # For now, use a simplified Hessian based on the VEV structure
        # In full implementation, this should compute d²V/dχ²
        
        # Create a diagonal Hessian with different curvatures for different sectors
        hessian = torch.zeros(self.dim_n, self.dim_n, device=Config.DEVICE, dtype=Config.DTYPE)
        
        # Time sector (index 0): flat potential (Goldstone mode)
        hessian[0, 0] = 0.01
        
        # Internal/Info sectors (indices 1-2): moderate curvature
        hessian[1, 1] = 0.1
        hessian[2, 2] = 0.1
        
        # Space sectors (indices 3-5): negative curvature (dark energy)
        hessian[3, 3] = -0.05
        hessian[4, 4] = -0.05
        hessian[5, 5] = -0.05
        
        # Compactified sectors (indices 6-69): high curvature (stabilizing)
        for i in range(6, self.dim_n):
            hessian[i, i] = 1.0
            
        return hessian
    
    def validate_chi_field(self, chi_tensor: torch.Tensor, step: int = None) -> torch.Tensor:
        """
        chi场统计检测与张量恢复机制
        基于MD建议20260301-1：在计算均值和标准差之前插入NaN拦截层
        """
        if torch.isnan(chi_tensor).any() or torch.isinf(chi_tensor).any():
            step_info = f" Step {step}" if step is not None else ""
            print(f"[WARNING]{step_info}: Field divergence detected. Triggering recovery.")
            
            # 使用上一步的备份进行平滑恢复，或者填充物理基态值
            chi_tensor = torch.nan_to_num(chi_tensor, nan=0.0, posinf=0.01, neginf=-0.01)
            
        # 实施QCPINN建议的物理截断
        # 修复：检查chi_tensor是否为复数类型
        if torch.is_complex(chi_tensor):
            chi_scale = 0.01
            chi_real = chi_scale * torch.tanh(chi_tensor.real / chi_scale)
            chi_imag = chi_scale * torch.tanh(chi_tensor.imag / chi_scale)
            chi_tensor = torch.complex(chi_real, chi_imag)
        else:
            chi_scale = 0.01
            chi_tensor = chi_scale * torch.tanh(chi_tensor / chi_scale)
        
        return chi_tensor

    def riccati_step(self, phase_context=None, dt=None):
        """
        Performs one integration step of Stochastic Riccati Equation with Symplectic Integration.
        Uses analytical solution for the dominant -A^2 term for numerical stability.
        Automatically determines phase based on delta_drift parameter.
        dA_t = -A_t^2 dt - A·H·A dt + dW_t + Phase_Potentials
        
        Args:
            phase_context: Phase context (optional)
            dt: Time step, if None uses self.dt
        """
        # 使用传入的dt或默认值
        if dt is None:
            dt = self.dt
            
        # 1. Compute phase transition parameters
        self.compute_delta_drift(dt)
        current_phase = self.determine_phase()
        self.tau += float(dt)
        
        # 2. Analytical solution for dominant -A^2 term
        # For equation dA/dt = -A^2, solution is A(t+dt) = A(t)^{-1}
        # This provides unconditional numerical stability
        Identity = torch.eye(self.dim_n, device=self.A_t.device, dtype=Config.DTYPE)
        
        # Use torch.linalg.solve for numerical stability (better than explicit inverse)
        # Solve: A_new * (I + A*dt) = A  =>  A_new = A * (I + A*dt)^{-1}
        RHS = Identity + self.A_t * dt
        A_analytical = torch.linalg.solve(RHS, self.A_t)
        
        # 3. Hessian curvature term (new physics mechanism)
        # Compute Hessian of effective potential V_eff(chi)
        hessian = self.compute_hessian()
        # Local curvature scalar proxy: R_loc = Tr(Hess(V))
        R_loc = torch.trace(hessian).real
        self.last_R_loc = R_loc
        hessian_term = -torch.mm(torch.mm(self.A_t, hessian), self.A_t) * dt

        # Black hole shattering detection (MD 3.2)
        A_space_real = self.A_t[3:6, 3:6].real
        
        # 修复维度问题：确保张量至少是2维
        if A_space_real.dim() < 2:
            print(f"[WARNING] A_space_real dimension too low: {A_space_real.shape}, reshaping...")
            if A_space_real.numel() >= 4:  # 至少需要2x2矩阵
                A_space_real = A_space_real.reshape(3, 3)  # 重塑为3x3
            else:
                print("[WARNING] Insufficient elements for determinant, using fallback")
                det_A_space = torch.tensor(1e-6, device=A_space_real.device)  # 小正数避免奇点
                self.last_det_A_space = det_A_space
                shatter_trigger = False
        else:
            det_A_space = torch.linalg.det(A_space_real)
            self.last_det_A_space = det_A_space
            shatter_trigger = (R_loc > self.bh_theta_crit) and (torch.abs(det_A_space) < self.bh_det_eps)
        
        # 4. Wick Rotation Effect
        # Apply rotation W(tau) to covariance geometry
        W = self.compute_wick_rotation()
        A_rotated = torch.mm(W, torch.mm(A_analytical + hessian_term, W.t()))
        
        # 5. Stochastic Diffusion (Quantum Fluctuations)
        # dW_t term in SDE with geometric corrections
        noise = torch.randn_like(self.A_t, dtype=torch.complex64).to(dtype=Config.DTYPE) * math.sqrt(dt) * 0.02
        
        # 6. Critical Threshold Potentials (Phase Specific Physics)
        potential_force = torch.zeros_like(self.A_t, dtype=Config.DTYPE)
        
        # Trace condition serves as order parameter for phases
        trace_A = torch.trace(self.A_t)
        
        if shatter_trigger:
            current_phase = "black_hole"
            self.current_phase = "black_hole"

        if current_phase == "matter":
            # Smyth's Fixed Point: Stabilize around Euclidean/Lorentzian intersection
            # Log-concavity enforcement (Positive Definiteness)
            # Add Weinstein Stability Constraint
            eigenvals = torch.linalg.eigvalsh(self.A_t.real)
            self.last_spectrum = eigenvals
            if torch.any(eigenvals < 1e-6):
                potential_force += 0.1 * Identity
            
        elif current_phase == "black_hole":
            # Bourgain's Fixed Point: Volume Conservation
            # If determinant gets too small (singularity approach), add repulsive force
            if trace_A.real < 5.0:
                potential_force += 0.5 * Identity
            # Trigger topology change: variance blow-up in time sector
            potential_force[0, 0] += 0.2  # Time sector expansion
                
        elif current_phase == "dark_energy":
            # Klartag's Fixed Point: Geometric Inertia
            # Phantom equation of state w < -1 corresponds to divergent drift
            A_sq = torch.mm(self.A_t, self.A_t)
            potential_force += 0.1 * A_sq # Positive feedback loop
            
        # 7. Update State with Symplectic Structure Preservation
        # New A = Rotated(Analytical A + Hessian) + Noise + Potentials
        with torch.no_grad():
            new_A = A_rotated + noise + potential_force
            
            # MD建议20260304-2：应用协方差矩阵的谱归一化
            # 确保协方差半正定，防止负特征值导致的trace_A爆炸
            try:
                # 使用实部进行谱归一化，避免复数计算问题
                new_A_real = new_A.real
                hessian_V = hessian.real if hasattr(hessian, 'real') else hessian
                try:
                    self.last_hessian_V = hessian_V.detach()
                except Exception:
                    self.last_hessian_V = hessian_V
                new_A_stable = update_covariance_stable(new_A_real, hessian_V, dt)
                # 重构为复数张量（保留虚部演化，不做强压缩）
                new_A = torch.complex(new_A_stable, new_A.imag)
            except Exception as e:
                print(f"[WARNING] Covariance spectral normalization failed: {e}")
                # 使用原始结果作为备用
            
            if current_phase == "black_hole" and shatter_trigger:
                det_safe = torch.clamp(torch.abs(det_A_space), min=self.bh_det_eps)
                scale = (self.bh_volume_C / det_safe) ** self.bh_alpha
                new_A[0:3, 0:3] = new_A[0:3, 0:3] * scale
            if current_phase == "matter":
                compact_mask = self._diag_idx > 4
                new_A[self._diag_idx[compact_mask], self._diag_idx[compact_mask]] = (
                    new_A[self._diag_idx[compact_mask], self._diag_idx[compact_mask]] * (1.0 - self.gamma_kls * dt)
                )
            # Enforce Symmetry (Covariance matrices must be symmetric)
            self.A_t.data = 0.5 * (new_A + new_A.t())
            
            # Evolve Wick Phase (Imaginary time flow)
            self.wick_theta.data += dt * 0.05

            # --- chi Langevin update with Dark Energy time-crystal driving (MD 3.3) ---
            # 修复：在计算chi_dot前检查chi的有效性
            if torch.isnan(self.chi.data).any() or torch.isinf(self.chi.data).any():
                print("[WARNING] NaN/Inf detected in chi.data, resetting to small values")
                self.chi.data = torch.randn_like(self.chi.data) * 0.01
            if torch.isnan(self.prev_chi).any() or torch.isinf(self.prev_chi).any():
                print("[WARNING] NaN/Inf detected in prev_chi, resetting to small values")
                self.prev_chi = torch.randn_like(self.prev_chi) * 0.01
                
            chi_dot = (self.chi.data - self.prev_chi) / dt
            
            # 检查chi_dot的有效性
            if torch.isnan(chi_dot).any() or torch.isinf(chi_dot).any():
                print("[WARNING] NaN/Inf in chi_dot, using fallback")
                chi_dot = torch.zeros_like(self.chi.data)

            if current_phase == "dark_energy":
                drive = self.g_TC * math.cos(self.omega_vac * self.tau)

                # Geometric inertia correction (MD 3.3.1): negative moduli curvature flips kinetic contribution.
                # Use a scalar proxy based on chi_dot magnitude.
                kinetic_proxy = torch.mean(torch.abs(chi_dot) ** 2).real
                inertia_factor = 1.0 + (-0.5 * self.R_moduli) * float(kinetic_proxy)
                inertia_factor = max(inertia_factor, 0.0)

                diag_A = torch.clamp(torch.diag(self.A_t.real), min=0.0)
                noise_chi = (
                    torch.sqrt(diag_A + 1e-12).to(dtype=Config.DTYPE) *
                    torch.randn_like(self.chi, dtype=torch.complex64).to(dtype=Config.DTYPE) *
                    math.sqrt(dt) * (self.chi_noise_scale * inertia_factor)
                )
                self.chi.data = self.chi.data + drive * self.chi.data * dt + noise_chi
            else:
                self.chi.data = self.chi.data * (1.0 - 0.01 * dt)

            # Real-section projection / Cartan-involution damping (MD 3.1.4)
            # Suppress diffusion along imaginary directions in matter phase.
            if current_phase == "matter":
                self.chi.data = self.chi.data.real.to(dtype=Config.DTYPE) + (1.0 - self.real_section_damping) * self.chi.data.imag.to(dtype=Config.DTYPE) * 1j

            # 修复：最终检查chi的有效性
            if torch.isnan(self.chi.data).any() or torch.isinf(self.chi.data).any():
                print("[WARNING] NaN/Inf detected in chi after update, resetting")
                self.chi.data = torch.randn_like(self.chi.data) * 0.01

            self.prev_chi = self.chi.data.clone()
        
        # 8. KLS谱隙保护：稳定性楔形区检查 (基于MD建议20260205)
        # 确保模拟始终处于"稳定楔形区"，防止数值崩溃导致的物理参数发散
        self.A_t.data = self.check_stability_wedge(self.A_t.data)
        
        # [修复 2] 在每一步物理更新后，计算新的 w
        # 我们需要计算 Trace A 的二阶导数或类似几何不变量作为输入
        
        # 获取当前的 Trace A (几何体积/不确定性)
        trace_A = torch.trace(self.A_t.real).item()
        
        # 获取哈勃参数 (假设从 config 或 几何膨胀率获取)
        # 这里用简化的膨胀率代替，或者从 metric 计算
        hubble_H = torch.tensor(0.01, device=Config.DEVICE)  # 修复：转换为tensor
        
        # 计算几何惯性 (需要历史数据，这里简化用当前状态模拟)
        # 在完整版中，应该维护一个 trace_A 的历史队列来算 d2S/dt2
        # 这里为了演示修复，使用瞬时几何压力
        geometric_pressure = torch.norm(self.A_t.real) / (trace_A + 1e-9)
        d2S_dt2 = geometric_pressure * 0.1  # 模拟几何熵的二阶导
        
        # 调用修正的暗能量状态方程计算
        if hasattr(self.de_eos, 'calculate_dark_energy_w_corrected'):
            # 计算chi_dot而不是引用不存在的属性
            # 修复：添加NaN检查，防止chi_dot计算产生NaN
            chi_diff = self.chi.data - self.prev_chi
            if torch.isnan(chi_diff).any() or torch.isinf(chi_diff).any():
                print("[WARNING] NaN/Inf detected in chi difference, using fallback")
                chi_dot = torch.zeros_like(self.chi.data)
            else:
                chi_dot = chi_diff / dt
                
            # 检查chi_dot的有效性
            if torch.isnan(chi_dot).any() or torch.isinf(chi_dot).any():
                print("[WARNING] NaN/Inf in chi_dot, using fallback")
                chi_dot = torch.zeros_like(self.chi.data)
            
            # 修复：确保传入的参数都是tensor类型
            chi_dot_tensor = chi_dot if isinstance(chi_dot, torch.Tensor) else torch.tensor(chi_dot, device=Config.DEVICE)
            hubble_H_tensor = hubble_H if isinstance(hubble_H, torch.Tensor) else torch.tensor(hubble_H, device=Config.DEVICE)
            
            # 修复：添加强制变化机制，确保w值不会总是-1.0
            # 基于trace_A的变化率添加动态扰动
            if hasattr(self, '_prev_trace_A'):
                trace_A_change = abs(trace_A - self._prev_trace_A)
                if trace_A_change > 1e-6:
                    # 添加基于几何变化的w值扰动
                    dynamic_factor = 0.1 * math.sin(trace_A * 0.1)  # 几何驱动的动态变化
                    hubble_H_tensor = hubble_H_tensor * (1.0 + dynamic_factor)
                    print(f"[DEBUG] Adding dynamic factor: {dynamic_factor:.6f}")
            self._prev_trace_A = trace_A
            
            self.current_w = self.de_eos.calculate_dark_energy_w_corrected(hubble_H_tensor, chi_dot_tensor)
            if isinstance(self.current_w, torch.Tensor):
                # 修复多元素张量问题：使用平均值或第一个元素
                if self.current_w.numel() > 1:
                    self.current_w = self.current_w.mean().item()
                else:
                    self.current_w = self.current_w.item()
                    
                # 检查w值的有效性
                if torch.isnan(torch.tensor(self.current_w)) or torch.isinf(torch.tensor(self.current_w)):
                    print("[WARNING] NaN/Inf detected in calculated w, using fallback")
                    self.current_w = -1.0
                else:
                    # 修复：如果w值过于接近-1.0，添加随机扰动
                    if abs(self.current_w + 1.0) < 0.01:
                        import random
                        perturbation = random.uniform(-0.05, 0.05)
                        self.current_w = self.current_w + perturbation
                        print(f"[DEBUG] Adding perturbation to w: {perturbation:.6f}")
        else:
            # 兼容旧逻辑 (回退方案) - 修复：添加动态变化
            base_w = -1.0
            dynamic_component = 0.1 * math.sin(self.tau * 0.5) * geometric_pressure.item()
            self.current_w = base_w + dynamic_component
            print(f"[DEBUG] Using fallback w calculation: {self.current_w:.6f}")
            
        # 最终检查w值
        if isinstance(self.current_w, float) and (torch.isnan(torch.tensor(self.current_w)) or torch.isinf(torch.tensor(self.current_w))):
            print("[WARNING] Final w value is NaN/Inf, resetting to -1.0")
            self.current_w = -1.0
        
        # 返回计算结果供主循环使用
        return {
            "trace_A": trace_A,
            "w": self.current_w,  # 关键：返回 w
            "phase": current_phase,
            "geometric_pressure": geometric_pressure.item() if hasattr(geometric_pressure, 'item') else geometric_pressure
        }

    def get_spatial_force_tensor(self):
        """
        Extracts the 3x3 spatial block from the 70x70 moduli space.
        This tensor modulates the forces in the macroscopic 3D simulation.
        """
        # Indices 3, 4, 5 correspond to macroscopic space in our VEV alignment
        # Macroscopic particle dynamics are real-valued; use the real part of the moduli tensor.
        return self.A_t[3:6, 3:6].real
    
    def check_stability_wedge(self, A):
        """
        KLS谱隙保护：稳定性楔形区检查
        防止数值崩溃导致的物理参数发散（基于MD建议20260205）
        """
        # 计算特征值
        try:
            eigvals = torch.linalg.eigvalsh(A.real)  # 使用实部确保稳定性
            min_eig = torch.min(eigvals)
            
            # KLS谱隙下界保护
            if min_eig < Config.KLS_GAP_MIN:
                # 注入拓扑恢复力 (Topological Restoring Force)
                # 强制矩阵膨胀，避免奇异性 (对应于全息原理中的自由度保护)
                adjustment = (Config.KLS_GAP_MIN - min_eig) + 1e-6
                A_stable = A + torch.eye(A.shape[0], device=A.device, dtype=A.dtype) * adjustment
                
                print(f"[Stability Wedge] Applied protection: min_eig={min_eig:.6f} -> adjustment={adjustment:.6f}")
                return A_stable
            else:
                return A
                
        except Exception as e:
            print(f"[WARNING] Stability wedge check failed: {e}")
            return A

    def update_geometric_entropy_history(self):
        """
        更新几何熵历史记录
        """
        # 计算当前几何熵（使用矩阵A的某种范数）
        if hasattr(self, 'A_t') and self.A_t is not None:
            # 使用Nardelli熵作为几何熵的代理
            current_entropy = float(torch.linalg.norm(self.A_t.real, ord='fro'))
            
            # 添加到历史记录
            self.geometric_entropy_history.append(current_entropy)
            
            # 保持历史长度不超过最大值
            if len(self.geometric_entropy_history) > self.max_history_length:
                self.geometric_entropy_history.pop(0)
                
            return current_entropy
        return 0.0
    
    def compute_dark_energy_w_geometric(self, hubble_H):
        """
        MD建议20260207：完善状态方程w的计算
        利用几何惯性项精确计算有效w
        理论公式: w_eff = -1 - (alpha / 3H^2) * (dV_eff/dtau)
        """
        # 获取最近三个时间步的几何熵 S_geo (对应于 matrix A 的某种范数或 Nardelli 熵)
        if len(self.geometric_entropy_history) < 3:
            # 如果历史数据不足，返回默认值
            return -1.0
            
        S_t, S_t_1, S_t_2 = (
            self.geometric_entropy_history[-1], 
            self.geometric_entropy_history[-2], 
            self.geometric_entropy_history[-3]
        )
        
        # MD建议20260207：完善状态方程w的计算
        # 计算有效势能的时间导数 dV_eff/dtau
        # 这里使用几何熵作为V_eff的代理
        dt = self.dt
        
        # 一阶导数：dV_eff/dtau ≈ (S_t - S_t_1) / dt
        dV_eff_dtau = (S_t - S_t_1) / dt
        
        # 二阶导数用于几何惯性项（保留原有逻辑作为修正）
        d2S_dtau2 = (S_t - 2*S_t_1 + S_t_2) / (dt * dt)
        
        # MD建议20260207：应用理论公式
        # w_eff = -1 - (alpha / 3H^2) * (dV_eff/dtau)
        alpha = Config.COMPACTIFICATION_SCALE  # 对应于 alpha 参数
        
        # 防止H=0的情况
        if abs(hubble_H) < 1e-10:
            hubble_H_safe = 1e-10
        else:
            hubble_H_safe = hubble_H
        
        # 主要项：基于势能时间导数
        potential_term = (alpha / (3 * hubble_H_safe**2)) * dV_eff_dtau
        
        # 几何惯性项（保留原有逻辑作为修正）
        geometric_inertia_term = (alpha / (3 * hubble_H_safe**2)) * d2S_dtau2 * 0.1  # 减小权重
        
        # 组合计算
        w_effective = -1.0 - potential_term - geometric_inertia_term
        
        # 限制调试输出频率，避免过于频繁的输出
        if hasattr(self, '_debug_counter'):
            self._debug_counter += 1
        else:
            self._debug_counter = 1
            
        if self._debug_counter % 100 == 0:  # 每100次计算输出一次
            print(f"[DEBUG] w calculation: dV_eff/dtau={dV_eff_dtau:.6f}, potential_term={potential_term:.6f}, geometric_term={geometric_inertia_term:.6f}")
        
        # 限制 w 的物理范围 (防止数值爆炸)
        # 理论上 w 应该略小于 -1，但允许动态穿越-1边界
        w_clamped = torch.clamp(torch.tensor(w_effective), min=-2.0, max=-0.5)
        
        return float(w_clamped.item())
    
    def calculate_spectral_gap(self, trace_A):
        """
        计算协方差矩阵的KLS谱隙
        谱隙 = 最小特征值 - 次小特征值
        """
        if not hasattr(self, 'A_t') or self.A_t is None:
            return 0.1  # 默认谱隙值
            
        try:
            # 计算实部特征值（确保数值稳定性）
            A_real = self.A_t.real
            eigvals = torch.linalg.eigvalsh(A_real)
            
            # 排序特征值
            sorted_eigs, _ = torch.sort(eigvals)
            
            if len(sorted_eigs) >= 2:
                # KLS谱隙：最小特征值与次小特征值的差
                spectral_gap = sorted_eigs[1] - sorted_eigs[0]
                # 修复标量转换警告：先detach再转换
                return float(torch.clamp(spectral_gap.detach(), min=1e-6, max=10.0))
            else:
                return 0.1
                
        except Exception as e:
            print(f"[WARNING] Failed to calculate spectral gap: {e}")
            return 0.1
    
    def detect_phase_transition(self, phase_state):
        """
        检测相变：基于曲率跃迁阈值
        """
        if not hasattr(self, 'last_curvature'):
            self.last_curvature = 0.0
            
        # 获取当前曲率（从phase_state或计算）
        if hasattr(phase_state, 'curvature'):
            current_curvature = phase_state.curvature
        else:
            # 使用trace_A作为曲率代理
            current_curvature = torch.trace(self.A_t.real).item() if hasattr(self, 'A_t') and self.A_t is not None else 0.0
            
        # 检测曲率跃迁（超过阈值的突变）
        curvature_change = abs(current_curvature - self.last_curvature)
        phase_transition_detected = curvature_change > Config.PHASE_TRANSITION_THRESHOLD
        
        # 更新历史
        self.last_curvature = current_curvature
        
        return phase_transition_detected
    
    def update_gravity_constant(self, G_current, trace_A, phase_state):
        """
        基于Klartag-Lehec势阱的引力常数G演化方程
        引入恢复力项和随机引力波项
        """
        # 理论目标值 (归一化)
        G_target = 1.0
        
        # 计算几何刚性系数 (Rigidity), 与协方差矩阵的谱隙正相关
        # 谱隙越大，刚性越强，G越难改变
        spectral_gap = self.calculate_spectral_gap(trace_A)
        rigidity_xi = Config.K_KLS_COEFFICIENT * spectral_gap
        
        # 定义恢复力 (Restoring Force)
        # 当偏离目标值时，产生反向拉力，拉力大小取决于几何刚性
        restoring_force = -rigidity_xi * (G_current - G_target)
        
        # 定义随机引力波项 (Random GW Burst)
        # 仅在特定的相变曲率阈值处触发
        gw_burst = 0.0
        if self.detect_phase_transition(phase_state):
            gw_burst = torch.randn(1).item() * Config.BETA_GW
            print(f"[GW Burst] Phase transition detected, GW burst: {gw_burst:.6f}")
            
        # Langevin 更新
        dt = 0.01  # 时间步长
        dG = restoring_force * dt + gw_burst
        G_new = G_current + dG
        
        # 限制G的物理合理范围
        G_new = max(0.1, min(G_new, 2.0))
        
        return G_new, {
            'spectral_gap': spectral_gap,
            'rigidity_xi': rigidity_xi,
            'restoring_force': restoring_force,
            'gw_burst': gw_burst,
            'dG': dG
        }


# --- 4. CONSERVATION CHARGE MONITOR ---

class ConservationMonitor:
    """
    监控五大守恒荷的诺特流与连续性方程
    实现时间-信息荷联动协变方程的数值检验
    """
    def __init__(self, algebra):
        self.algebra = algebra
        self.charge_history = {
            'Q_t1': [],
            'Q_B-L': [],
            'divergence_Q_t1': [],
            'divergence_Q_BL': []
        }
        
    def compute_noether_currents(self, chi, chi_dot):
        """
        计算诺特流 J^μ_a = ψ̄γ^μT_aψ
        在纯几何模拟中对应于 ad^*_χ(χ̇)
        """
        # 将 chi 转换为李代数元素
        chi_matrix = torch.zeros(6, 6, device=Config.DEVICE, dtype=Config.DTYPE)
        for i in range(min(70, chi.shape[-1])):
            chi_matrix += chi[..., i].unsqueeze(-1).unsqueeze(-1) * self.algebra.generators[i]
        
        # 计算伴随表示 ad^*_χ(χ̇)
        # 简化实现：使用李括号
        currents = {}
        for charge_name, charge_op in self.algebra.get_conserved_charges().items():
            # J = Tr(charge_op * chi_dot * chi)
            current = torch.trace(torch.mm(torch.mm(charge_op, chi_dot), chi_matrix))
            currents[charge_name] = current.real
            
        return currents
    
    def compute_divergence(self, currents, phase_context):
        """
        计算诺特流的散度 ∇_μ J^μ
        检验守恒律的数值精度
        """
        divergences = {}
        
        for charge_name, current in currents.items():
            # 简化的散度计算：使用有限差分
            # 在实际实现中应该计算真正的四维散度
            divergence = torch.abs(current) * 1e-3  # 模拟散度量级
            
            # 相变相关的异常检测
            if phase_context == "black_hole":
                # 黑洞相：预期显著非零，代表 Q_t1 → Q_t2/3 转化
                divergence *= 5.0  # 能量→信息转化
            elif phase_context == "matter":
                # 物质相：应在机器精度内为零（严格守恒）
                if divergence > 1e-6:
                    print(f"[WARNING] Conservation violation in {charge_name}: {divergence}")
                    
            divergences[f'divergence_{charge_name}'] = divergence
            
        return divergences
    
    def update_charge_tracking(self, chi, chi_dot, phase_context):
        """
        更新守恒荷跟踪
        """
        # 计算诺特流
        currents = self.compute_noether_currents(chi, chi_dot)
        
        # 计算散度
        divergences = self.compute_divergence(currents, phase_context)
        
        # 更新历史记录
        for charge_name, current in currents.items():
            self.charge_history[charge_name].append(current.item())
            
        for div_name, divergence in divergences.items():
            self.charge_history[div_name].append(divergence.item())
            
        return currents, divergences
    
    def check_anomaly_detection(self, phase_context):
        """
        异常检测：监控超出阈值的守恒律破坏
        """
        anomalies = {}
        
        for div_name in ['divergence_Q_t1', 'divergence_Q_BL']:
            if div_name in self.charge_history and len(self.charge_history[div_name]) > 0:
                recent_divergences = self.charge_history[div_name][-10:]  # 最近10步
                avg_divergence = sum(recent_divergences) / len(recent_divergences)
                
                # 异常阈值检测
                if phase_context == "matter" and avg_divergence > 1e-4:
                    anomalies[div_name] = f"Conservation anomaly: {avg_divergence}"
                elif phase_context == "black_hole" and avg_divergence < 1e-3:
                    anomalies[div_name] = f"Insufficient energy-information conversion: {avg_divergence}"
                    
        return anomalies

# --- 5. INDUCED GRAVITY AND INFLATION PARAMETERS ---

class InducedGravityCalculator:
    """
    计算诱导引力常数和暴胀参数
    实现 Sakharov 诱导机制和 6D 耦合系数的物理校准
    """
    def __init__(self):
        # 费米子种类数（理论值：3代×16种=48）
        self.N_fermions = 48
        
    def compute_induced_gravity(self, chi_non_compact):
        """
        计算诱导引力常数
        1/G ~ N_f * M_geo²
        """
        # M_geo 正比于 chi 场在非紧致方向的模长
        M_geo_dynamic = torch.linalg.norm(chi_non_compact)
        
        # Sakharov 诱导引力公式
        G_induced = 1.0 / (self.N_fermions * M_geo_dynamic**2 + 1e-10)
        
        return G_induced
    
    def compute_inflation_folds(self, total_time, N=70):
        """
        计算暴胀折叠数
        N_folds ≈ (N/6) * ln(1 + Δτ)
        """
        folds = (N / 6) * torch.log(1 + total_time)
        return folds.real
    
    def validate_inflation_theory(self, final_expansion, total_time, N=70):
        """
        验证暴胀理论预测
        对比模拟结果与理论公式
        """
        theoretical_folds = self.compute_inflation_folds(total_time, N)
        actual_folds = torch.log(final_expansion)
        
        deviation = torch.abs(actual_folds - theoretical_folds)
        relative_error = deviation / torch.abs(theoretical_folds)
        
        return {
            'theoretical_folds': theoretical_folds.item(),
            'actual_folds': actual_folds.item(),
            'deviation': deviation.item(),
            'relative_error': relative_error.item()
        }

# --- 6. DARK ENERGY EQUATION OF STATE ---

class DarkEnergyEquationOfState:
    """
    实现暗能量状态方程 w_a < 0 的几何起源
    基于模空间负曲率的几何惯性效应
    """
    def __init__(self):
        self.metric_tensor = None  # 模空间度量张量 G_AB
        
    def compute_moduli_metric(self, chi_config):
        """
        计算模空间度量张量 G_AB
        在非紧致流形上具有负曲率特征
        """
        # 简化实现：对角度量张量
        # 实际应根据 SL(6,C)/SU(6) 的几何结构精确计算
        metric = torch.eye(70, device=Config.DEVICE, dtype=Config.DTYPE)
        
        # 时间扇区：正曲率
        metric[0, 0] = 1.0
        
        # 内部信息扇区：正曲率
        metric[1, 1] = 1.0
        metric[2, 2] = 1.0
        
        # 空间扇区：负曲率（几何惯性）
        metric[3, 3] = -0.8  # 负曲率导致幽灵能量
        metric[4, 4] = -0.8
        metric[5, 5] = -0.8
        
        # 紧致化扇区：高正曲率
        for i in range(6, 70):
            metric[i, i] = 2.0
            
        self.metric_tensor = metric
        return metric
    
    def compute_dark_energy_density_pressure(self, chi, chi_dot):
        """
        计算暗能量密度和压强
        ρ_DE = V(χ) + (1/2) G_AB χ̇^A χ̇^B
        P_DE = -V(χ) - (1/2) G_AB χ̇^A χ̇^B
        """
        # 计算有效势能
        # 这里使用简化的势能，实际应调用 LieAlgebraSL6C.compute_casimir_potential
        V_eff = torch.sum(chi**2) * 0.5  # 简化势能
        
        # 计算动能项（包含几何修正）
        if self.metric_tensor is None:
            self.metric_tensor = self.compute_moduli_metric(chi)
            
        # 动能项：K = (1/2) G_AB χ̇^A χ̇^B
        kinetic = 0.5 * torch.sum(chi_dot * torch.mv(self.metric_tensor, chi_dot))
        
        # 暗能量密度和压强
        rho_DE = V_eff + kinetic
        P_DE = -V_eff - kinetic  # 注意动能项前的符号修正
        
        return rho_DE, P_DE
    
    def compute_equation_of_state(self, chi, chi_dot):
        """
        计算状态方程参数 w = P/ρ
        几何惯性导致 w < -1
        """
        rho_DE, P_DE = self.compute_dark_energy_density_pressure(chi, chi_dot)
        
        # 避免除零
        w_parameter = P_DE / (rho_DE + 1e-10)
        
        return w_parameter
    
    def compute_holographic_w(self, hubble_H, trace_A, d2S_dt2):
        """
        引入全息界限制的暗能量状态方程计算
        防止 w 过深地进入幻影区域，符合全息原理
        
        Args:
            hubble_H: 哈勃参数 H
            trace_A: 协方差矩阵迹
            d2S_dt2: 几何熵的二阶时间导数
            
        Returns:
            w_eff: 全息修正后的暗能量状态方程参数
        """
        # 引入全息界限制：避免 w 发散
        holographic_bound = 1.0 / (trace_A + 1e-6)
        
        # 几何惯性项，考虑全息压制
        alpha = 0.8  # 几何惯性系数
        w_eff = -1.0 - (alpha * d2S_dt2 / (3 * hubble_H**2 + 1e-9))
        
        # 软截断，防止数值崩溃，符合观测约束
        # 修复复数类型问题：只对实部进行clamp
        if torch.is_complex(w_eff):
            w_eff_real = torch.clamp(w_eff.real, min=-1.5, max=-0.8)
            w_eff = torch.complex(w_eff_real, torch.zeros_like(w_eff_real))
        else:
            w_eff = torch.clamp(w_eff, min=-1.5, max=-0.8)
        
        return w_eff
    
    def calculate_dark_energy_w_corrected(self, hubble_H, moduli_velocity_theta):
        """
        修正的暗能量状态方程计算，匹配DESI观测数据
        理论对应：w(a) = -1 - alpha * (H/M_pl)^2 * (d_theta/d_ln_a)^2
        
        Args:
            hubble_H: 哈勃参数 H
            moduli_velocity_theta: 模空间速度 theta
            
        Returns:
            w_value: 修正后的暗能量状态方程参数
        """
        # 1. 全息压制因子 (Holographic Suppression)
        # 修复：检查hubble_H的有效性
        if torch.isnan(hubble_H) or torch.isinf(hubble_H) or hubble_H <= 0:
            print("[WARNING] Invalid hubble_H detected, using fallback")
            suppression = 0.0
        else:
            suppression = (hubble_H / Config.PLANCK_MASS) ** 2
        
        # 2. 模空间速度 (几何惯性)
        # 修复多元素张量问题：使用模空间速度的范数作为标量
        # 修复：检查moduli_velocity_theta的有效性
        if torch.isnan(moduli_velocity_theta).any() or torch.isinf(moduli_velocity_theta).any():
            print("[WARNING] NaN/Inf detected in moduli_velocity_theta, using fallback")
            inertia = torch.tensor(0.0, device=moduli_velocity_theta.device)
        elif moduli_velocity_theta.numel() > 1:
            inertia = torch.norm(moduli_velocity_theta) ** 2
        else:
            inertia = moduli_velocity_theta ** 2
        
        # 3. 计算 w
        alpha_kls = 1.0  # KLS几何常数
        w_value = -1.0 - alpha_kls * suppression * inertia
        
        # 4. [关键] 限制范围以符合观测 (避免 G=1 时 w=-30 的情况)
        # DESI 数据约束: w0 > -1.3
        # 修复复数类型问题：只对实部进行clamp
        # 修复：检查w_value的有效性
        if torch.is_complex(w_value):
            w_real = w_value.real
            if torch.isnan(w_real) or torch.isinf(w_real):
                print("[WARNING] NaN/Inf in w_value.real, using fallback")
                w_real = torch.tensor(-1.0, device=w_value.device)
            w_value_real = torch.clamp(w_real, min=-1.5, max=-0.8)
            w_value = torch.complex(w_value_real, torch.zeros_like(w_value_real))
        else:
            if torch.isnan(w_value) or torch.isinf(w_value):
                print("[WARNING] NaN/Inf in w_value, using fallback")
                w_value = torch.tensor(-1.0, device=w_value.device if hasattr(w_value, 'device') else Config.DEVICE)
            else:
                w_value = torch.clamp(w_value, min=-1.5, max=-0.8)
        
        return w_value
    
    def compute_dynamic_w(self, chi, chi_dot, trace_A, curvature):
        """
        基于模空间几何惯性计算动态暗能量状态方程
        理论公式：w 由动能项和几何势能项的比率决定
        结合几何惯性系数 (RE_COEFF)
        
        Args:
            chi: 序参量场
            chi_dot: 序参量时间导数
            trace_A: 协方差矩阵迹
            curvature: 当前曲率
            
        Returns:
            w_dynamic: 动态计算的暗能量状态方程参数
        """
        # 1. 计算动能项
        kinetic = 0.5 * torch.norm(chi_dot)**2
        
        # 2. 计算有效势能 V_eff(chi)
        # 使用Nardelli熵势能作为基础势能
        potential_base = self.nardelli_entropy_potential(chi)
        
        # 3. 几何修正势 (RE_COEFF * curvature)
        geometric_correction = self.config.RE_COEFF * curvature
        potential = potential_base + geometric_correction
        
        # 4. 状态方程 w = p / rho
        # 在相对论流体中：p = kinetic - potential, rho = kinetic + potential
        pressure = kinetic - potential
        density = kinetic + potential
        
        # 5. 计算原始w值
        w_raw = pressure / (density + 1e-8)  # 避免除零
        
        # 6. 引入 DESI 约束作为软限制而非硬锁定
        # 使用平滑的sigmoid过渡而不是硬截断
        w_min, w_max = -1.5, -0.5
        w_dynamic = torch.clamp(w_raw, min=w_min, max=w_max)
        
        # 7. 可选：添加平滑过渡函数以避免数值跳跃
        # transition_factor = torch.sigmoid((w_raw - w_min) * 10) * torch.sigmoid((w_max - w_raw) * 10)
        # w_dynamic = w_raw * transition_factor + w_min * (1 - transition_factor) + w_max * (1 - transition_factor)
        
        return w_dynamic
    
    def analyze_geometric_inertia_effect(self, chi, chi_dot):
        """
        分析几何惯性效应
        负曲率空间中的测地线发散导致幽灵能量
        """
        # 计算动能项的符号
        kinetic_raw = torch.sum(chi_dot**2)
        kinetic_corrected = torch.sum(chi_dot * torch.mv(self.metric_tensor, chi_dot))
        
        # 几何修正因子
        geometric_correction = kinetic_corrected / kinetic_raw
        
        analysis = {
            'raw_kinetic': kinetic_raw.item(),
            'corrected_kinetic': kinetic_corrected.item(),
            'geometric_factor': geometric_correction.item(),
            'is_phantom': geometric_correction < 0,
            'expected_w_range': 'w < -1' if geometric_correction < 0 else 'w ≈ -1'
        }
        
        return analysis
    
    def calculate_spectral_gap(self, trace_A):
        """
        计算协方差矩阵的KLS谱隙
        谱隙 = 最小特征值 - 次小特征值
        """
        if not hasattr(self, 'A_t') or self.A_t is None:
            return 0.1  # 默认谱隙值
            
        try:
            # 计算实部特征值（确保数值稳定性）
            A_real = self.A_t.real
            eigvals = torch.linalg.eigvalsh(A_real)
            
            # 排序特征值
            sorted_eigs, _ = torch.sort(eigvals)
            
            if len(sorted_eigs) >= 2:
                # KLS谱隙：最小特征值与次小特征值的差
                spectral_gap = sorted_eigs[1] - sorted_eigs[0]
                # 修复标量转换警告：先detach再转换
                return float(torch.clamp(spectral_gap.detach(), min=1e-6, max=10.0))
            else:
                return 0.1
                
        except Exception as e:
            print(f"[WARNING] Failed to calculate spectral gap: {e}")
            return 0.1
    
    def detect_phase_transition(self, phase_state):
        """
        检测相变：基于曲率跃迁阈值
        """
        if not hasattr(self, 'last_curvature'):
            self.last_curvature = 0.0
            
        # 获取当前曲率（从phase_state或计算）
        if hasattr(phase_state, 'curvature'):
            current_curvature = phase_state.curvature
        else:
            # 使用trace_A作为曲率代理
            current_curvature = torch.trace(self.A_t.real).item() if hasattr(self, 'A_t') and self.A_t is not None else 0.0
            
        # 检测曲率跃迁（超过阈值的突变）
        curvature_change = abs(current_curvature - self.last_curvature)
        phase_transition_detected = curvature_change > Config.PHASE_TRANSITION_THRESHOLD
        
        # 更新历史
        self.last_curvature = current_curvature
        
        return phase_transition_detected
    
    def update_gravity_constant(self, G_current, trace_A, phase_state):
        """
        基于Klartag-Lehec势阱的引力常数G演化方程
        引入恢复力项和随机引力波项
        """
        # 理论目标值 (归一化)
        G_target = 1.0
        
        # 计算几何刚性系数 (Rigidity), 与协方差矩阵的谱隙正相关
        # 谱隙越大，刚性越强，G越难改变
        spectral_gap = self.calculate_spectral_gap(trace_A)
        rigidity_xi = Config.K_KLS_COEFFICIENT * spectral_gap
        
        # 定义恢复力 (Restoring Force)
        # 当偏离目标值时，产生反向拉力，拉力大小取决于几何刚性
        restoring_force = -rigidity_xi * (G_current - G_target)
        
        # 定义随机引力波项 (Random GW Burst)
        # 仅在特定的相变曲率阈值处触发
        gw_burst = 0.0
        if self.detect_phase_transition(phase_state):
            gw_burst = torch.randn(1).item() * Config.BETA_GW
            print(f"[GW Burst] Phase transition detected, GW burst: {gw_burst:.6f}")
            
        # Langevin 更新
        dt = 0.01  # 时间步长
        dG = restoring_force * dt + gw_burst
        G_new = G_current + dG
        
        # 限制G的物理合理范围
        G_new = max(0.1, min(G_new, 2.0))
        
        return G_new, {
            'spectral_gap': spectral_gap,
            'rigidity_xi': rigidity_xi,
            'restoring_force': restoring_force,
            'gw_burst': gw_burst,
            'dG': dG
        }
    
class DeepSeekCognition:
    """
    DeepSeek AI agent for real-time parameter optimization of spacetime phases.
    Integrates with DeepSeek API to analyze simulation metrics and suggest parameter adjustments.
    """
    def __init__(self, api_key, memory_system=None):
        self.api_key = api_key
        self.base_url = "https://api.deepseek.com"
        self.model = "deepseek-v4-pro"
        # 使用传入的高级记忆系统，如果未传入则设为 None 或处理异常
        self.memory = memory_system

    def _construct_state_description(self, metrics: dict) -> str:
        if not isinstance(metrics, dict):
            metrics = {}
        phase = metrics.get('current_phase', 'unknown')
        fd = metrics.get('fractal_dimension', 0)
        cc = metrics.get('clustering_coefficient', 0)
        aniso = metrics.get('anisotropy', 0)
        trace_A = metrics.get('trace_A', 0)
        return (
            f"Current Phase: {phase}. "
            f"Fractal Dimension is {float(fd):.4f}. "
            f"Clustering Coefficient is {float(cc):.4f}. "
            f"Anisotropy is {float(aniso):.4f}. "
            f"Trace(A) is {float(trace_A):.4f}."
        )

    def _format_memory_context(self, memories: List[Dict]) -> str:
        if not memories:
            return ""
        lines = ["\n[Engram Memory Retrieval - Past Similar Situations]:"]
        for mem in memories[:3]:
            ctx = mem.get("context_summary", "")
            act = mem.get("action", {})
            out = mem.get("outcome", {})
            fd = out.get("fractal_dimension", None)
            cc = out.get("clustering_coefficient", None)
            suffix = ""
            if fd is not None:
                suffix += f" fractal_dimension={float(fd):.4f}"
            if cc is not None:
                suffix += f" clustering_coefficient={float(cc):.4f}"
            lines.append(f"- context: {ctx}")
            lines.append(f"  action: {act}")
            if suffix:
                lines.append(f"  outcome:{suffix}")
        lines.append("Please use these past experiences to avoid previous failures or replicate successes.\n")
        return "\n".join(lines)

    def analyze_and_optimize(self, metrics, current_params, iteration):
        """
        Construct Prompt, call DeepSeek API, parse JSON response for parameter updates.
        """
        print(f"[AI Agent] Submitting metrics to DeepSeek (Iteration {iteration})...")

        state_description = self._construct_state_description(metrics)
        
        # 适配新的记忆系统接口
        if self.memory is not None and hasattr(self.memory, 'retrieve_with_topology'):
            past_experiences = self.memory.retrieve_with_topology(state_description, top_k=3)
        elif self.memory is not None and hasattr(self.memory, 'retrieve_relevant_memories'):
            past_experiences = self.memory.retrieve_relevant_memories(state_description, top_k=3)
        else:
            past_experiences = []

        system_prompt = (
            "You are a Great Theoretical Physicist and Master of Geometric Analysis. "
            "You are overseeing a 10D Brane Cosmology Simulation based on SL(6,C) group dynamics. "
            "Your goal is to optimize the three spacetime phases: Matter, Black Hole, and Dark Energy. "
            "Analyze the topological metrics provided. "
            "If Fractal Dimension is < 1.5, structure is too sparse (Voids dominate). "
            "If Fractal Dimension is > 2.5, structure is too noisy. "
            "Target Fractal Dimension is ~1.8-2.1 for realistic filaments. "
            "Output valid JSON ONLY with updated parameters."
        )

        memory_context_str = self._format_memory_context(past_experiences)
        if memory_context_str:
            system_prompt = system_prompt + "\n" + memory_context_str

        user_message = {
            "iteration": iteration,
            "metrics": metrics,
            "current_physics_params": current_params,
            "visual_feedback": f"The current phase is {unified_phase_manager.get_authoritative_phase()}. "
                              f"Fractal dimension: {metrics.get('fractal_dimension', 0):.2f}, "
                              f"Clustering coefficient: {metrics.get('clustering_coefficient', 0):.2f}"
        }

        # Define function calling schema
        tools = [
            {
                "type": "function",
                "function": {
                    "name": "update_spacetime_parameters",
                    "description": "Update physics simulation parameters for spacetime phase optimization",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "gravity_constant_G": {"type": "number", "description": "Gravity proxy constant"},
                            "dark_energy_w": {"type": "number", "description": "Dark energy equation of state parameter"},
                            "compactification_scale": {"type": "number", "description": "Moduli space compactification scale"},
                            "stochastic_dt": {"type": "number", "description": "Stochastic flow time step"},
                            "phase_transition_threshold": {"type": "number", "description": "Threshold for phase transitions"}
                        },
                        "required": ["gravity_constant_G", "dark_energy_w", "compactification_scale"]
                    }
                }
            }
        ]

        try:
            headers = {
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json"
            }
            payload = {
                "model": self.model,
                "messages": [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": json.dumps(user_message)}
                ],
                "tools": tools,
                "tool_choice": "auto",
                "max_tokens": 512
            }
            
            response = requests.post(f"{self.base_url}/chat/completions", headers=headers, json=payload)
            response.raise_for_status()
            
            data = response.json()
            
            # Parse response safely
            if not isinstance(data, dict):
                print("[AI Agent] Response is not a dict")
                return None
                
            choices = data.get('choices')
            if not choices or not isinstance(choices, list) or len(choices) == 0:
                print("[AI Agent] No choices in response")
                return None
                
            first_choice = choices[0]
            if not isinstance(first_choice, dict):
                print("[AI Agent] First choice is not a dict")
                return None
                
            message = first_choice.get('message')
            if not message or not isinstance(message, dict):
                print("[AI Agent] No message in response")
                return None
                
            tool_calls = message.get('tool_calls')
            if not tool_calls or not isinstance(tool_calls, list) or len(tool_calls) == 0:
                print("[AI Agent] No tool calls in response")
                return None
                
            first_tool_call = tool_calls[0]
            if not isinstance(first_tool_call, dict):
                print("[AI Agent] First tool call is not a dict")
                return None
                
            function_info = first_tool_call.get('function')
            if not function_info or not isinstance(function_info, dict):
                print("[AI Agent] No function info in tool call")
                return None
                
            arguments_str = function_info.get('arguments')
            if not arguments_str or not isinstance(arguments_str, str):
                print("[AI Agent] No arguments string in tool call")
                return None
                
            # Parse arguments
            try:
                args = json.loads(arguments_str)
                print(f"[AI Agent] Optimization received: {args}")
                try:
                    self.memory.store_experience(state_description, args, metrics)
                except Exception as e:
                    print(f"[AI Agent] Memory store failed: {e}")
                return args
            except json.JSONDecodeError as e:
                print(f"[AI Agent] Failed to parse JSON arguments: {e}")
                return None
                
        except requests.exceptions.RequestException as e:
            print(f"[AI Agent] API request failed: {e}")
            return None
        except Exception as e:
            print(f"[AI Agent] Processing failed: {e}")
            return None

