    def update_cosmic_phase_and_partitions(self, dt: float):
        if not hasattr(self, "snapshot") or self.snapshot is None:
            return

        self.snapshot.tau = float(getattr(self, "tau", 0.0))
        self.snapshot.current_sphere_radius = float(getattr(self, "current_sphere_radius", self.snapshot.current_sphere_radius))

        trace_A_val = None
        try:
            if hasattr(self, "flow_solver") and hasattr(self.flow_solver, "A_t") and self.flow_solver.A_t is not None:
                trace_A_val = float(torch.trace(self.flow_solver.A_t.real).item())
        except Exception:
            trace_A_val = None

        if trace_A_val is not None:
            self.snapshot.trace_A = trace_A_val

        # [16_0-V22Dual] V22 影子必须先于判据更新，v22 模式下判据直接读当帧三区间状态
        try:
            _chi = getattr(self.flow_solver, 'chi', None)
            _Hv = float(abs(getattr(self, 'expansion_rate', 0.05)) or 0.05)
            self.snapshot.update_v22_feedback(_chi, float(dt), _Hv)
        except Exception:
            pass

        try:
            self.snapshot.safe_partition_update(self.snapshot.trace_A, float(dt))
        except Exception:
            try:
                self.snapshot.update_phase_state(float(dt))
            except Exception:
                return

        # [CYBERNETIC-P1-1 2026-06-29] Bourgain slicing constraint:
        # When det(space_A) → 0, holographic volume conservation forces
        # det(time_A) → ∞, triggering black-hole decompactification.
        # Reference: Lean V10.1 Domain I — decompactification_trigger theorem
        try:
            if hasattr(self.flow_solver, 'A_t') and self.flow_solver.A_t is not None:
                A = self.flow_solver.A_t
                # Partition A_t into space (first 6 dims) and time (next 3 dims)
                # Simplification: use leading diagonal blocks
                n = A.shape[0]
                n_space = min(6, n)
                n_time = min(3, n - n_space)
                if n_space > 0 and n_time > 0:
                    space_block = A[:n_space, :n_space]
                    time_block = A[n_space:n_space + n_time, n_space:n_space + n_time]
                    det_space = float(torch.det(space_block.real).abs().item())
                    det_time = float(torch.det(time_block.real).abs().item())

                    # Store for CSV/debugging
                    self._bourgain_det_space = det_space
                    self._bourgain_det_time = det_time

                    # Bourgain trigger: spatial collapse → temporal decompactification
                    if det_space < 1e-6 and det_time < 1e6:
                        # Force time dilation: det(time) ≥ C^n / det(space)
                        total_det_lower = (self.flow_solver.theta_stable ** n_space)
                        target_time_det = total_det_lower / max(det_space, 1e-12)
                        # Apply via sphere radius inflation
                        inflation_factor = (target_time_det / max(det_time, 1e-6)) ** (1.0 / 3.0)
                        inflation_factor = min(inflation_factor, 100.0)  # Cap inflation
                        self.snapshot.current_sphere_radius *= inflation_factor
                        self.current_sphere_radius = self.snapshot.current_sphere_radius
                        if getattr(self, 'current_step', 0) % 1000 == 0:
                            print(f"[BOURGAIN] Step {self.current_step}: det(space)={det_space:.2e} → "
                                  f"sphere_radius ×{inflation_factor:.1f} → {self.current_sphere_radius:.1f}")
        except Exception as e:
            if getattr(self, 'current_step', 0) % 1000 == 0:
                print(f"[BOURGAIN] Constraint check failed (non-critical): {e}")

        try:
            unified_phase_manager.set_authoritative_phase(self.snapshot.current_phase.value, source="snapshot")
        except Exception:
            try:
                unified_phase_manager.set_authoritative_phase(str(self.snapshot.current_phase), source="snapshot")
            except Exception:
                pass

        self.current_phase = unified_phase_manager.get_authoritative_phase()

        try:
            self.phase_partitions = tuple(self.snapshot.phase_partitions)
        except Exception:
            pass

        try:
            if hasattr(self, "flow_solver") and self.flow_solver is not None:
                self.flow_solver.current_phase = self.current_phase
        except Exception:
            pass

        if self._deferred_phase_components_initialized:
            return

        self._deferred_phase_components_initialized = True
        
        # MD建议20260207：添加MCTS代理树搜索功能
