    def get_hubble_parameter(self):
        """
        获取当前哈勃参数H
        基于宇宙膨胀率和密度参数的简化计算
        """
        # 简化的哈勃参数计算
        # H = H0 * sqrt(Ω_m * a^-3 + Ω_Λ * a^(-3*(1+w)))
        H0 = 70.0  # km/s/Mpc，简化为70
        a = self._expansion_a_multiplier  # 尺度因子
        
        # 简化的密度参数
        omega_m = 0.3  # 物质密度参数
        omega_lambda = 0.7  # 暗能量密度参数
        w = self.w_dark_energy  # 暗能量状态方程
        
        # 计算哈勃参数
        H = H0 * math.sqrt(omega_m * a**(-3) + omega_lambda * a**(-3*(1+w)))
        
        return H * 3.24e-20  # 转换为1/s单位

