    # ------------------------------------------------------------------
    # [15_2 CYBERNETIC-FIX] 断点续跑三件套
    #   原 save_state 已实现但主循环从未调用 → 35150 步中断后无法续跑，只能重跑。
    #   现在：save_state 落盘到 checkpoints/ 并只保留最近 3 个；新增
    #   find_latest_checkpoint / load_state，配合主循环 SPSGAN_NO_RESUME 环境变量恢复。
    # ------------------------------------------------------------------
    @staticmethod
    def _ckpt_dir():
        # [16_0-V22Dual] 双轨并行时必须隔离 checkpoint，否则两轨的 save_state
        # 会互相覆盖，且"只保留最近 3 个"的逻辑会删掉另一轨的存档
        _d = os.environ.get('SPSGAN_CKPT_DIR', '').strip()
        d = _d if _d else os.path.join(os.getcwd(), "checkpoints")
        os.makedirs(d, exist_ok=True)
        return d

    @staticmethod
    def _ckpt_num(path):
        base = os.path.basename(path)
        digits = ''.join(ch for ch in base if ch.isdigit())
        return int(digits) if digits else -1

    @staticmethod
    def _as_numpy(x):
        if torch.is_tensor(x):
            return x.detach().cpu().numpy()
        try:
            return np.asarray(x)
        except Exception:
            return x

    def save_state(self, step: int):
        """保存状态到 checkpoints/（[15_2] 保留最近 3 个）"""
        try:
            ckpt_dir = self._ckpt_dir()
            checkpoint_data = {
                'step': step,
                'pos': self._as_numpy(self.pos),
                'vel': self._as_numpy(self.vel),
                'phase_labels': self._as_numpy(self.phase_labels),
                'metrics_history': {k: list(v)[-500:] for k, v in getattr(self, 'metrics_history', {}).items()},
                'current_step': step,
                'simulation_time': time.time(),
                'config_snapshot': {k: getattr(Config, k) for k in (
                    'G_TC_IR', 'BETA_FUNC_B0', 'LAMBDA_KLS', 'LAMBDA_KLS_EFF',
                    'THETA_STABLE', 'THETA_CRIT', 'TAU_C') if hasattr(Config, k)},
                # [V23Dual] V22/V23 判据槽位序列化（根治 resume 丢判据：50K 续跑数据作废的根因）
                'v22_state': self._v23_collect_state(),
            }
            ckpt_file = os.path.join(ckpt_dir, f"checkpoint_{step}.pt")
            torch.save(checkpoint_data, ckpt_file)
            # 只保留最近 3 个，避免磁盘无界增长
            import glob as _glob
            all_ck = sorted(_glob.glob(os.path.join(ckpt_dir, "checkpoint_*.pt")), key=self._ckpt_num)
            for old_file in all_ck[:-3]:
                try:
                    os.remove(old_file)
                except OSError:
                    pass
            if self.orchestrator:
                try:
                    self.orchestrator._save_world_state(os.path.join(ckpt_dir, f"world_state_{step}.json"))
                except Exception:
                    pass
            print(f"[CHECKPOINT] State saved at step {step} -> {ckpt_file}")
        except Exception as e:
            print(f"[CHECKPOINT] Save failed: {e}")

    def find_latest_checkpoint(self):
        """返回最新的 checkpoint 路径，没有则 None"""
        import glob as _glob
        cks = _glob.glob(os.path.join(self._ckpt_dir(), "checkpoint_*.pt"))
        if not cks:
            return None
        return max(cks, key=self._ckpt_num)

    def load_state(self, ckpt_path):
        """从 checkpoint 恢复粒子与指标历史，返回恢复到的 step"""
        ck = torch.load(ckpt_path, map_location=Config.DEVICE, weights_only=False)
        pos = torch.as_tensor(ck['pos'], device=self.pos.device, dtype=self.pos.dtype)
        vel = torch.as_tensor(ck['vel'], device=self.vel.device, dtype=self.vel.dtype)
        if tuple(pos.shape) == tuple(self.pos.shape):
            with torch.no_grad():
                self.pos.copy_(pos)
                self.vel.copy_(vel)
        else:
            print(f"[RESUME][WARN] 粒子数不一致 pos {tuple(pos.shape)} vs {tuple(self.pos.shape)}，跳过粒子恢复")
        pl = ck.get('phase_labels')
        if pl is not None:
            try:
                with torch.no_grad():
                    self.phase_labels.copy_(torch.as_tensor(pl, device=self.phase_labels.device))
            except Exception as _ple:
                print(f"[RESUME][WARN] phase_labels 恢复失败: {_ple}")
        for k, vals in (ck.get('metrics_history') or {}).items():
            if k in getattr(self, 'metrics_history', {}):
                self.metrics_history[k] = list(vals)
        # [V23Dual] 恢复 V22/V23 判据槽位（缺失 = 旧档，按初始化逻辑重建并显式告警）
        vs = ck.get('v22_state')
        if isinstance(vs, dict) and vs:
            for k, v in vs.items():
                try:
                    setattr(self, k, v)
                except Exception as _se:
                    print(f"[RESUME][V22][WARN] 槽位 {k} 恢复失败: {_se}")
            print(f"[RESUME][V22] 判据槽位已恢复: judge={vs.get('judge_mode')} m={vs.get('m_ratio')} "
                  f"x={vs.get('v22_x'):.6g} regime={vs.get('v22_regime')} N={vs.get('_v22_N'):.6g}")
        else:
            print("[RESUME][V22][WARN] checkpoint 无 V22 判据状态（旧档）。若 SPSGAN_PHASE_JUDGE=v22，"
                  "影子层将按初始化逻辑重建（x 回到 1.0 起点），与停止前轨迹不连续——请改用 V23Dual 产出的新档。")
        step = int(ck.get('step', 0))
        print(f"[RESUME] 已恢复 checkpoint step={step}（pos/vel/phase_labels/metrics_history/V22 槽位）")
        return step

    def _v23_collect_state(self):
        """[V23Dual] 收集 V22/V23 影子层与判据槽位（getattr 驱动，缺省安全）"""
        keys = ['cov_scalar', 'cov_excess', 'vac_response', 'dust_mass', 'rho_v',
                'accel_diag', 'v22_x', 'v22_regime', 'constraint_residual', 'hubble_v22',
                'x_plus', 'x_minus', 'v22_n_efolds', 'lambda_cc', 'v23_regime_threshold',
                'v23_n_star', 'v23_f_peak', 'residual_rh', 'residual_re',
                'response_err_bound', 'm_minus_4ellnu', 'twolnu_minus_3',
                't_cos_v22', 'tau_v22', 'rho_tot_v23']
        st = {'judge_mode': str(getattr(self, 'judge_mode', V22_PHASE_JUDGE)),
              'm_ratio': float(getattr(Config, 'V22_M_RATIO', 6.0)),
              'm0_dust': float(getattr(Config, 'V22_M0_DUST', 0.0))}
        for k in keys:
            st[k] = float(getattr(self, k)) if not isinstance(getattr(self, k, None), str)                 else str(getattr(self, k))
        for k in ['_v22_N', '_v22_E0', '_v22_R0', '_v22_init', '_v23_t_cos', '_v23_rho_max']:
            st[k] = getattr(self, k, False if k == '_v22_init' else 0.0)
        return st

    def get_hubble_parameter(self) -> float:
        """获取哈勃参数"""
        try:
            vel_mag = torch.norm(self.vel, dim=1)
            return float(torch.mean(vel_mag).item())
        except Exception:
            return 0.0

    def get_scale_factor(self, t: float) -> float:
        """Cosmology scale factor a(t) proxy.

        Minimal, stable implementation:
        use the ratio of current sphere radius to base radius as a(t).
        """
        base_radius = getattr(self, 'base_sphere_radius', None)
        if base_radius is None:
            base_radius = getattr(self, '_initial_sphere_radius', 1.0)
        base = float(base_radius) if float(base_radius) != 0.0 else 1.0
        a_t = (float(self.current_sphere_radius) / base) * float(self._expansion_a_multiplier)
        a_t = max(a_t, self._a_min)
        return min(a_t, self._a_max)

    def yoshida_step(
        self,
        pos: torch.Tensor,
        vel: torch.Tensor,
        force_func: Callable[[torch.Tensor], torch.Tensor],
        dt: float,
        t: float,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        """4th-order Yoshida symplectic integration step.

        Recomputes force before each Kick via `force_func(pos)` (MD suggestion).
        The comoving correction is applied in drift: dx/dt = v / a(t)^2.
        """
        w0 = -1.7024143839193153
        w1 = 1.3512071919596578
        c = [w1 / 2.0, (w0 + w1) / 2.0, (w0 + w1) / 2.0, w1 / 2.0]
        d = [w1, w0, w1]

        a_t = self.get_scale_factor(t)
        inv_a2 = 1.0 / (a_t * a_t)

        # Drift 1
        pos = pos + vel * (c[0] * dt * inv_a2)
        # Kick 1
        force = force_func(pos)
        vel = vel + force * (d[0] * dt)

        # Drift 2
        pos = pos + vel * (c[1] * dt * inv_a2)
        # Kick 2
        force = force_func(pos)
        vel = vel + force * (d[1] * dt)

        # Drift 3
        pos = pos + vel * (c[2] * dt * inv_a2)
        # Kick 3
        force = force_func(pos)
        vel = vel + force * (d[2] * dt)

        # Drift 4
        pos = pos + vel * (c[3] * dt * inv_a2)

        return pos, vel

