    def save_spectrum_to_csv(self, iteration: int):
        with torch.no_grad():
            spectrum = getattr(self.flow_solver, 'last_spectrum', None)
            if spectrum is None:
                spectrum = torch.linalg.eigvalsh(self.flow_solver.A_t.real)
            spectrum = torch.clamp(spectrum.real, min=1e-30)
            log_spec = torch.log(spectrum).detach().cpu().numpy().tolist()

        # 安全地初始化IO属性
        if not hasattr(self, '_io_lock'):
            self._io_lock = threading.Lock()
        if not hasattr(self, '_io_executor'):
            self._io_executor = ThreadPoolExecutor(max_workers=2)
        if not hasattr(self, '_pending_io'):
            self._pending_io = []
        
        row = [iteration] + log_spec
        def _write():
            with self._io_lock:
                with open(self.spectrum_csv_filename, 'a', newline='') as csvfile:
                    writer = csv.writer(csvfile)
                    writer.writerow(row)

        self._pending_io.append(self._io_executor.submit(_write))

