    def save_chi_to_csv(self, iteration: int):
        with torch.no_grad():
            chi = getattr(self.flow_solver, 'chi', None)
            if chi is None:
                return
            chi_real = chi.detach().real.cpu().numpy().tolist()
            chi_imag = chi.detach().imag.cpu().numpy().tolist()
            R_loc = getattr(self.flow_solver, 'last_R_loc', None)
            if R_loc is None:
                R_loc = 0.0
            else:
                R_loc = float(R_loc)
            phase = getattr(self.flow_solver, 'current_phase', None)
            if phase is None:
                phase = self.current_phase

        # 安全地初始化IO属性
        if not hasattr(self, '_io_lock'):
            self._io_lock = threading.Lock()
        if not hasattr(self, '_io_executor'):
            self._io_executor = ThreadPoolExecutor(max_workers=2)
        if not hasattr(self, '_pending_io'):
            self._pending_io = []

        row = [iteration, R_loc, phase] + chi_real + chi_imag
        def _write():
            with self._io_lock:
                with open(self.chi_csv_filename, 'a', newline='') as csvfile:
                    writer = csv.writer(csvfile)
                    writer.writerow(row)

        self._pending_io.append(self._io_executor.submit(_write))

    def flush_io(self):
        """Flush pending IO operations with improved timeout handling"""
        # 安全地初始化IO属性
        if not hasattr(self, '_pending_io'):
            self._pending_io = []
            return
        
        pending = self._pending_io
        self._pending_io = []
        
        if not pending:
            return
            
        print(f"[DEBUG] Flushing {len(pending)} pending I/O operations...")
        
        for i, fut in enumerate(pending):
            try:
                # 减少超时时间，更快失败
                fut.result(timeout=5)
                if i % 10 == 0:
                    print(f"[DEBUG] I/O progress: {i}/{len(pending)} completed")
            except TimeoutError:
                print(f"[WARNING] I/O operation {i} timed out, skipping...")
                # 取消任务
                fut.cancel()
            except Exception as e:
                print(f"[WARNING] I/O operation {i} failed: {e}")
                # 取消任务
                fut.cancel()
        
        # 强制关闭线程池以防止资源泄漏
        try:
            self._io_executor.shutdown(wait=False)
            # 重新创建线程池
            self._io_executor = ThreadPoolExecutor(max_workers=2)
            print("[DEBUG] Thread pool recycled")
        except Exception as e:
            print(f"[WARNING] Failed to recycle thread pool: {e}")
            # 如果失败，创建新的线程池
            try:
                self._io_executor = ThreadPoolExecutor(max_workers=2)
            except Exception:
                print("[ERROR] Failed to create new thread pool, disabling async I/O")
                self._io_executor = None
        
    def spherical_to_cartesian(self, r, theta, phi):
        """球坐标转换为笛卡尔坐标"""
        x = r * np.sin(theta) * np.cos(phi)
        y = r * np.sin(theta) * np.sin(phi)
        z = r * np.cos(theta)
        return x, y, z
        
