    def apply_parameter_optimizations(self, optimized_params):
        """
        应用参数优化到模拟器
        """
        if not optimized_params:
            return
        
        print(f"[OPTIMIZATION] Applying parameter optimizations...")
        
        # 应用引力常数优化
        if 'gravity_constant_G' in optimized_params:
            old_G = self.G_proxy
            new_G = optimized_params['gravity_constant_G']
            self.G_proxy = new_G
            self.gravity_manager.alpha_sl6c = new_G
            print(f"[OPTIMIZATION] Gravity constant: {old_G:.6f} -> {new_G:.6f}")
        
        # 应用暗能量状态方程优化
        if 'dark_energy_w' in optimized_params:
            old_w = self.w_dark_energy
            new_w = optimized_params['dark_energy_w']
            self.w_dark_energy = new_w
            print(f"[OPTIMIZATION] Dark energy w: {old_w:.6f} -> {new_w:.6f}")
        
        # 应用膨胀率优化
        if 'expansion_rate' in optimized_params:
            old_rate = getattr(self, 'expansion_rate', 1.0)
            new_rate = optimized_params['expansion_rate']
            self.expansion_rate = new_rate
            print(f"[OPTIMIZATION] Expansion rate: {old_rate:.6f} -> {new_rate:.6f}")
        
        # 应用模空间协方差优化
        if 'trace_A' in optimized_params:
            # 这里需要通过flow_solver来调整
            try:
                old_trace = torch.trace(self.flow_solver.A_t).real.item()
                # 通过调整A_t的缩放来实现
                scale_factor = optimized_params['trace_A'] / old_trace if old_trace != 0 else 1.0
                self.flow_solver.A_t = self.flow_solver.A_t * scale_factor
                new_trace = torch.trace(self.flow_solver.A_t).real.item()
                print(f"[OPTIMIZATION] Trace A: {old_trace:.6f} -> {new_trace:.6f}")
            except Exception as e:
                print(f"[WARNING] Failed to optimize trace A: {e}")
        
        print(f"[OPTIMIZATION] Parameter optimization completed")
    
