    def optimize_with_memory(self, current_params: dict, metrics: dict, metric_data: np.ndarray = None) -> dict:
        """
        基于记忆进行参数优化
        """
        if not INTELLIGENT_MEMORY_AVAILABLE:
            return current_params
        
        try:
            # 构建当前状态描述
            current_context = f"Current Phase: {unified_phase_manager.get_authoritative_phase()}. "
            current_context += f"Fractal Dimension is {metrics.get('fractal_dimension', 0):.2f}. "
            current_context += f"Clustering Coefficient is {metrics.get('clustering_coefficient', 0):.2f}. "
            current_context += f"Universe is {'expanding' if metrics.get('expansion_rate', 1) > 1 else 'contracting'}."
            
            # 检索相关经验
            relevant_experiences = self.retrieve_relevant_experiences(current_context, metric_data, top_k=3)
            
            if not relevant_experiences:
                print("[MEMORY] No relevant experiences found, using default parameters")
                return current_params
            
            # 分析历史经验并调整参数
            optimized_params = current_params.copy()
            
            # 统计成功经验
            successful_experiences = [exp for exp in relevant_experiences 
                                if exp.get('outcome', {}).get('fractal_dimension', 0) > 1.0]
            
            if successful_experiences:
                # 使用成功经验的平均参数
                avg_G = np.mean([exp['action'].get('gravity_constant_G', current_params['gravity_constant_G']) 
                               for exp in successful_experiences])
                avg_w = np.mean([exp['action'].get('dark_energy_w', current_params['dark_energy_w']) 
                               for exp in successful_experiences])
                
                optimized_params['gravity_constant_G'] = avg_G
                optimized_params['dark_energy_w'] = avg_w
                
                print(f"[MEMORY] Optimized based on {len(successful_experiences)} successful experiences")
                print(f"[MEMORY] G: {current_params['gravity_constant_G']:.6f} -> {avg_G:.6f}")
                print(f"[MEMORY] w: {current_params['dark_energy_w']:.6f} -> {avg_w:.6f}")
            
            return optimized_params
            
        except Exception as e:
            print(f"[ERROR] Memory-based optimization failed: {e}")
            return current_params
    
