    def _mock_evaluation(self, metrics: dict, params: dict) -> dict:
        """
        模拟评估结果
        """
        score = 75.0
        
        # 基于简单规则调整分数
        if metrics.get('script_failed', False):
            score = 10.0
        elif metrics.get('loss', 999.9) < 1.0:
            score = 90.0
        elif metrics.get('einstein_residual', 999.9) < 1.0:
            score = 85.0
        
        return {
            "score": score,
            "reasoning": f"Mock evaluation for params: {params}",
            "suggestions": ["Continue optimization", "Check numerical stability"]
        }
    
