    def run_hybrid_optimization(self, cycle, mcts_budget=10):
        """
        运行混合优化：结合MCTS、记忆和数据分析
        """
        print(f"\n{'='*60}")
        print(f"Starting Hybrid Optimization for Cycle {cycle}")
        print(f"{'='*60}")
        
        # 1. 获取当前状态
        current_params = self.get_current_parameters()
        current_metrics = self.compute_topological_metrics()
        
        # 2. 基于记忆优化
        memory_optimized = self.optimize_with_memory(current_params, current_metrics)
        
        # 3. 运行MCTS优化
        mcts_optimized = self.run_mcts_optimization(mcts_budget)
        
        # 4. 融合优化结果
        final_params = current_params.copy()
        
        # 优先级：MCTS > 记忆优化 > 原始参数
        if mcts_optimized:
            final_params.update(mcts_optimized)
            print(f"[HYBRID] Applied MCTS optimizations")
        
        if memory_optimized != current_params:
            # 对于MCTS没有覆盖的参数，使用记忆优化
            for key, value in memory_optimized.items():
                if key not in mcts_optimized:
                    final_params[key] = value
            print(f"[HYBRID] Applied memory optimizations for remaining parameters")
        
        # 5. 应用最终优化参数
        self.integrate_mcts_optimization(cycle, final_params)
        
        # 6. 存储混合优化经验
        if INTELLIGENT_MEMORY_AVAILABLE:
            context_text = f"Hybrid optimization cycle {cycle} completed"
            outcome_metrics = {
                'mcts_budget': mcts_budget,
                'memory_used': INTELLIGENT_MEMORY_AVAILABLE,
                'final_params': final_params
            }
            self.store_simulation_experience(context_text, final_params, outcome_metrics)
        
        print(f"[HYBRID] Hybrid optimization completed for cycle {cycle}")
        return final_params
    
