# --- GPU-Accelerated Topology Analysis ---
class GPUTopologyAnalyzer:
    """
    GPU-accelerated topology analysis to replace CPU-bound GUDHI operations
    """
    def __init__(self, device=None):
        self.device = device or Config.DEVICE
        self.max_points = 1000  # 限制点数避免内存溢出
        
    def analyze_topology_gpu(self, positions):
        """
        GPU-accelerated topology analysis using PyTorch operations
        """
        try:
            if isinstance(positions, np.ndarray):
                positions = torch.from_numpy(positions).float().to(self.device)
            
            n_points = min(positions.shape[0], self.max_points)
            if n_points < 3:
                return {"betti_numbers": [1, 0, 0], "persistence_entropy": 0.0}
            
            # 采样以控制内存使用
            if positions.shape[0] > n_points:
                indices = torch.randperm(positions.shape[0])[:n_points]
                positions = positions[indices]
            
            # GPU计算距离矩阵 (chunked for >8192)
            dist_matrix = _safe_pairwise_dists(positions)
            
            # 动态阈值（基于距离分布）
            sorted_distances, _ = torch.sort(dist_matrix.view(-1))
            threshold_idx = int(len(sorted_distances) * 0.1)  # 10%分位数
            max_edge_length = sorted_distances[threshold_idx].item()
            
            # GPU计算连通分量 (Betti_0)
            adjacency = (dist_matrix < max_edge_length).float()
            betti_0 = self._count_connected_components_gpu(adjacency)
            
            # GPU计算环的近似 (Betti_1)
            betti_1 = self._estimate_loops_gpu(adjacency, positions)
            
            # GPU计算空洞的近似 (Betti_2)
            betti_2 = self._estimate_voids_gpu(positions, dist_matrix)
            
            # 计算持久化熵（简化版）
            persistence_entropy = self._compute_persistence_entropy_gpu(dist_matrix, max_edge_length)
            
            return {
                "betti_numbers": [betti_0, betti_1, betti_2],
                "persistence_entropy": persistence_entropy,
                "topological_features": {
                    "num_points": n_points,
                    "max_edge_length": max_edge_length,
                    "gpu_accelerated": True
                }
            }
            
        except Exception as e:
            print(f"[WARNING] GPU topology analysis failed: {e}")
            return {"betti_numbers": [1, 0, 0], "persistence_entropy": 0.0}
    
    def _count_connected_components_gpu(self, adjacency):
        """GPU计算连通分量数量"""
        n = adjacency.shape[0]
        visited = torch.zeros(n, dtype=torch.bool, device=self.device)
        components = 0
        
        for i in range(n):
            if not visited[i]:
                # BFS/DFS on GPU
                stack = [i]
                visited[i] = True
                components += 1
                
                while stack:
                    current = stack.pop()
                    neighbors = torch.where(adjacency[current] > 0)[0]
                    
                    for neighbor in neighbors:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
        
        return components
    
    def _estimate_loops_gpu(self, adjacency, positions):
        """GPU估计环的数量"""
        # 简化：使用三角形数量作为环的代理
        n = adjacency.shape[0]
        triangles = 0
        
        # 采样检查三角形
        sample_size = min(100, n)
        indices = torch.randperm(n)[:sample_size]
        
        for i in range(sample_size):
            for j in range(i+1, sample_size):
                for k in range(j+1, sample_size):
                    idx_i, idx_j, idx_k = indices[i], indices[j], indices[k]
                    if (adjacency[idx_i, idx_j] > 0 and 
                        adjacency[idx_j, idx_k] > 0 and 
                        adjacency[idx_k, idx_i] > 0):
                        triangles += 1
        
        return min(triangles // 10, 50)  # 限制范围
    
    def _estimate_voids_gpu(self, positions, dist_matrix):
        """GPU估计空洞数量"""
        # 简化：基于凸包性质
        n = positions.shape[0]
        if n < 4:
            return 0
        
        # 计算质心
        centroid = positions.mean(dim=0)
        
        # 计算到质心的距离
        distances_to_centroid = torch.norm(positions - centroid, dim=1)
        
        # 估计空洞：基于距离分布的偏度
        mean_dist = distances_to_centroid.mean()
        std_dist = distances_to_centroid.std()
        
        # 简化的空洞估计
        skewness = ((distances_to_centroid - mean_dist) ** 3).mean() / (std_dist ** 3 + 1e-8)
        
        # 基于偏度估计空洞数量
        voids = max(0, int(skewness * 10))
        return min(voids, 10)  # 限制范围
    
    def _compute_persistence_entropy_gpu(self, dist_matrix, max_edge_length):
        """GPU计算持久化熵"""
        # 只考虑小于阈值的边
        valid_edges = dist_matrix[dist_matrix < max_edge_length]
        
        if valid_edges.numel() == 0:
            return 0.0
        
        # 计算边长分布
        edge_lengths = valid_edges.view(-1)
        
        # 归一化
        edge_lengths = edge_lengths / (edge_lengths.sum() + 1e-8)
        
        # 计算熵
        entropy = -torch.sum(edge_lengths * torch.log(edge_lengths + 1e-8))
        
        return entropy.item()

# --- Memory Management for Topology Analysis ---
class TopologyMemoryManager:
    """
    拓扑分析内存管理器

    [15_2 CYBERNETIC-FIX] 两个根因修复：
    1. check_memory_usage 原用 memory_allocated()/total，多卡+碎片场景实测返回 285%
       （>1），导致清理逻辑每轮都触发。改为 reserved 指标 + clamp 到 [0,1]。
    2. gc.collect() 每 50 步一次，在 19k 行对象图上单次可达数秒且随步数恶化。
       改为：empty_cache 按需，full gc 每 5 次清理才做一次（且只在 reserved 真高时）。
    """
    def __init__(self, device=None):
        self.device = device or Config.DEVICE
        self.memory_threshold = 0.85   # 85% 阈值（基于 reserved）
        self.cleanup_interval = 100    # 每 100 步检查一次（原 50 → 减半触发频次）
        self.step_counter = 0
        self.cleanup_count = 0
        self.last_allocated_ratio = 0.0
        self.last_reserved_ratio = 0.0

    def check_memory_usage(self):
        """检查 GPU 内存使用比例（返回 0.0-1.0；当前设备）"""
        if not torch.cuda.is_available():
            return 0.0
        try:
            dev = torch.cuda.current_device()
            total = float(torch.cuda.get_device_properties(dev).total_memory)
            if total <= 0:
                return 0.0
            allocated = float(torch.cuda.memory_allocated(dev))
            reserved = float(torch.cuda.memory_reserved(dev))
            self.last_allocated_ratio = min(allocated / total, 1.0)
            self.last_reserved_ratio = min(reserved / total, 1.0)
            # 以 reserved（含缓存块）为压力指标：allocated 高但 reserved 不高时无需清理
            return self.last_reserved_ratio
        except Exception:
            return 0.0

    def auto_cleanup_if_needed(self):
        """按需清理 GPU 缓存（不做无条件 gc.collect）"""
        if not torch.cuda.is_available():
            return False
        usage_ratio = self.check_memory_usage()
        if usage_ratio <= self.memory_threshold:
            return False

        torch.cuda.empty_cache()
        # 完整 gc 代价高：每 5 次清理才做一次，且仅在活跃张量也偏高时
        if self.cleanup_count % 5 == 0 and self.last_allocated_ratio > 0.60:
            import gc
            gc.collect()
        self.cleanup_count += 1
        new_usage = self.check_memory_usage()
        print(f"[MEMORY] cleanup #{self.cleanup_count}: reserved {usage_ratio:.1%} -> {new_usage:.1%}"
              f" (allocated {self.last_allocated_ratio:.1%})")
        return True

    def periodic_cleanup(self):
        """定期清理"""
        self.step_counter += 1
        if self.step_counter % self.cleanup_interval == 0:
            self.auto_cleanup_if_needed()

    def stats(self):
        """供 checkpoint / 日志读取的内存状态"""
        return {
            "step_counter": self.step_counter,
            "cleanup_count": self.cleanup_count,
            "allocated_ratio": round(self.last_allocated_ratio, 4),
            "reserved_ratio": round(self.last_reserved_ratio, 4),
        }

# 全局GPU拓扑分析器实例
GPU_TOPOLOGY_ANALYZER = None

def get_gpu_topology_analyzer():
    """获取或创建GPU拓扑分析器"""
    global GPU_TOPOLOGY_ANALYZER
    if GPU_TOPOLOGY_ANALYZER is None:
        GPU_TOPOLOGY_ANALYZER = GPUTopologyAnalyzer()
    return GPU_TOPOLOGY_ANALYZER

# 全局内存管理器
MEMORY_MANAGER = TopologyMemoryManager()

def get_memory_manager():
    """获取内存管理器"""
    return MEMORY_MANAGER

# --- Advanced GPU Computing & Storage Optimization ---
# Based on Dask, Polars, and PyTorch Lightning best practices

import gc
from typing import Dict, List, Tuple, Optional, Any
import threading
from concurrent.futures import ThreadPoolExecutor
import time

class AdvancedGPUOptimizer:
    """
    Advanced GPU optimization combining Dask-style parallelization,
    Polars-like lazy evaluation, and Lightning-style memory management
    """
    def __init__(self, device=None):
        self.device = device or Config.DEVICE
        self.memory_pool = {}  # GPU内存池
        self.computation_cache = {}  # 计算结果缓存
        self.lazy_operations = []  # 延迟操作队列
        self.batch_size = OPTIMAL_BATCH_SIZE
        self.chunk_size = 1000  # 分块大小
        self.memory_threshold = 0.8  # 80%内存阈值
        
        # 性能监控
        self.performance_stats = {
            'memory_usage': [],
            'computation_times': [],
            'cache_hits': 0,
            'cache_misses': 0
        }
        
        print(f"[GPU_OPT] Advanced GPU optimizer initialized on {self.device}")
        print(f"[GPU_OPT] Memory threshold: {self.memory_threshold:.1%}")
        print(f"[GPU_OPT] Chunk size: {self.chunk_size}")
    
    def lazy_tensor_operation(self, operation_func, *args, **kwargs):
        """
        延迟张量操作，类似Polars的lazy evaluation
        """
        operation = {
            'func': operation_func,
            'args': args,
            'kwargs': kwargs,
            'result': None,
            'computed': False,
            'timestamp': time.time()
        }
        self.lazy_operations.append(operation)
        return operation
    
    def compute_lazy_operations(self, force=False):
        """
        执行延迟操作，类似Dask的compute()
        """
        if not self.lazy_operations:
            return
        
        # 检查内存使用情况
        if not force and self.check_memory_pressure():
            print("[GPU_OPT] Memory pressure detected, deferring operations")
            return
        
        print(f"[GPU_OPT] Computing {len(self.lazy_operations)} lazy operations") if len(self.lazy_operations) > 0 else None
        
        for operation in self.lazy_operations:
            if not operation['computed']:
                try:
                    start_time = time.time()
                    result = operation['func'](*operation['args'], **operation['kwargs'])
                    operation['result'] = result
                    operation['computed'] = True
                    operation['compute_time'] = time.time() - start_time
                    
                    self.performance_stats['computation_times'].append(operation['compute_time'])
                    
                except Exception as e:
                    print(f"[GPU_OPT] Operation failed: {e}")
                    operation['result'] = None
                    operation['computed'] = False
        
        # 清理已计算的操作
        self.lazy_operations = [op for op in self.lazy_operations if not op['computed']]
    
    def get_from_memory_pool(self, shape, dtype=torch.float32):
        """
        从内存池获取张量，避免重复分配
        """
        key = (shape, dtype)
        if key in self.memory_pool:
            tensor = self.memory_pool[key]
            if tensor.shape == shape and tensor.dtype == dtype:
                self.performance_stats['cache_hits'] += 1
                return tensor.zero_()
            else:
                del self.memory_pool[key]
        
        # 分配新张量
        tensor = torch.zeros(shape, dtype=dtype, device=self.device)
        self.memory_pool[key] = tensor
        self.performance_stats['cache_misses'] += 1
        return tensor
    
    def chunked_computation(self, data, computation_func, chunk_size=None):
        """
        分块计算，类似Dask的chunked processing
        """
        if chunk_size is None:
            chunk_size = self.chunk_size
        
        if data.shape[0] <= chunk_size:
            return computation_func(data)
        
        results = []
        for i in range(0, data.shape[0], chunk_size):
            chunk = data[i:i+chunk_size]
            result = computation_func(chunk)
            results.append(result)
            
            # 内存管理
            if self.check_memory_pressure():
                self.cleanup_memory()
        
        # 合并结果
        if isinstance(results[0], torch.Tensor):
            return torch.cat(results, dim=0)
        else:
            return results
    
    def check_memory_pressure(self):
        """
        检查内存压力
        """
        if not torch.cuda.is_available():
            return False
        
        allocated = torch.cuda.memory_allocated()
        total = torch.cuda.get_device_properties(0).total_memory
        usage_ratio = allocated / total
        
        self.performance_stats['memory_usage'].append(usage_ratio)
        
        return usage_ratio > self.memory_threshold
    
    def cleanup_memory(self, aggressive=False):
        """
        智能内存清理
        """
        print(f"[GPU_OPT] Cleaning memory (aggressive={aggressive})")
        
        # 清理延迟操作结果
        for operation in self.lazy_operations:
            if operation['computed'] and operation['result'] is not None:
                if isinstance(operation['result'], torch.Tensor):
                    del operation['result']
                operation['result'] = None
        
        # 清理内存池中的旧张量
        current_time = time.time()
        keys_to_remove = []
        for key, tensor in self.memory_pool.items():
            # 移除超过5分钟未使用的张量
            if hasattr(tensor, '_last_used'):
                if current_time - tensor._last_used > 300:
                    keys_to_remove.append(key)
            else:
                tensor._last_used = current_time
        
        for key in keys_to_remove:
            del self.memory_pool[key]
        
        # GPU缓存清理 — 清理所有GPU设备
        if torch.cuda.is_available():
            for gpu_id in range(torch.cuda.device_count()):
                with torch.cuda.device(gpu_id):
                    torch.cuda.empty_cache()
            if aggressive:
                # 同步所有GPU流以确保清理完全
                torch.cuda.synchronize()
                for gpu_id in range(torch.cuda.device_count()):
                    with torch.cuda.device(gpu_id):
                        torch.cuda.empty_cache()
                        torch.cuda.reset_peak_memory_stats(gpu_id)
        
        # Python垃圾回收
        gc.collect()
        
        if aggressive:
            # 强制更激进的清理
            torch.cuda.synchronize()
            torch.cuda.empty_cache()
            gc.collect()
    
    def get_performance_stats(self):
        """
        获取性能统计
        """
        stats = self.performance_stats.copy()
        
        if stats['memory_usage']:
            stats['avg_memory_usage'] = sum(stats['memory_usage']) / len(stats['memory_usage'])
            stats['max_memory_usage'] = max(stats['memory_usage'])
        
        if stats['computation_times']:
            stats['avg_computation_time'] = sum(stats['computation_times']) / len(stats['computation_times'])
            stats['total_computation_time'] = sum(stats['computation_times'])
        
        stats['cache_hit_rate'] = stats['cache_hits'] / (stats['cache_hits'] + stats['cache_misses'] + 1e-8)
        
        return stats

class GPUAcceleratedPhysics:
    """
    GPU加速的物理计算模块
    """
    def __init__(self, device=None, optimizer=None):
        self.device = device or Config.DEVICE
        self.optimizer = optimizer or AdvancedGPUOptimizer(device)
        
        # 预分配常用张量
        self._preallocate_tensors()
        
        print(f"[PHYSICS] GPU-accelerated physics initialized")
    
    def _preallocate_tensors(self):
        """
        预分配常用张量以减少运行时分配
        """
        self.temp_tensors = {}
        
        # 常用尺寸的张量
        common_sizes = [
            (OPTIMAL_BATCH_SIZE, 3),
            (OPTIMAL_BATCH_SIZE, 6, 6),
            (OPTIMAL_BATCH_SIZE, 70),
            (OPTIMAL_BATCH_SIZE, 4, 4)
        ]
        
        for size in common_sizes:
            key = str(size)
            self.temp_tensors[key] = torch.zeros(*size, device=self.device)
    
    def get_temp_tensor(self, size):
        """
        获取临时张量
        """
        key = str(size)
        if key in self.temp_tensors:
            tensor = self.temp_tensors[key]
            if tensor.shape == size:
                return tensor.zero_()
        
        # 分配新的临时张量
        tensor = torch.zeros(*size, device=self.device)
        self.temp_tensors[key] = tensor
        return tensor
    
    def accelerated_ricci_computation(self, metric_tensor):
        """
        GPU加速的里奇标量计算
        """
        # 使用延迟操作
        def compute_ricci_chunk(metric_chunk):
            # 简化的里奇标量计算
            batch_size = metric_chunk.shape[0]
            ricci = torch.zeros(batch_size, device=self.device)
            
            for i in range(batch_size):
                g = metric_chunk[i]
                # 计算逆度规
                try:
                    g_inv = torch.inverse(g)
                    # 计算里奇标量 (简化版本)
                    ricci[i] = torch.trace(g_inv @ g) - 6  # 6是维度
                except:
                    ricci[i] = 0.0
            
            return ricci
        
        # 分块计算
        return self.optimizer.chunked_computation(
            metric_tensor, compute_ricci_chunk, self.optimizer.chunk_size
        )
    
    def accelerated_force_computation(self, positions, density):
        """
        GPU加速的力场计算 — Multi-GPU distributed version
        将 O(n²) N-body 计算分布到所有可用 GPU（4×RTX4000）
        """
        n_particles = positions.shape[0]
        device_main = self.device
        
        # Free memory before computation
        torch.cuda.empty_cache()
        for gpu_id in range(torch.cuda.device_count()):
            with torch.cuda.device(gpu_id):
                torch.cuda.empty_cache()
        
        # Multi-GPU chunked computation — 始终使用多GPU（移除 n_particles<2000 限制）
        num_gpus = torch.cuda.device_count()
        if num_gpus < 2:
            # 真·单GPU：chunked计算避免O(n²)全矩阵
            chunk_size = min(256, max(64, n_particles // 10))
            forces = torch.zeros(n_particles, 3, device=device_main, dtype=positions.dtype)
            for i in range(0, n_particles, chunk_size):
                end_i = min(i + chunk_size, n_particles)
                # 小批次避免OOM
                sub_chunk = 128
                force_sum = torch.zeros(end_i - i, 3, device=device_main, dtype=positions.dtype)
                for j in range(0, n_particles, sub_chunk):
                    end_j = min(j + sub_chunk, n_particles)
                    pos_i = positions[i:end_i]
                    pos_j = positions[j:end_j]
                    den_i = density[i:end_i]
                    dist_ij = torch.cdist(pos_i, pos_j, p=2)
                    mag_ij = den_i.unsqueeze(1) / (dist_ij + 1e-6)**2
                    diff_ij = pos_i.unsqueeze(1) - pos_j.unsqueeze(0)
                    dir_ij = diff_ij / (dist_ij.unsqueeze(-1) + 1e-6)
                    force_sum += torch.sum(mag_ij.unsqueeze(-1) * dir_ij, dim=1)
                    del dist_ij, mag_ij, diff_ij, dir_ij
                forces[i:end_i] = force_sum
                del force_sum
                if i % (chunk_size * 5) == 0:
                    torch.cuda.empty_cache()
        else:
            # 多GPU：将粒子分片到各GPU，每个GPU只算自己的chunk vs 全量
            forces = torch.zeros(n_particles, 3, device=device_main, dtype=positions.dtype)
            chunk_size = (n_particles + num_gpus - 1) // num_gpus
            
            # 先将全量positions放到CPU（节省GPU 0显存）
            pos_cpu = positions.cpu()
            den_cpu = density.cpu()
            
            for gpu_id in range(num_gpus):
                start_i = gpu_id * chunk_size
                end_i = min(start_i + chunk_size, n_particles)
                if start_i >= n_particles:
                    break
                
                # 每个GPU只加载自己的chunk
                pos_chunk_cpu = pos_cpu[start_i:end_i]
                den_chunk_cpu = den_cpu[start_i:end_i]
                
                with torch.cuda.device(gpu_id):
                    # 流式迁移：先放chunk，再放全量
                    pos_chunk = pos_chunk_cpu.to(f'cuda:{gpu_id}')
                    den_chunk = den_chunk_cpu.to(f'cuda:{gpu_id}')
                    pos_full = pos_cpu.to(f'cuda:{gpu_id}')
                    
                    # 计算该chunk对全量粒子的力
                    dist_chunk = torch.cdist(pos_chunk, pos_full, p=2)
                    mag_chunk = den_chunk.unsqueeze(1) / (dist_chunk + 1e-6)**2
                    pos_diff_chunk = pos_chunk.unsqueeze(1) - pos_full.unsqueeze(0)
                    dir_chunk = pos_diff_chunk / (dist_chunk.unsqueeze(-1) + 1e-6)
                    force_part = torch.sum(mag_chunk.unsqueeze(-1) * dir_chunk, dim=1)
                    forces[start_i:end_i] = force_part.to(device_main)
                    
                    del pos_chunk, den_chunk, pos_full
                    del dist_chunk, mag_chunk, pos_diff_chunk, dir_chunk, force_part
                    torch.cuda.empty_cache()
            
            del pos_cpu, den_cpu
        
        # Avoid self-interaction
        forces[torch.arange(n_particles, device=device_main)] = 0.0
        return forces
    
    def lazy_topology_analysis(self, positions):
        """
        延迟拓扑分析
        """
        def compute_topology_lazy(positions_chunk):
            # 延迟操作，稍后执行
            return self.optimizer.lazy_tensor_operation(
                self._compute_topology_chunk, positions_chunk
            )
        
        # 返回延迟操作对象而不是直接计算
        return self.optimizer.lazy_tensor_operation(
            self._compute_topology_chunk, positions
        )
    
    def _compute_topology_chunk(self, positions_chunk):
        """
        计算拓扑分块
        """
        # 简化的拓扑分析
        n_points = positions_chunk.shape[0]
        if n_points < 3:
            return {"betti_numbers": [1, 0, 0], "persistence_entropy": 0.0}
        
        # GPU距离计算
        dist_matrix = torch.cdist(positions_chunk, positions_chunk, p=2)
        
        # 动态阈值
        threshold = torch.quantile(dist_matrix, 0.1)
        adjacency = (dist_matrix < threshold).float()
        
        # 连通分量估计
        betti_0 = torch.trace(adjacency).int().item()
        
        return {
            "betti_numbers": [betti_0, 0, 0],
            "persistence_entropy": 0.0
        }

