        print(f"      Lie algebra created with {len(sl6c.generators)} generators")
        
        # 测试 chi 向量
        print("2. 创建测试 chi 向量...")
        chi = torch.randn(70, device=Config.DEVICE, dtype=Config.DTYPE) * 0.1
        print(f"   Created test chi vector: shape {chi.shape}")
        
        # 测试势能计算
        print("3. 测试势能计算...")
        V = sl6c.compute_casimir_potential(chi)
        print(f"   Potential computed: {V.item():.6f}")
        
        # 测试度规计算
        print("4. 测试度规计算...")
        metric = sl6c.get_metric(chi)
        print(f"   Metric computed: shape {metric.shape}")
        
        # 测试 Hessian 计算（可能很慢）
        print("5. 测试 Hessian 计算...")
        try:
            H = sl6c.compute_potential_hessian(chi)
            print(f"   Hessian computed: shape {H.shape}")
        except Exception as e:
            print(f"   Hessian computation failed: {e}")
            # 使用简化的 Hessian
            H = torch.eye(70, device=Config.DEVICE, dtype=Config.DTYPE) * 0.01
            print(f"   Using simplified Hessian: shape {H.shape}")
        
        # 测试积分器
        print("6. 测试积分器...")
        cfg = Config()
        integrator = StochasticFlowIntegrator(cfg, sl6c)
        
        # 测试 riccati_step
        A = torch.eye(70, device=cfg.DEVICE, dtype=cfg.DTYPE) * 0.01
        A_new = integrator.riccati_step(A, H, cfg.DT)
        print(f"   Riccati step successful: A_new shape {A_new.shape}")
        
        # 测试 langevin_step
        drift = torch.randn(70, device=cfg.DEVICE, dtype=cfg.DTYPE) * 0.01
        chi_new = integrator.langevin_step(chi, A, drift, cfg.DT)
        print(f"   Langevin step successful: chi_new shape {chi_new.shape}")
        
        print("=== 所有测试通过 ===")
        
        # 运行主程序
        main()
        
